INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ef0f27-f300-4150-934f-b4b735d807ad', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十五', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["風衣起（京本作「動」），晝則不聞聲。","寇賊夜行明則伏，遣人窺（辛本、川本作「探」）視（京本作「伺候」）莫教停，防備夜偷營。"]', '["风衣起（京本作「动」），晝則不闻声。","寇賊夜行明則伏，遣人窺（辛本、川本作「探」）視（京本作「伺候」）莫教停，防備夜偷營。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d814b6d-8baf-463a-b4a0-b8004dc0eb1b', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十六', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["邦（京本作「郡」）與邑，風猛似雷聲。","折木飛沙幷（京本作「兼」）走石，搖門拔戶禍應生，第一怕三刑。","（京本注：「寅申己亥辰戌丑未之類。","」）。"]', '["邦（京本作「郡」）與邑，风猛似雷声。","折木飞沙幷（京本作「兼」）走石，搖门拔戶禍應生，第一怕三刑。","（京本注：「寅申己亥辰戌丑未之類。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af9a195-8dda-4730-ac70-b0509bba2ae4', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十七', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，風猛突然來。","若在歲刑憂歲內，月刑之內必爲灾，准備莫遲回。"]', '["軍營內，风猛突然来。","若在歲刑憂歲內，月刑之內必爲灾，准備莫遲回。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c34d7a-045b-4f5d-80db-c30bb5566490', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十八', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["乾與坎，艮震巽離宮。","坤兌八方真正位，敵軍（京本作「人」）居守起方風，狂（辛本、川本、京本作「枉」）戰我無[功]（攻）（據辛本、川本、京本改。","）。"]', '["乾與坎，艮震巽離宮。","坤兌八方真正位，敵軍（京本作「人」）居守起方风，狂（辛本、川本、京本作「枉」）戰我無[功]（攻）（據辛本、川本、京本改。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80737bb6-93b8-4d20-8303-e687f185a032', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十九', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["吾攻彼，審令看風情。","令不順方兵（辛本、川本、京本作「吾」）莫（京本作「可」）撃，風如（京本作「仍」）順我必攻城（京本件「成」），降虜出前迎。"]', '["吾攻彼，審令看风情。","令不順方兵（辛本、川本、京本作「吾」）莫（京本作「可」）撃，风如（京本作「仍」）順我必攻城（京本件「成」），降虜出前迎。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb24699d-54e1-4c99-bd1d-4b7d8d9df87f', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營下畢，風卒似雷聲。","吹倒鎗旗幷（辛本、川本、京本作「旗鎗飄」）帳幕，須防敵騎欲偷（辛本、川本作「棄」、京本作「奪」）營，大戰血交幷。","（天風起，有雷聲吼，三朝五日同。","）。"]', '["營下畢，风卒似雷声。","吹倒鎗旗幷（辛本、川本、京本作「旗鎗飄」）帳幕，須防敵騎欲偷（辛本、川本作「棄」、京本作「奪」）營，大戰血交幷。","（天风起，有雷声吼，三朝五日同。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20955656-8d03-4e64-bf43-77e9c69c05b9', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十一', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，風卒亂（辛本、京本作「突」）軍旗。","人馬驚奔皆恐懼（京本作「悸恐」），前程必有廟堂期（京本作「基」），祭拜免灾危。"]', '["兵行次，风卒亂（辛本、京本作「突」）軍旗。","人马驚奔皆恐懼（京本作「悸恐」），前程必有廟堂期（京本作「基」），祭拜免灾危。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b090fd-86ff-4558-88e5-eca082178477', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十二', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次（京本作「處」），風向後飄（京本作「頭」）來。","旗幟翩翩吹向敵（京本作「從敵上」），天威默助凱歌回，賊敗息（京本作「悉」）塵埃。"]', '["臨陣次（京本作「处」），风向後飄（京本作「头」）来。","旗幟翩翩吹向敵（京本作「從敵上」），天威默助凱歌回，賊敗息（京本作「悉」）塵埃。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4587105-a4e7-4d84-8ae7-cac6bf13cd6e', '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十三', '兵要望江南 风角第二（辛本作「占风角第二」、京本作「占风第三」。三十三首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次（京本作「處」），風起四維間。","兵近塞（京本作「寨」）邊先備敵，更（辛本、京本作「便」）從豹尾撃黃幡。","殺敵（京本作「賊」）不爲難。"]', '["臨陣次（京本作「处」），风起四維间。","兵近塞（京本作「寨」）邊先備敵，更（辛本、京本作「便」）從豹尾撃黄幡。","殺敵（京本作「賊」）不爲难。"]', '诗', 'shi', '', NULL, '兵要望江南 風角第二（辛本作「占風角第二」、京本作「占風第三」。三十三首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e852fd25-d81c-4180-b29a-66472c692ab7', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 一', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵若進，先（辛本、京本作「須」）要（京本作「是」）識浮雲。","雲氣順時（京本作「隨」）當急（京本作「速」）戰，毋（京本作「勿」）令雲散後交兵，莫問晝陰晴。"]', '["兵若進，先（辛本、京本作「須」）要（京本作「是」）識浮云。","云氣順时（京本作「隨」）當急（京本作「速」）戰，毋（京本作「勿」）令云散後交兵，莫问晝陰晴。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128d8bb1-efe5-4205-a3be-b2a3720fa296', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["商音姓，軍陣見[雲從]（從營）（從辛本、京本改。","）白與黑時（京本作「兮」）吾大吉，青雲亦（京本作「主」）勝赤雲凶，黃者兩平蹤。","（辛本注：「主取天子姓，不主出帥姓。","」京本注：「天子出，取天子姓，不出則以主將。","」）。"]', '["商音姓，軍陣见[云從]（從營）（從辛本、京本改。","）白與黑时（京本作「兮」）吾大吉，青云亦（京本作「主」）勝赤云凶，黄者兩平蹤。","（辛本注：「主取天子姓，不主出帥姓。","」京本注：「天子出，取天子姓，不出則以主將。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32585424-8dbb-4498-9e12-31a17756b6b2', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 三', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["角音姓，青氣見（辛本作「寓」）晴空。","黃赤二雲軍（京本作「兵」）亦勝，黑雲陰助喜先鋒，白色定爲凶。"]', '["角音姓，青氣见（辛本作「寓」）晴空。","黄赤二云軍（京本作「兵」）亦勝，黑云陰助喜先鋒，白色定爲凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e7ec5d6-d38e-4c6e-bafe-85a7b9929b7b', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 四', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["宮音姓，黃色（京本作「赤」）要先逢。","青色氣（京本作「雲」）來軍大敗，更兼兵死將無功，黑氣利先攻（京本作「鋒」）。"]', '["宮音姓，黄色（京本作「赤」）要先逢。","青色氣（京本作「云」）来軍大敗，更兼兵死將無功，黑氣利先攻（京本作「鋒」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c310e938-13b3-468a-a989-8535710eec49', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 五', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["徴音姓，赤色火燒金。","非火（京本作「是」）剋金成大器，青雲（京本作「贏」）黃助黑雲凶（辛本作「白雲黑氣現黃雲」）。","軍將禍（京本作「盡」）殃深。"]', '["徴音姓，赤色火燒金。","非火（京本作「是」）剋金成大器，青云（京本作「贏」）黄助黑云凶（辛本作「白云黑氣現黄云」）。","軍將禍（京本作「尽」）殃深。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223e7f38-b662-4347-b2f5-7c2e770a6da4', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 六', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["羽音姓，惟是（辛本作「事」）要青（京本作「黑雲」）青，列陣賊來先自（京本作「是」）走，赤黃白黑（京本作「赤雲遍處」）總非贏，宜退（京本作「去」）不宜征。"]', '["羽音姓，惟是（辛本作「事」）要青（京本作「黑云」）青，列陣賊来先自（京本作「是」）走，赤黄白黑（京本作「赤云遍处」）總非贏，宜退（京本作「去」）不宜征。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2e6c87-2762-4d04-8bdd-4a2e4e6c18cd', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 七', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲起處（京本作「氣至」），形色（辛本、川本作「行色」）重而烏。","暗伏賊兵（京本作「師」）軍不見，露其形體（京本作「體象」）在高隅，一半是番胡。","。"]', '["云起处（京本作「氣至」），形色（辛本、川本作「行色」）重而烏。","暗伏賊兵（京本作「師」）軍不见，露其形體（京本作「體象」）在高隅，一半是番胡。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21fa859-ae31-4ebb-b36f-c9fa2060de6c', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 八', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲起處（京本作「氣至」），低覆似人形。","此是賊軍（辛本作「兵」）謀我象（京本作「重」），須防入境起征凶（京本作「凶征」），遣將用精兵。"]', '["云起处（京本作「氣至」），低覆似人形。","此是賊軍（辛本作「兵」）謀我象（京本作「重」），須防入境起征凶（京本作「凶征」），遣將用精兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540c2b33-83d5-48e5-89d9-bafe658d5aa0', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 九', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲似虎，或若豹行形（京本作「形行」）。","及似穿連走匹練（首本注：「一作驄」。","辛本、川本作「絹」）。","暴師入境却偷營，排（京本作「摆」）陣整兵迎。"]', '["云似虎，或若豹行形（京本作「形行」）。","及似穿連走匹練（首本注：「一作驄」。","辛本、川本作「絹」）。","暴師入境却偷營，排（京本作「摆」）陣整兵迎。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c3fbad-d7a2-4aeb-853c-9f72fa6d3e37', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["四方現，雲色（京本作「氣」）競腾過。","黯淡相親（京本作「侵」）來我寨，賊來請命未爲和，賢將莫蹉跎。"]', '["四方現，云色（京本作「氣」）競腾過。","黯淡相親（京本作「侵」）来我寨，賊来請命未爲和，賢將莫蹉跎。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b09894-b618-4465-a493-e5899148cba6', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十一', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲起現，片片或舒長。","有似舒繩排椽木，名爲愁氣不相當，現處將憂喪。"]', '["云起現，片片或舒长。","有似舒繩排椽木，名爲愁氣不相當，現处將憂喪。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c3fc33-44b2-4db1-9fa9-70e25deed05f', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十二', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲氣赤，尤更接連綿。","有似成長藤無（京本作「幷」）斷續，外邦賊起入（京本作「及」）中原，主戰在秋天（京本作「前」）。"]', '["云氣赤，尤更接連綿。","有似成长藤無（京本作「幷」）斷續，外邦賊起入（京本作「及」）中原，主戰在秋天（京本作「前」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191c2ecc-54e3-4c3c-ae68-8f93de7c45ae', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十三', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲氣赤，那更滿蒼（京本作「青」）天。","必定賊來侵我界，黑雲中赤亦徒然，吾將必（京本作「莫」）遷延。"]', '["云氣赤，那更满蒼（京本作「青」）天。","必定賊来侵我界，黑云中赤亦徒然，吾將必（京本作「莫」）遷延。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b59efa1-3b80-47d0-8452-d5921088ff86', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十四', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雲來往，有似兩[爭龍]（龍爭）（從辛本、川本改，京本作「兩條龍」）。","只在外軍盤頂上，賊邦兵將必逢凶，我帥顯英雄。"]', '["云来往，有似兩[爭龙]（龙爭）（從辛本、川本改，京本作「兩條龙」）。","只在外軍盤頂上，賊邦兵將必逢凶，我帥显英雄。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330a9757-9a93-41c3-9373-4afe3a40a4eb', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十五', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍似鳥，盤繞在其（京本作「軍」）中。","此時（京本作「是」）上方天（京本作「蒼加」）助順，不宜復見黑雲峰，連赤亦爲凶。"]', '["軍似鸟，盤繞在其（京本作「軍」）中。","此时（京本作「是」）上方天（京本作「蒼加」）助順，不宜复见黑云峰，連赤亦爲凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d8bcdd-4a0d-48f4-ac5a-5b90563fb73c', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十六', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["甲乙日，大（辛本、川本作「將」）忌白雲前。","若奔吾軍還勢急，理當速退（京本作「去」）捨平川，守固在（京本作「固守險」）高原。"]', '["甲乙日，大（辛本、川本作「將」）忌白云前。","若奔吾軍還勢急，理當速退（京本作「去」）捨平川，守固在（京本作「固守險」）高原。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e06652d-5b32-487e-b9da-9615e2968115', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十七', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["丙丁日，若（京本作「前」）遇黑雲攔（辛本、川本作「閑」）。","莫恃兵多兼將勇，也宜堅守（京本作「壁」）引師還。","征戰（京本作「伐」）必遭[殘]（殃）（從京本改）。"]', '["丙丁日，若（京本作「前」）遇黑云攔（辛本、川本作「闲」）。","莫恃兵多兼將勇，也宜堅守（京本作「壁」）引師還。","征戰（京本作「伐」）必遭[殘]（殃）（從京本改）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('040b43c4-4252-461f-8242-4d80f517a099', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十八', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["戊己日，前面有雲青。","忽止忽行權且住（辛本、川本作「急止匆行權住在」，京本作「急止勿行權住寨」，似以京本爲長），軍人訛（辛本、川本作「須」）語審詳聽，施德惠於（京本作「其」）兵（辛本、川本作「施惠得中旌」）。"]', '["戊己日，前面有云青。","忽止忽行權且住（辛本、川本作「急止匆行權住在」，京本作「急止勿行權住寨」，似以京本爲长），軍人訛（辛本、川本作「須」）語審詳听，施德惠於（京本作「其」）兵（辛本、川本作「施惠得中旌」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0fbb80-5700-459a-90d3-655f488b8699', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十九', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["庚辛日，前忌赤雲來。","勢緊迫（京本作「迎」）吾須大戰，彼軍得勝我軍摧，守險固顛危。","（過旬〖京本作「日」〗中却行）。"]', '["庚辛日，前忌赤云来。","勢緊迫（京本作「迎」）吾須大戰，彼軍得勝我軍摧，守險固顛危。","（過旬〖京本作「日」〗中却行）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5a7e49-0867-4350-ae13-7593ccfc673b', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["壬癸日，雲忌暗（京本作「色」）而黃。","此兆主灾軍（京本作「兵」）將損（辛本、川本作「迎老將」），無緣兵廣恣猖狂，謀者審（京本作「貴密」）而詳。"]', '["壬癸日，云忌暗（京本作「色」）而黄。","此兆主灾軍（京本作「兵」）將損（辛本、川本作「迎老將」），無緣兵廣恣猖狂，謀者審（京本作「貴密」）而詳。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c69b7d-798c-43d7-a887-b4a3873c44e2', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十一', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["[觀]（現）（從辛本、京本改）雲氣，擇士細詳（京本作「汝當」）看。","晝夜[用]（同）（從辛本改）心精審究（京本作「却須精細審」），莫將此事以（京本作「擬」）爲閑，風色便（辛本作「辨」，京本作「旺」）相干。"]', '["[观]（現）（從辛本、京本改）云氣，擇士細詳（京本作「汝當」）看。","晝夜[用]（同）（從辛本改）心精審究（京本作「却須精細審」），莫將此事以（京本作「擬」）爲闲，风色便（辛本作「辨」，京本作「旺」）相干。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fedee86a-f555-499c-91e2-ee7484c724cf', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十二', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營上，雲若似飛烏。","有似盖來幷伏虎，此爲勝氣不須疑，攻則定疎虞。"]', '["軍營上，云若似飞烏。","有似盖来幷伏虎，此爲勝氣不須疑，攻則定疎虞。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b576c18-6f98-4b63-bc6b-3e128eca6e54', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十三', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營上，雲若死灰揚。","若似（辛本、川本作「盖」）臥魚或乍見，此爲衰氣不須張，不動將兵（辛本、川本作「軍」）亡。","（移寨遠處吉。","）。"]', '["軍營上，云若死灰揚。","若似（辛本、川本作「盖」）臥鱼或乍见，此爲衰氣不須張，不动將兵（辛本、川本作「軍」）亡。","（移寨远处吉。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed997bb-6b1e-4066-8fb8-a5139624dc05', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十四', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城頭上，突出赤色雲。","或是黃紅雲上現，城中不久喜來臻，以此得和平。"]', '["城头上，突出赤色云。","或是黄紅云上現，城中不久喜来臻，以此得和平。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204ee8e7-7094-4b79-8539-06653309ea73', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十五', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占候法，雞羽作爲車。","二者勿惟牙帳內，敵人千里外須圖，知辨在須臾。"]', '["占候法，雞羽作爲车。","二者勿惟牙帳內，敵人千里外須圖，知辨在須臾。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6de7054-5f2b-4d1c-af17-77a799fb2033', '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十六', '兵要望江南 占云第三（京本作「占云第二十四○二十六首」） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍善，識得氣妖祥。","風角鳥占能總解，心無機巧計從長，報國效忠良。","（既有其象，當隨其景，就謀術，以破其軍。","）（按：以上二首據京本補，首本等入《占氣第四》，稍異。","）。"]', '["將軍善，識得氣妖祥。","风角鸟占能總解，心無機巧計從长，報国效忠良。","（既有其象，當隨其景，就謀術，以破其軍。","）（按：以上二首據京本補，首本等入《占氣第四》，稍異。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雲第三（京本作「占雲第二十四○二十六首」） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85878ab8-60b8-4782-b771-175dd99823b2', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 一', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占氣色（辛本作「法」），雞羽爲輪車。","二者勿離牙帳內，敵人千里外須知，圖變在須臾。"]', '["占氣色（辛本作「法」），雞羽爲輪车。","二者勿離牙帳內，敵人千里外須知，圖变在須臾。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b88e51-e2d2-4e92-b013-67ebb9518d17', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍既舉，惟以氣爲先。","兵若精雄加氣銳，超關投石可攻前，鼓作在英賢。"]', '["軍既舉，惟以氣爲先。","兵若精雄加氣銳，超关投石可攻前，鼓作在英賢。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fdd6603-5605-4a75-b55c-849c014278a0', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍善（一作「位」），識得（一作「善識」）氣妖祥。","風角鳥雲能總解，機[籌]（策）謀略[又]（應）（均從辛本改）相當，取勝應功良（一作「征討又功強」）。","（按：此首又重見于「觀氣色」一首之後，今刪去，異文注爲「一作」。","）。"]', '["將軍善（一作「位」），識得（一作「善識」）氣妖祥。","风角鸟云能總解，機[籌]（策）謀略[又]（應）（均從辛本改）相當，取勝應功良（一作「征討又功強」）。","（按：此首又重见于「观氣色」一首之後，今刪去，異文注爲「一作」。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fab689-1c0d-4b82-baa8-7e23881c0532', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 四', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍（辛本、川本、京本作「兵」）進撃，覩（京本作「觀」）氣合參詳。","不似（京本作「必」）攻城幷野戰，度其形狀自（京本作「細」）斟量，稍錯便乖張。"]', '["軍（辛本、川本、京本作「兵」）進撃，覩（京本作「观」）氣合參詳。","不似（京本作「必」）攻城幷野戰，度其形狀自（京本作「細」）斟量，稍錯便乖張。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d8a363-cd5d-4f6b-a678-98e5f141c928', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 五', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，氣似鳳（京本作「似鳳或」）如龍。","更若大（京本作「太」）山幷類蓋，猶如（辛本作「人」）火（京本作「人大」）赤降城中，其下不堪攻。","（下必有貴人。","）。"]', '["城營內，氣似鳳（京本作「似鳳或」）如龙。","更若大（京本作「太」）山幷類蓋，猶如（辛本作「人」）火（京本作「人大」）赤降城中，其下不堪攻。","（下必有貴人。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6775560a-fe53-47cb-abd3-576d3577b96e', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 六', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["高空現，拂拂又微微。","透闕（京本作「秀潤」）輕籠煙靉靉，一般黃氣色依依，慶賀兩朝期。"]', '["高空現，拂拂又微微。","透闕（京本作「秀潤」）轻籠煙靉靉，一般黄氣色依依，慶賀兩朝期。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e7af64-bc20-4f82-bc61-64a4a63eb858', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 七', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛將氣，龍虎兩（京本作「氣」）兩連。","掛翳蔽天兼掠地，蔓瓜蓋路（京本作「地」）覆平川，堅守莫爭先。"]', '["猛將氣，龙虎兩（京本作「氣」）兩連。","掛翳蔽天兼掠地，蔓瓜蓋路（京本作「地」）覆平川，堅守莫爭先。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd1d8010-4e65-48b7-9343-1ce47231f5f9', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 八', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛將氣，樓閣及旌幢。","或似長堤形淼淼，更如華（京本作「兵」）蓋與王良（京本作「蟲狼」），其下莫能當。"]', '["猛將氣，楼閣及旌幢。","或似长堤形淼淼，更如华（京本作「兵」）蓋與王良（京本作「蟲狼」），其下莫能當。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9ce01d-6317-4365-9ca1-e1aa7544852c', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 九', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛將氣，黑色似龍形。","或似（辛本、川本、京本作「類」）虎形（京本作「熊」）幷猛獸，當（京本作「形」）其敵上或城營，不可向前征。"]', '["猛將氣，黑色似龙形。","或似（辛本、川本、京本作「類」）虎形（京本作「熊」）幷猛獸，當（京本作「形」）其敵上或城營，不可向前征。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94fdeaf2-0211-41f1-b123-9a98f73b18b6', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛將氣，顯赫（京本作「象」）又衝天。","或似雙蛇山岳（辛本、川本作「兵」）樣，又如倉廩及濃烟，休戰最爲先。","。"]', '["猛將氣，显赫（京本作「象」）又衝天。","或似雙蛇山岳（辛本、川本作「兵」）樣，又如倉廩及濃烟，休戰最爲先。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad32cda-c272-448d-b41d-49c571299ed5', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十一', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛將氣，持戟（京本作「戈」）又（辛本、川本、京本作「或」）持刀。","林下森森弓弩樣，色兼青白若脂膏，將士盡雄豪。"]', '["猛將氣，持戟（京本作「戈」）又（辛本、川本、京本作「或」）持刀。","林下森森弓弩樣，色兼青白若脂膏，將士尽雄豪。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68dbeea2-3143-43a4-91aa-5d18d188c1aa', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十二', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["猛將氣，如虎黑霞遮。","或似門樓旗立內，又如氣出若蛟蛇，其下將堪誇。"]', '["猛將氣，如虎黑霞遮。","或似门楼旗立內，又如氣出若蛟蛇，其下將堪誇。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7674abc6-bbd9-43cd-a88e-b4fd94eef592', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十三', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["暴兵氣，如火又如烟。","或似旗{旛巾=方}幷戰（京本作「五」）馬，低頭仰（京本作「傾」）[尾]（面）（從辛本、川本、京本改）向軍前（京本作「前軍」），觸戰血成川。"]', '["暴兵氣，如火又如烟。","或似旗{旛巾=方}幷戰（京本作「五」）马，低头仰（京本作「傾」）[尾]（面）（從辛本、川本、京本改）向軍前（京本作「前軍」），觸戰血成川。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d424b3f-89d8-4f5b-a7fa-fb1896ef0468', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十四', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["伏兵氣，渾渾又能圓。","黑（京本作「赤」）氣中間環赤色（辛本、川本作「色」，京本作「含黑氣」），又如赤杵黑霞連（京本作「邊」），其下立戈鋋。","（狀如赤杵在黑氣中[也]）（據京本補）。"]', '["伏兵氣，渾渾又能圓。","黑（京本作「赤」）氣中间环赤色（辛本、川本作「色」，京本作「含黑氣」），又如赤杵黑霞連（京本作「邊」），其下立戈鋋。","（狀如赤杵在黑氣中[也]）（據京本補）。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6773e2e7-f7ec-4394-88af-93b95d6cfdbf', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十五', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["降兵氣，叉手盡低頭。","形似成行相把手，三朝五日敵兵（辛本、川本、京本作「來」）求，指日倒戈矛。"]', '["降兵氣，叉手尽低头。","形似成行相把手，三朝五日敵兵（辛本、川本、京本作「来」）求，指日倒戈矛。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22abf99-faa6-424f-8e53-7f1433eca1fb', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十六', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["降兵氣，髣髴狀如樓。","兼有似人形黑赤，或如（京本作「如逢」）山岳立（辛本、川本、京本作「覆」）崗丘（京本作「頭」），其下有戈矛。"]', '["降兵氣，髣髴狀如楼。","兼有似人形黑赤，或如（京本作「如逢」）山岳立（辛本、川本、京本作「覆」）崗丘（京本作「头」），其下有戈矛。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502c990d-a912-4b6b-8414-71ef7d9c9af0', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十七', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發（京本作「發兵」）日，天氣久陰沉。","不雨又無光彩色，奸人謀事（京本作「士」）恨懷心，仔細速（京本作「早」）推尋。"]', '["兵發（京本作「發兵」）日，天氣久陰沉。","不雨又無光彩色，奸人謀事（京本作「士」）恨懷心，仔細速（京本作「早」）推尋。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52c81b0-bcd8-47b0-b677-8fce834d65b2', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十八', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["[觀]（現）（從京本、辛本、川本改）氣色，日月氣來衝。","北面氣來還北壯，氣南南壯或西東，常（京本作「俱」）以此爲宗。"]', '["[观]（現）（從京本、辛本、川本改）氣色，日月氣来衝。","北面氣来還北壯，氣南南壯或西东，常（京本作「俱」）以此爲宗。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81236630-a4c7-418e-86e7-6b9830ca61d5', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十九', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城上氣，結似犬羊（京本作「作犬頭」）形。","象主血流圍邑破，好持降類出門迎，方免血（京本作「死」）殘兵。"]', '["城上氣，結似犬羊（京本作「作犬头」）形。","象主血流圍邑破，好持降類出门迎，方免血（京本作「死」）殘兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8378571f-c123-4e6c-8f64-71f7eda02f21', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占蒙氣，鬱鬱達（辛本作「遶」）城營。","其氣周迴如帛遶，分毫不入此城中，休撃此般城。"]', '["占蒙氣，鬱鬱達（辛本作「遶」）城營。","其氣周迴如帛遶，分毫不入此城中，休撃此般城。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c621dceb-bf49-4a2c-98e6-0bbd675942e6', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十一', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營寨，有氣入城中。","必主奸謀事已定，安排大戰奪吾城，謹守令嚴明。"]', '["城營寨，有氣入城中。","必主奸謀事已定，安排大戰奪吾城，謹守令嚴明。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31eff90a-e8d2-4e67-b8f9-adce082ff623', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十二', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍上氣，漸漸變成雲。","或作山形於直上，內中將有大（辛本作「大有將」）機謀，要撃且休休。","。"]', '["軍上氣，漸漸变成云。","或作山形於直上，內中將有大（辛本作「大有將」）機謀，要撃且休休。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e00c92-bc24-414b-b47c-f875801f3959', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十三', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，赤氣後前生。","必有伏兵埋氣下，事[須]（雖）（從辛本、川本改）謹慎探其情，固守莫胡行。"]', '["臨陣次，赤氣後前生。","必有伏兵埋氣下，事[須]（雖）（從辛本、川本改）謹慎探其情，固守莫胡行。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18317edc-f254-4831-96a5-3153101df3e5', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十四', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占敗氣，如綱又如蛇。","赤氣照天營上起，又如破屋壞毡車，其下死如麻。"]', '["占敗氣，如綱又如蛇。","赤氣照天營上起，又如破屋壞毡车，其下死如麻。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5b9b96-6cb0-4d00-adea-9c20496e709e', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十五', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占敗氣，捲（京本作「掃」）帚似猪羊。","藤蔓死蛟幷（京本作「蛇兼」）死狗，塵埃走鹿又（京本作「及」）驚獐，不戰自奔亡。"]', '["占敗氣，捲（京本作「掃」）帚似猪羊。","藤蔓死蛟幷（京本作「蛇兼」）死狗，塵埃走鹿又（京本作「及」）驚獐，不戰自奔亡。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5e9614-4496-44ee-859e-0907105bea1f', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十六', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占敗氣，羣鳥似低頭。","或類揚灰魚臥樣（辛本、京本作「死」），懸鐘映暈或牽牛，纔戰若星流。"]', '["占敗氣，羣鸟似低头。","或類揚灰鱼臥樣（辛本、京本作「死」），懸鐘映暈或牽牛，纔戰若星流。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a4f0bc-8445-4998-bb37-2c77d3b884f2', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十七', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占敗氣，掃（京本作「如」）帚又如虹。","捲席（京本作「鑼鼓」）懸衣灰色樣，臥屍無首覆船同，戰彼不須攻。"]', '["占敗氣，掃（京本作「如」）帚又如虹。","捲席（京本作「鑼鼓」）懸衣灰色樣，臥屍無首覆船同，戰彼不須攻。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d19542-9134-4279-b351-fc99edcdc311', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十八', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["敗軍（京本作「占敗」）氣，鳩尾及鷹（京本作「鸚」）飛。","或似壞山幷破屋，彼軍形（京本作「有」）現敗無疑，一戰自（京本作「纔戰便」）奔馳。"]', '["敗軍（京本作「占敗」）氣，鳩尾及鷹（京本作「鸚」）飞。","或似壞山幷破屋，彼軍形（京本作「有」）現敗無疑，一戰自（京本作「纔戰便」）奔驰。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2612e2-46a9-49fe-b362-96292cf15460', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十九', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["敗軍氣，乍有（京本作「大」）乍微纖（京本作「微」）。","一去一來皆斷續，又如霞氣入青天（京本作「在平田」），俱是敗之先（京本作「亡原」）。"]', '["敗軍氣，乍有（京本作「大」）乍微纖（京本作「微」）。","一去一来皆斷續，又如霞氣入青天（京本作「在平田」），俱是敗之先（京本作「亡原」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b380bf7-87a3-47e5-967d-753efd87ded4', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三十', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["敗軍氣，千萬似人頭。","更有（京本作「似」）偃魚零落樹，如灰（京本作「又如」）瓦礫覆城樓，其下血交流。"]', '["敗軍氣，千万似人头。","更有（京本作「似」）偃鱼零落樹，如灰（京本作「又如」）瓦礫覆城楼，其下血交流。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2140b750-7738-4996-8dd1-157af986ec75', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三十一', '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["黑氣現，其象若胡人。","又似虜兵（京本作「軍」）排列陣，八方夷夏（京本作「狄」）起烟塵，民戮屋燒焚。"]', '["黑氣現，其象若胡人。","又似虜兵（京本作「軍」）排列陣，八方夷夏（京本作「狄」）起烟塵，民戮屋燒焚。"]', '诗', 'shi', '', NULL, '兵要望江南 占氣第四（京本作「占氣第二十三」○三十一首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bef88a68-8749-4f24-a706-150cb6a9a36d', '兵要望江南 占霧第五（京本列第八○十首） 一', '兵要望江南 占霧第五（京本列第八○十首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天霧者，不止四時生。","陽不順時陰成霧，陰不和上霧昏沉（辛本、川本作「昏昏」）。","邪氣事難精。"]', '["天霧者，不止四时生。","陽不順时陰成霧，陰不和上霧昏沉（辛本、川本作「昏昏」）。","邪氣事难精。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cef37f2-c21e-456f-ad7f-90da7b8b4275', '兵要望江南 占霧第五（京本列第八○十首） 二', '兵要望江南 占霧第五（京本列第八○十首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天之霧，五七日當占。","有雨時時且平吉，若無雨時疫瘟纏。","民病有災愆。"]', '["天之霧，五七日當占。","有雨时时且平吉，若無雨时疫瘟纏。","民病有災愆。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e5f336-a5a8-4f75-94ba-a49bb6ce5905', '兵要望江南 占霧第五（京本列第八○十首） 三', '兵要望江南 占霧第五（京本列第八○十首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["相對敵，有霧敵（京本作「客」）邊來。","似雨紛紛來（京本作「須」）勢急，如烟入眼目（京本作「眼」）難開。","馬步一齊（京本作「時」）來。","。"]', '["相对敵，有霧敵（京本作「客」）邊来。","似雨紛紛来（京本作「須」）勢急，如烟入眼目（京本作「眼」）难开。","马步一齊（京本作「时」）来。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e5001a-a109-423a-b567-9d30c38826ae', '兵要望江南 占霧第五（京本列第八○十首） 四', '兵要望江南 占霧第五（京本列第八○十首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，霧氣晝昏昏（京本作「紛紛」）。","一（辛本、川本、京本作「欲」）似露來兼灑（京本作「霧來兼似」）雨，此爲天泣淚（京本作「血」）紛紛，須駐（京本作「駐泊」）賞三軍。"]', '["兵發日，霧氣晝昏昏（京本作「紛紛」）。","一（辛本、川本、京本作「欲」）似露来兼灑（京本作「霧来兼似」）雨，此爲天泣泪（京本作「血」）紛紛，須駐（京本作「駐泊」）賞三軍。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c13885-8ffc-433d-ad69-c62eb2560cdd', '兵要望江南 占霧第五（京本列第八○十首） 五', '兵要望江南 占霧第五（京本列第八○十首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["久陰霧，顏色帶紅鮮。","更被黃（辛本、川本、京本作「黑」）風吹上去，兵戈即日（京本作「目」）展平川，速備（京本作「避」）莫遷延。"]', '["久陰霧，顏色带紅鲜。","更被黄（辛本、川本、京本作「黑」）风吹上去，兵戈即日（京本作「目」）展平川，速備（京本作「避」）莫遷延。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95475ac-f40c-4da5-af35-7ee7365f0840', '兵要望江南 占霧第五（京本列第八○十首） 六', '兵要望江南 占霧第五（京本列第八○十首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營上，有霧似懸屍。","爲將且須觀此象，所居營寨即那（京本作「須」）移。","不去將當之。"]', '["城營上，有霧似懸屍。","爲將且須观此象，所居營寨即那（京本作「須」）移。","不去將當之。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b5f04de-add4-4b4c-8510-173b5e037fab', '兵要望江南 占霧第五（京本列第八○十首） 七', '兵要望江南 占霧第五（京本列第八○十首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，大霧數朝濃（首本作「昏」，從辛本、川本、京本改）。","晝夜不開相對敵，客軍先敗走奔衝，排陣（辛本、川本、京本作「隊」）襲其蹤。"]', '["軍營內，大霧數朝濃（首本作「昏」，從辛本、川本、京本改）。","晝夜不开相对敵，客軍先敗走奔衝，排陣（辛本、川本、京本作「隊」）襲其蹤。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473e24b2-fe52-4649-9287-f6e001e46888', '兵要望江南 占霧第五（京本列第八○十首） 八', '兵要望江南 占霧第五（京本列第八○十首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城（京本作「軍」）營內，大霧起城頭。","白色似（京本作「沙」）烟兵戰起（辛本、川本、京本作「喜」），三朝五日簇戈矛，准備好（京本作「防備外」）方遊。"]', '["城（京本作「軍」）營內，大霧起城头。","白色似（京本作「沙」）烟兵戰起（辛本、川本、京本作「喜」），三朝五日簇戈矛，准備好（京本作「防備外」）方游。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f72f07-85b9-4c9b-8c71-78b4e4f3e300', '兵要望江南 占霧第五（京本列第八○十首） 九', '兵要望江南 占霧第五（京本列第八○十首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["大（京本作「青」）黃霧，騰{曰/卓}（京本作「勝氣」）掩山川。","乍合乍開防詐僞，須防內外有（京本作「與外」）相連，不悟血侵（京本作「浸」）田。"]', '["大（京本作「青」）黄霧，腾{曰/卓}（京本作「勝氣」）掩山川。","乍合乍开防詐僞，須防內外有（京本作「與外」）相連，不悟血侵（京本作「浸」）田。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2789fc-874d-490a-9a4a-a105ec4f18c3', '兵要望江南 占霧第五（京本列第八○十首） 十', '兵要望江南 占霧第五（京本列第八○十首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["周迴霧，城內沒些兒。","欲要攻城攻不得，其城天助有軍威，謹守自安宜。"]', '["周迴霧，城內沒些兒。","欲要攻城攻不得，其城天助有軍威，謹守自安宜。"]', '诗', 'shi', '', NULL, '兵要望江南 占霧第五（京本列第八○十首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9853c522-724c-4606-8100-24d675eea285', '兵要望江南 占霞第六（京本列第二十六○十一首） 一', '兵要望江南 占霞第六（京本列第二十六○十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占霞色，似氣不相成。","形若似雲雲不是，形如拖掃氣紛紛，識者自詳因。"]', '["占霞色，似氣不相成。","形若似云云不是，形如拖掃氣紛紛，識者自詳因。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56577629-1041-4f9c-a848-5b1e399811c0', '兵要望江南 占霞第六（京本列第二十六○十一首） 二', '兵要望江南 占霞第六（京本列第二十六○十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，占顧（京本作「看」）面前霞。","甲乙怕逢霞氣白，丙丁黑氣向前遮，大戰不應差（京本作「定交加」）。"]', '["兵發日，占顧（京本作「看」）面前霞。","甲乙怕逢霞氣白，丙丁黑氣向前遮，大戰不應差（京本作「定交加」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee0b974-0039-47ef-b2f2-b9df8bbbdf94', '兵要望江南 占霞第六（京本列第二十六○十一首） 三', '兵要望江南 占霞第六（京本列第二十六○十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，霞氣日辰幷（辛本、川本作「兵」）。","縱有前程應（京本作「勿」）大戰，逢霞生日應須贏，拗日不宜（京本作「須」）征（辛本、川本作「多精」。","甲乙日黃、戊己日黑之類）。"]', '["兵發日，霞氣日辰幷（辛本、川本作「兵」）。","縱有前程應（京本作「勿」）大戰，逢霞生日應須贏，拗日不宜（京本作「須」）征（辛本、川本作「多精」。","甲乙日黄、戊己日黑之類）。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96d7fd0b-70e9-476b-9c90-873215e071cf', '兵要望江南 占霞第六（京本列第二十六○十一首） 四', '兵要望江南 占霞第六（京本列第二十六○十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["觀霞氣（辛本、川本作「氣色」），霞氣日辰裁（京本作「諧」）。","兵進前途交戰勝，開疆玉帛積成堆，人馬盡驅來。"]', '["观霞氣（辛本、川本作「氣色」），霞氣日辰裁（京本作「諧」）。","兵進前途交戰勝，开疆玉帛積成堆，人马尽驱来。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfdc79d2-dee0-49a2-b810-e67fe0ad519e', '兵要望江南 占霞第六（京本列第二十六○十一首） 五', '兵要望江南 占霞第六（京本列第二十六○十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，五氣辨灾祥。","角姓怕逢霞氣白，羽音黃氣莫禁（京本作「相」）當，宮姓怕青蒼。"]', '["兵發日，五氣辨灾祥。","角姓怕逢霞氣白，羽音黄氣莫禁（京本作「相」）當，宮姓怕青蒼。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96aa2740-2606-4658-b308-a37a0a0fa811', '兵要望江南 占霞第六（京本列第二十六○十一首） 六', '兵要望江南 占霞第六（京本列第二十六○十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["商音姓，前怕赤霞攔。","徴姓黑霞幷黑氣，皆爲鬼賊怕相殘（京本作「攀」），不得視爲閑。"]', '["商音姓，前怕赤霞攔。","徴姓黑霞幷黑氣，皆爲鬼賊怕相殘（京本作「攀」），不得視爲闲。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d67c71e-70bc-47be-86dd-87fe0e9a3e08', '兵要望江南 占霞第六（京本列第二十六○十一首） 七', '兵要望江南 占霞第六（京本列第二十六○十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營上，五色氣幷霞。","盡是賊（京本作「敗」）軍天預顯，早須爲計好防他（辛本、川本作「警覺較量些」、京本作「警悟較些些」）。","否則死如麻。"]', '["城營上，五色氣幷霞。","尽是賊（京本作「敗」）軍天預显，早須爲計好防他（辛本、川本作「警覺較量些」、京本作「警悟較些些」）。","否則死如麻。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d8c69c-091e-4655-b64a-52df149843b0', '兵要望江南 占霞第六（京本列第二十六○十一首） 八', '兵要望江南 占霞第六（京本列第二十六○十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["霞與氣，二件或相兼。","氣若色黃赤白好，霞如黑色亦（京本作「氣色一」）同占，髣髴在良賢。"]', '["霞與氣，二件或相兼。","氣若色黄赤白好，霞如黑色亦（京本作「氣色一」）同占，髣髴在良賢。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ecb0c6e-7203-42b4-835c-d7d657dad140', '兵要望江南 占霞第六（京本列第二十六○十一首） 九', '兵要望江南 占霞第六（京本列第二十六○十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["霞似虎（辛本作「似席」、京本作「與氣」），雲即便（京本作「變」）爲龍。","龍虎相交軍必戰（川本、辛本作「勝」），臨時勝負更看風（辛本、川本作「辨誰凶」），逐（辛本、川本作「遂」）我彼軍凶。"]', '["霞似虎（辛本作「似席」、京本作「與氣」），云即便（京本作「变」）爲龙。","龙虎相交軍必戰（川本、辛本作「勝」），臨时勝負更看风（辛本、川本作「辨誰凶」），逐（辛本、川本作「遂」）我彼軍凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d376c9-62bc-44c5-90d8-190fb3e65cf8', '兵要望江南 占霞第六（京本列第二十六○十一首） 十', '兵要望江南 占霞第六（京本列第二十六○十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["出軍日，霞氣莫前攔。","我後氣來風更順，從他前銳後寬嚴（辛本、川本作「寬」），軍馬獲平安。"]', '["出軍日，霞氣莫前攔。","我後氣来风更順，從他前銳後寬嚴（辛本、川本作「寬」），軍马獲平安。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1479cf-6f49-4175-891d-d20680aacd0c', '兵要望江南 占霞第六（京本列第二十六○十一首） 十一', '兵要望江南 占霞第六（京本列第二十六○十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["攻城寨，先料水清源（首本作「源情」、辛本、川本作「情源」，此從京本）。","上有大流堪決灌，不須交刃損兵員，勿縱暴剛權。"]', '["攻城寨，先料水清源（首本作「源情」、辛本、川本作「情源」，此從京本）。","上有大流堪決灌，不須交刃損兵員，勿縱暴剛權。"]', '诗', 'shi', '', NULL, '兵要望江南 占霞第六（京本列第二十六○十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae03a94-8286-4f27-87d2-76a614bdb218', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 一', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹霓現，因雨影東西。","晨現必當雨未止，晚來東現日光輝，術者細觀之。"]', '["虹霓現，因雨影东西。","晨現必當雨未止，晚来东現日光輝，術者細观之。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db87bc4-ae57-42bb-8741-bb8c8a8499ee', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 二', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，虹貫日（京本作「路」）邊傍。","禦（京本作「預」）備伏兵前有阻，且須審細自（京本作「更」）商量，移寨避灾殃（辛本、川本、京本作「終不得開疆」）。","。"]', '["兵行次，虹貫日（京本作「路」）邊傍。","禦（京本作「預」）備伏兵前有阻，且須審細自（京本作「更」）商量，移寨避灾殃（辛本、川本、京本作「終不得开疆」）。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90b0985-951f-4afa-8f71-2a618b92d3aa', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 三', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹霓現，城寨可攻之。","虹（辛本、川本作「蛇」）直入來爲病疫，淺虹兵瘴（京本作「青虹兵戰」）要須知，移寨避灾宜（京本作「危」）。"]', '["虹霓現，城寨可攻之。","虹（辛本、川本作「蛇」）直入来爲病疫，淺虹兵瘴（京本作「青虹兵戰」）要須知，移寨避灾宜（京本作「危」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0d7cfef-2d17-4f6b-983f-ed65c3dff9a2', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 四', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹赤白，盡是阻軍行。","若是（京本作「似」）虹橋欄着路，且須盤泊犒（京本作「靠」）軍兵，不久却回程。"]', '["虹赤白，尽是阻軍行。","若是（京本作「似」）虹橋欄着路，且須盤泊犒（京本作「靠」）軍兵，不久却回程。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe129d5-d149-4ff3-acb0-8f50048d8e89', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 五', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹入井，盡是敗軍情。","或有（京本作「似」）鼠形營上現，忽然交戰血成坑，防（京本作「勿」）撃保城營。"]', '["虹入井，尽是敗軍情。","或有（京本作「似」）鼠形營上現，忽然交戰血成坑，防（京本作「勿」）撃保城營。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1f0ae4-dada-485d-a817-cc932bb685d7', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 六', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹如暈，更復（京本作「或」）似弓形。","有若白虹形斷續，兼之五六見城營，皆主血光成（京本作「生」。","京本注：「或見五六月」）。"]', '["虹如暈，更复（京本作「或」）似弓形。","有若白虹形斷續，兼之五六见城營，皆主血光成（京本作「生」。","京本注：「或见五六月」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2571ec-f313-41ac-9a3b-695ebd446b8d', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 七', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹霓見，更或似弓形。","有若暈來如斷續，兵興五日定（辛本、川本作「便」）回程。","久住必灾成。"]', '["虹霓见，更或似弓形。","有若暈来如斷續，兵兴五日定（辛本、川本作「便」）回程。","久住必灾成。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50da9443-962b-4d51-a2db-92084b98e1e4', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 八', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["白赤虹，單見色無雙。","如氣冲天或橫過，蚩尤旗號動戈鎗，起處必爲殃。"]', '["白赤虹，單见色無雙。","如氣冲天或橫過，蚩尤旗號动戈鎗，起处必爲殃。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb99ff8-0c0b-40c2-8d66-a760adba5c7f', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 九', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虹起處，頭尾地侵天。","其虹見時非有雨，晴天見者血成川，民更有灾愆。"]', '["虹起处，头尾地侵天。","其虹见时非有雨，晴天见者血成川，民更有灾愆。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7f9cfd6-7f54-4737-9d0d-ada81cb18e68', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["白虹見，晝（川本作「盡」）見地侵（辛本、川本作「青」）天。","其地一方皆主亂，衆人喧鬧有灾纏，年內應其占。"]', '["白虹见，晝（川本作「尽」）见地侵（辛本、川本作「青」）天。","其地一方皆主亂，衆人喧鬧有灾纏，年內應其占。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4874dc2a-9909-4205-b5da-4907c0724484', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十一', '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["白赤虹，晝（川本作「盡」）見莫興兵。","更有虹霓垂軍上，彼軍殺將且須停，動必有灾迍。"]', '["白赤虹，晝（川本作「尽」）见莫兴兵。","更有虹霓垂軍上，彼軍殺將且須停，动必有灾迍。"]', '诗', 'shi', '', NULL, '兵要望江南 占虹霓第七（京本作「占虹第九」○十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29041e3a-e091-452c-a3e1-f627290636be', '兵要望江南 占雨第八（京本列第二○十七首） 一', '兵要望江南 占雨第八（京本列第二○十七首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡論雨，二氣是陰陽。","升則爲雲降則雨，若逢兵動合灾祥，良將要參詳。"]', '["凡論雨，二氣是陰陽。","升則爲云降則雨，若逢兵动合灾祥，良將要參詳。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e1b93b-a166-4002-87ae-32c3bd4fdc42', '兵要望江南 占雨第八（京本列第二○十七首） 二', '兵要望江南 占雨第八（京本列第二○十七首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["師在道，或始出郊城。","雷雨如傾溪澗阻，沐（京本作「淋」）屍凶象不堪行，勿要（辛本、川本作「足」）與天爭。"]', '["師在道，或始出郊城。","雷雨如傾溪澗阻，沐（京本作「淋」）屍凶象不堪行，勿要（辛本、川本作「足」）與天爭。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7653d8c6-c52e-46e5-931f-8c7b26379bca', '兵要望江南 占雨第八（京本列第二○十七首） 三', '兵要望江南 占雨第八（京本列第二○十七首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵（辛本、川本、京本作「軍」）始進，雨急立成泥。","名曰沐（京本作「淋」）屍當立（辛本、川本、京本作「速」）止，別詮吉日與良時，強進必（京本作「有」）凶危。","（京本注：軍讖曰：兵行日暴風猛雨，折旗幟不止，此天怒也，不可進兵。","待天象和明，別擇日行。","）。"]', '["兵（辛本、川本、京本作「軍」）始進，雨急立成泥。","名曰沐（京本作「淋」）屍當立（辛本、川本、京本作「速」）止，別詮吉日與良时，強進必（京本作「有」）凶危。","（京本注：軍讖曰：兵行日暴风猛雨，折旗幟不止，此天怒也，不可進兵。","待天象和明，別擇日行。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b9534a-0993-4476-ad06-c32d51a3fcb2', '兵要望江南 占雨第八（京本列第二○十七首） 四', '兵要望江南 占雨第八（京本列第二○十七首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍發日，微雨灑軍（京本作「潤兵」）行。","此是潤軍兵（京本作「兵人」）必利，旌旗前指最爲精，所向定須贏。"]', '["軍發日，微雨灑軍（京本作「潤兵」）行。","此是潤軍兵（京本作「兵人」）必利，旌旗前指最爲精，所向定須贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58202681-d2d3-4587-bf8d-e203db829a22', '兵要望江南 占雨第八（京本列第二○十七首） 五', '兵要望江南 占雨第八（京本列第二○十七首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵始進，旗幟繞於鎗。","半雨半晴霞氣過，且須盤泊好參詳，去即陣難當。"]', '["兵始進，旗幟繞於鎗。","半雨半晴霞氣過，且須盤泊好參詳，去即陣难當。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd85db9-01f5-4562-8f08-d7fc531e15ef', '兵要望江南 占雨第八（京本列第二○十七首） 六', '兵要望江南 占雨第八（京本列第二○十七首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天數日，半雨半兼（川本作「無」）晴。","營內有奸謀結叛，先晴後雨叛難成（京本作「擒」），先雨後晴興（京本作「兵」）。"]', '["天數日，半雨半兼（川本作「無」）晴。","營內有奸謀結叛，先晴後雨叛难成（京本作「擒」），先雨後晴兴（京本作「兵」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2850b91-69a3-40d3-a078-d6ac86176067', '兵要望江南 占雨第八（京本列第二○十七首） 七', '兵要望江南 占雨第八（京本列第二○十七首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵（首本作「風」，此從辛本）發日，風雨逆沾人。","天意示（辛本作「欲」）知教我記，不須前進恐危身，見陣潰亡軍。","（《軍行志》：如行軍見暴風猛雨，倒折旗鎗，大雨不止者，天之怒也，軍不可進。","宜待天象和明，別擇日時門戶，軍行方吉也。","）。"]', '["兵（首本作「风」，此從辛本）發日，风雨逆沾人。","天意示（辛本作「欲」）知教我記，不須前進恐危身，见陣潰亡軍。","（《軍行志》：如行軍见暴风猛雨，倒折旗鎗，大雨不止者，天之怒也，軍不可進。","宜待天象和明，別擇日时门戶，軍行方吉也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0429157b-f8a7-4f1e-93b1-c62efb53115f', '兵要望江南 占雨第八（京本列第二○十七首） 八', '兵要望江南 占雨第八（京本列第二○十七首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天雨物，形體不能聲。","其分凶灾主兵寇，功臣遭戮國須傾，固守得平平。"]', '["天雨物，形體不能声。","其分凶灾主兵寇，功臣遭戮国須傾，固守得平平。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d07678-d45b-44e9-861e-598342a2927c', '兵要望江南 占雨第八（京本列第二○十七首） 九', '兵要望江南 占雨第八（京本列第二○十七首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天雨血，賢退進邪人。","血染金革皆不喜，急移營寨賞三軍，無罪受王刑。"]', '["天雨血，賢退進邪人。","血染金革皆不喜，急移營寨賞三軍，無罪受王刑。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288b7967-d1ee-4b95-aeff-70808b9c9763', '兵要望江南 占雨第八（京本列第二○十七首） 十', '兵要望江南 占雨第八（京本列第二○十七首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天雨鳥，爪翅及諸般。","若在彼軍他主敗，我軍逢此不能安，必見損兵官。"]', '["天雨鸟，爪翅及諸般。","若在彼軍他主敗，我軍逢此不能安，必见損兵官。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39012c83-a706-4160-8bdd-d673a9ec8bcb', '兵要望江南 占雨第八（京本列第二○十七首） 十一', '兵要望江南 占雨第八（京本列第二○十七首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天雨蛩，在敵不能（辛本作「宜」）攻。","或鱉或魚皆凶（首本作「吉」，今從辛本）兆，我軍見者便回程，不動必遭凶。"]', '["天雨蛩，在敵不能（辛本作「宜」）攻。","或鱉或鱼皆凶（首本作「吉」，今從辛本）兆，我軍见者便回程，不动必遭凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5891aaab-1641-447a-9dcd-35b1a0a93264', '兵要望江南 占雨第八（京本列第二○十七首） 十二', '兵要望江南 占雨第八（京本列第二○十七首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天雨毛，主將信邪奸。","急宜謹亷須固守，莫將輕慢事非凡，天意報君顏。"]', '["天雨毛，主將信邪奸。","急宜謹亷須固守，莫將轻慢事非凡，天意報君顏。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('472645c0-9f19-4265-bae3-20926fe9f567', '兵要望江南 占雨第八（京本列第二○十七首） 十三', '兵要望江南 占雨第八（京本列第二○十七首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["無雲霧，一色見天晴。","此象無雲而雨降，謂之天泣事難禁，主帥未安心。"]', '["無云霧，一色见天晴。","此象無云而雨降，謂之天泣事难禁，主帥未安心。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62017bd4-e5d3-451a-a49e-95ff91f4a112', '兵要望江南 占雨第八（京本列第二○十七首） 十四', '兵要望江南 占雨第八（京本列第二○十七首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["黑雲現，橫截在天河。","見此天河新作換，來朝有雨報君家，此語不曾差。"]', '["黑云現，橫截在天河。","见此天河新作換，来朝有雨報君家，此語不曾差。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33385ca1-a3be-4a4b-8b78-a2c05497fed6', '兵要望江南 占雨第八（京本列第二○十七首） 十五', '兵要望江南 占雨第八（京本列第二○十七首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天河內，閃電見光明。","隨即來朝遭大雨，自然霶霈若盆傾，平地水汪盈。"]', '["天河內，閃電见光明。","隨即来朝遭大雨，自然霶霈若盆傾，平地水汪盈。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9704a4de-1346-405a-9bf9-7ec56af65838', '兵要望江南 占雨第八（京本列第二○十七首） 十六', '兵要望江南 占雨第八（京本列第二○十七首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月生暈，月暈暈參星。","或暈井宿遭雨降，五朝七日不差分，空裏似盆傾。"]', '["月生暈，月暈暈參星。","或暈井宿遭雨降，五朝七日不差分，空裏似盆傾。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37fae4a7-339a-4f58-8591-04c7e3f24f32', '兵要望江南 占雨第八（京本列第二○十七首） 十七', '兵要望江南 占雨第八（京本列第二○十七首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["密雲現，雨陣黑濃濃。","驀地攔前轟霹靂，天雷驚震擁（首本作「攤」，茲從辛本、川本）來攻，有雨不多分。"]', '["密云現，雨陣黑濃濃。","驀地攔前轟霹靂，天雷驚震擁（首本作「攤」，茲從辛本、川本）来攻，有雨不多分。"]', '诗', 'shi', '', NULL, '兵要望江南 占雨第八（京本列第二○十七首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672487db-43fe-4754-b059-64c58d59cd1a', '兵要望江南 占雷第九（京本列第二十五○三十一首）', '兵要望江南 占雷第九（京本列第二十五○三十一首）', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9454b108-a48f-4343-99f2-e1604abb56eb', '兵要望江南 占雷第九（京本列第二十五○三十一首） 一', '兵要望江南 占雷第九（京本列第二十五○三十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["老陽極，出地變成雷。","出聲之先收聲後，此爲灾怪號非時，兵起主荒饑。"]', '["老陽極，出地变成雷。","出声之先收声後，此爲灾怪號非时，兵起主荒饑。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb3c5b7b-98dc-4510-925c-7df888bc16c6', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占雷法，大怕出非時。","皆是守官無政法，酷民枉法有天知，天怒震權威（辛本、川本作「震威摧」）。"]', '["占雷法，大怕出非时。","皆是守官無政法，酷民枉法有天知，天怒震權威（辛本、川本作「震威摧」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ee4136-2255-4f11-ac5d-a19b4fa7a4b6', '兵要望江南 占雷第九（京本列第二十五○三十一首） 三', '兵要望江南 占雷第九（京本列第二十五○三十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，風吼忽雷鳴。","戰馬盡驚旗倒折，前程必有賊來迎，大戰血交幷。"]', '["兵發日，风吼忽雷鳴。","戰马尽驚旗倒折，前程必有賊来迎，大戰血交幷。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcc1b89-f13e-4ea0-aa4d-9caa19cc2b55', '兵要望江南 占雷第九（京本列第二十五○三十一首） 四', '兵要望江南 占雷第九（京本列第二十五○三十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，雲氣與雷聲。","雲趁我軍雷逐後，天威神助大軍行，此去必須贏。"]', '["兵發日，云氣與雷声。","云趁我軍雷逐後，天威神助大軍行，此去必須贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed56bfb9-5dca-41ac-8c3d-c19735566093', '兵要望江南 占雷第九（京本列第二十五○三十一首） 五', '兵要望江南 占雷第九（京本列第二十五○三十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，雷動我軍營。","天助威靈軍得勝，若居彼上我勞軍，審細聽其聲。"]', '["兵發日，雷动我軍營。","天助威靈軍得勝，若居彼上我勞軍，審細听其声。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61bc2b8-a0f8-4ead-aae7-2dbaeede3aae', '兵要望江南 占雷第九（京本列第二十五○三十一首） 六', '兵要望江南 占雷第九（京本列第二十五○三十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["冬三月，何事忽雷鳴？只利客居（川本作「軍」）非利主（辛本、川本作「土」），高旗先舉定須贏，後戰必無成。"]', '["冬三月，何事忽雷鳴？只利客居（川本作「軍」）非利主（辛本、川本作「土」），高旗先舉定須贏，後戰必無成。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13021139-d964-4084-9976-56152184b30f', '兵要望江南 占雷第九（京本列第二十五○三十一首） 七', '兵要望江南 占雷第九（京本列第二十五○三十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雷霹靂，樹木及諸般。","若在彼軍營寨上，天威殺氣我難當，移寨始爲安。"]', '["雷霹靂，樹木及諸般。","若在彼軍營寨上，天威殺氣我难當，移寨始爲安。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092363d0-4667-4d22-93df-9c83b782fabe', '兵要望江南 占雷第九（京本列第二十五○三十一首） 八', '兵要望江南 占雷第九（京本列第二十五○三十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨上，雷止一聲鳴。","定是命來應迅速，不然急詔事叮嚀，上將好詳聽。"]', '["營寨上，雷止一声鳴。","定是命来應迅速，不然急詔事叮嚀，上將好詳听。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b66972eb-d920-4390-bccd-fecfb7f378cc', '兵要望江南 占雷第九（京本列第二十五○三十一首） 九', '兵要望江南 占雷第九（京本列第二十五○三十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營郡邑，天上忽雷鳴（辛本、川本作「聲」）。","欲似雷鳴還不是（辛本、川本作「似」），多應土地注長（二字據辛本、川本補）傾，否則（辛本、川本作「即」）戰將爭。"]', '["營郡邑，天上忽雷鳴（辛本、川本作「声」）。","欲似雷鳴還不是（辛本、川本作「似」），多應土地注长（二字據辛本、川本補）傾，否則（辛本、川本作「即」）戰將爭。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cc1914e-b6f6-4c06-859f-893f8aee1387', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，風送逆雷聲。","天意欲將（京本作「顯然」）兵仔細，不宜先舉恐傷危，遇敵恐（京本作「必」）遭摧。","（京本注：夫雷霆者，天地之成，震則以驚萬物，兵者尤宜祭之。","凡雷霆於將軍士卒，宜擐甲張弦，其兵得天助也。","）。"]', '["兵發日，风送逆雷声。","天意欲將（京本作「显然」）兵仔細，不宜先舉恐傷危，遇敵恐（京本作「必」）遭摧。","（京本注：夫雷霆者，天地之成，震則以驚万物，兵者尤宜祭之。","凡雷霆於將軍士卒，宜擐甲張弦，其兵得天助也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60971608-4da6-4526-84d9-5233a77566ee', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十一', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["無雲氣，天色十分晴。","驀地一聲如雷響，或如霹靂野鷄驚，龍出沒灾刑。","（經曰：「謂之天鼓，亦主兵火。","」又曰：「龍出。","」）。"]', '["無云氣，天色十分晴。","驀地一声如雷响，或如霹靂野鷄驚，龙出沒灾刑。","（經曰：「謂之天鼓，亦主兵火。","」又曰：「龙出。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3684cd13-485e-4a31-a1f4-1e1a0f8a7032', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十二', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍衆，驀地一聲雷。","次後幷無雷附矣，將軍兵衆必行之，舉處可先爲。"]', '["將軍衆，驀地一声雷。","次後幷無雷附矣，將軍兵衆必行之，舉处可先爲。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17473fe1-6806-4229-a954-74a30fffdb40', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十三', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["春三月，甲子共庚寅。","乙丑戊子幷辛卯，雷鳴霹靂恐傷人，大戰月旬驚。","。"]', '["春三月，甲子共庚寅。","乙丑戊子幷辛卯，雷鳴霹靂恐傷人，大戰月旬驚。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20020aaa-af8d-4fdf-8ff1-ca18d1fe940a', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十四', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將戰次，臨陣有雷聲。","從我軍中謀至敵，敵軍必敗我軍贏，反此一同情。"]', '["將戰次，臨陣有雷声。","從我軍中謀至敵，敵軍必敗我軍贏，反此一同情。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09002079-f47c-4c52-a61f-ce597c60f2c2', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十五', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天陰久，不雨數朝期。","忽有雷鳴我軍上，前程得捷便占（辛本、川本作「占便」）宜，反此我軍危。"]', '["天陰久，不雨數朝期。","忽有雷鳴我軍上，前程得捷便占（辛本、川本作「占便」）宜，反此我軍危。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb48857c-9585-4bd5-bf1c-ddc4a270c9b3', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十六', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雷四起，南北與東西。","其勢往還鳴不定，合當迴避不須遲，大戰兩傷之。"]', '["雷四起，南北與东西。","其勢往還鳴不定，合當迴避不須遲，大戰兩傷之。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc871ca-2d2c-4c81-87a0-56ea400bee32', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十七', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["聲渾渾，其勢又圓長。","起處來方我軍上，若還征戰定無妨，又助我軍強。"]', '["声渾渾，其勢又圓长。","起处来方我軍上，若還征戰定無妨，又助我軍強。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('746bf485-19b8-4db8-b545-7a3f076daf14', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十八', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["霹靂震，牙（首本作「手」，茲從辛本、川本）帳震聲雄。","忽速搜尋休要住，須知營寨有奸凶，尋覓莫從容。"]', '["霹靂震，牙（首本作「手」，茲從辛本、川本）帳震声雄。","忽速搜尋休要住，須知營寨有奸凶，尋覓莫從容。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67038af-eeb4-4917-8a89-8f90de449ed4', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十九', '兵要望江南 占雷第九（京本列第二十五○三十一首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["密雲見，踴躍若傾河。","或（辛本作「忽」）有雷聲先大作，其時有雨也無多，說處莫（川本作「沒」）偏頗（辛本作「說出遍遍無。","」）（按：首本此處缺一頁，以下五首據辛本補。","）。"]', '["密云见，踴躍若傾河。","或（辛本作「忽」）有雷声先大作，其时有雨也無多，说处莫（川本作「沒」）偏頗（辛本作「说出遍遍無。","」）（按：首本此处缺一頁，以下五首據辛本補。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d0ba03-dfc3-429d-b1ad-3735d3591fa3', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雷忽震，震處衆人驚。","若雷又非聲振怒，我軍之上必摧傾，移寨免憂驚。"]', '["雷忽震，震处衆人驚。","若雷又非声振怒，我軍之上必摧傾，移寨免憂驚。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b860c987-5ed6-4773-8303-c63db5c830d9', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十一', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雷聲震，連日不收聲。","此象正爲多失信，爲他官吏不能清，天令與人聞。"]', '["雷声震，連日不收声。","此象正爲多失信，爲他官吏不能清，天令與人闻。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11b05ff-90c9-45af-8b4a-7d9d3112e54b', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十二', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雷震雹，隨即雪空飛。","陰氣勝陽因此得，賊臣將起事須疑，主吏損心知。"]', '["雷震雹，隨即雪空飞。","陰氣勝陽因此得，賊臣將起事須疑，主吏損心知。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10076299-e598-4a37-b58d-5441fd1b527f', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十三', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，雷發我軍中。","天助神威兵大勝，若居彼上我軍凶，詳細辨雷轟。"]', '["兵發日，雷發我軍中。","天助神威兵大勝，若居彼上我軍凶，詳細辨雷轟。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aced8bf-c825-4a65-bfec-0c1eae6defb1', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十四', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，霞氣與雷聲。","霞隨我軍雷隨彼，威感應之我軍停，此去必成功。"]', '["兵發日，霞氣與雷声。","霞隨我軍雷隨彼，威感應之我軍停，此去必成功。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148bb9e8-09be-4c53-9407-df874f451bd3', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十五', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，須要識鳴方。","雷自我軍營上起，主軍大勝客軍傷，天意助吾祥。","（以下七首從京本補。","）。"]', '["兵發日，須要識鳴方。","雷自我軍營上起，主軍大勝客軍傷，天意助吾祥。","（以下七首從京本補。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb654e2-0d12-47c6-93d2-9d8aebe37bf5', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十六', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，雷向敵軍鳴。","彼勝我輸宜罷戰，不然城寨定遭迍，預計不宜征。"]', '["兵發日，雷向敵軍鳴。","彼勝我輸宜罷戰，不然城寨定遭迍，預計不宜征。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2380383c-be53-4103-bf07-a8c2aee0b3fc', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十七', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，無雨及無雲。","營上忽然雷霹靂，主軍大敗急移營，不爾禍來侵。","。"]', '["軍營內，無雨及無云。","營上忽然雷霹靂，主軍大敗急移營，不爾禍来侵。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15748310-175b-44f7-b60c-e02e049356cf', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十八', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占雷兆，初發那方鳴。","乾上主興多士卒，坎方大水阻行兵，艮位病臨營。"]', '["占雷兆，初發那方鳴。","乾上主兴多士卒，坎方大水阻行兵，艮位病臨營。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb990e9-e9dc-4be7-bdcb-859b1a804c50', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十九', '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占雷兆，初若震方鳴。","決主其年穀高貴，預收糧餉賑軍民，巽上旱灾臨。"]', '["占雷兆，初若震方鳴。","決主其年穀高貴，預收糧餉賑軍民，巽上旱灾臨。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1034da59-1e7d-4f5c-a326-79e87804e303', '兵要望江南 占雷第九（京本列第二十五○三十一首） 三十', '兵要望江南 占雷第九（京本列第二十五○三十一首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占雷兆，初動在離方。","恐有火灾兼旱孽，坤宮損稼總宜禳，兌位起兵忙。"]', '["占雷兆，初动在離方。","恐有火灾兼旱孽，坤宮損稼總宜禳，兌位起兵忙。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3c276e-3d44-4872-b012-a25c626c4705', '兵要望江南 占雷第九（京本列第二十五○三十一首） 三十一', '兵要望江南 占雷第九（京本列第二十五○三十一首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["商音姓，鳴忌在離方。","角姓兌乾宮震巽，羽防坤艮及中央，徴姓坎方殃。","（天子出取天子姓，不出只以主將姓幷日干爲主，以八方生尅斷。","訣云：甲乙兌乾方，丙丁坎上當。","戊己防震巽，庚辛離有殃。","壬癸艮坤位，中央總不祥。","我尅他軍敗，他尅我軍傷。","生他雖用計，生我自投降。","上天昭應驗，良將細推詳。","）。"]', '["商音姓，鳴忌在離方。","角姓兌乾宮震巽，羽防坤艮及中央，徴姓坎方殃。","（天子出取天子姓，不出只以主將姓幷日干爲主，以八方生尅斷。","訣云：甲乙兌乾方，丙丁坎上當。","戊己防震巽，庚辛離有殃。","壬癸艮坤位，中央總不祥。","我尅他軍敗，他尅我軍傷。","生他雖用計，生我自投降。","上天昭應驗，良將細推詳。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占雷第九（京本列第二十五○三十一首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea67d90-f8a8-438b-8625-b436e40c5547', '兵要望江南 占天第十（十一首） 一', '兵要望江南 占天第十（十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天之道，爲父又爲君。","清靜麗明爲順吉，昏暗陰散缺忠臣，諂佞近王庭。"]', '["天之道，爲父又爲君。","清静丽明爲順吉，昏暗陰散缺忠臣，諂佞近王庭。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9481a25e-9b23-459e-86c0-b8bc926a7edd', '兵要望江南 占天第十（十一首） 二', '兵要望江南 占天第十（十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天氣赤，蔭地一般紅。","人物盡來如屠血，來兵必戰有災凶，兵敗莫西東。","（宋咸淳甲戌七月初六日庚辰酉時，在天有一丈餘高霞，映地如血，當年十二月過江，至丙子納降，江淮軍民遭塗炭。","）（按：此條原注爲後人附加。","）。"]', '["天氣赤，蔭地一般紅。","人物尽来如屠血，来兵必戰有災凶，兵敗莫西东。","（宋咸淳甲戌七月初六日庚辰酉时，在天有一丈餘高霞，映地如血，當年十二月過江，至丙子納降，江淮軍民遭塗炭。","）（按：此條原注爲後人附加。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc22068-9b54-4aeb-af87-080c1bb63dd0', '兵要望江南 占天第十（十一首） 三', '兵要望江南 占天第十（十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天之道，哀響又兼鳴。","此處必主興王道，異謀革位少良臣，年內見其因。"]', '["天之道，哀响又兼鳴。","此处必主兴王道，異謀革位少良臣，年內见其因。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19507ce9-e37a-4299-86ac-ccb53c4e7a33', '兵要望江南 占天第十（十一首） 四', '兵要望江南 占天第十（十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天之道，其象號乾方。","或若分爲於兩半，分常別土亂征傷，人主見憂惶。"]', '["天之道，其象號乾方。","或若分爲於兩半，分常別土亂征傷，人主见憂惶。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d72280d2-5540-4738-b3f5-c188c1dd7d90', '兵要望江南 占天第十（十一首） 五', '兵要望江南 占天第十（十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天之道，忽裂見樓臺。","皆主兵荒人世亂，千般祥瑞忽爲災，其怪報人來。","（以上五首首本缺，據辛本、川本補。","）。"]', '["天之道，忽裂见楼台。","皆主兵荒人世亂，千般祥瑞忽爲災，其怪報人来。","（以上五首首本缺，據辛本、川本補。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc42cd3a-534e-46b7-a75b-628a57a20a8c', '兵要望江南 占天第十（十一首） 六', '兵要望江南 占天第十（十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天河分，忽若似鎗（辛本、川本作「戟」）尖。","兵世當興逢此兆，諸川郡府見憂煎。","塗炭遍山川。"]', '["天河分，忽若似鎗（辛本、川本作「戟」）尖。","兵世當兴逢此兆，諸川郡府见憂煎。","塗炭遍山川。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaca596a-09e8-4da6-b874-418b5f240394', '兵要望江南 占天第十（十一首） 七', '兵要望江南 占天第十（十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天色白，慘慘甚昏曚。","久陰不雨陰謀事，必爲兵火事難通（「通」字據辛本、川本補）。","年內始知蹤（首本作「通」，茲從辛本、川本。","）。"]', '["天色白，慘慘甚昏曚。","久陰不雨陰謀事，必爲兵火事难通（「通」字據辛本、川本補）。","年內始知蹤（首本作「通」，茲從辛本、川本。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705a91c4-2444-472d-b3eb-87db7d9235f6', '兵要望江南 占天第十（十一首） 八', '兵要望江南 占天第十（十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天忽響，鳴鬧在蒼穹。","多是子憂當父感，天鳴臣怒鑒君同，君主可寬刑。"]', '["天忽响，鳴鬧在蒼穹。","多是子憂當父感，天鳴臣怒鑒君同，君主可寬刑。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('056e7255-220e-4b50-8571-c196ba29a39d', '兵要望江南 占天第十（十一首） 九', '兵要望江南 占天第十（十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天道慘，慘色變深黃。","必主大風三二日，船行急止莫徜徉（辛本、川本作「滄洋」），預報與君忙。"]', '["天道慘，慘色变深黄。","必主大风三二日，船行急止莫徜徉（辛本、川本作「滄洋」），預報與君忙。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e425bbfd-f1c2-4ede-b421-2292e19d7543', '兵要望江南 占天第十（十一首） 十', '兵要望江南 占天第十（十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天忽見，有虹赤紅黃。","貫北斗極星還遶，君生賢聖主（辛本作「至」）非常。","此事甚相當。"]', '["天忽见，有虹赤紅黄。","貫北斗極星還遶，君生賢聖主（辛本作「至」）非常。","此事甚相當。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3a6dad-4d00-4024-96ab-37317ff65c7e', '兵要望江南 占天第十（十一首） 十一', '兵要望江南 占天第十（十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["天久旱，無雨水盆流。","此是天時雨不潤，不能下降令人憂（辛本、川本作「奔高流」）。"]', '["天久旱，無雨水盆流。","此是天时雨不潤，不能下降令人憂（辛本、川本作「奔高流」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占天第十（十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2579964d-891f-41a0-bf73-b7ba79c4d084', '兵要望江南 占日第十一（京本列第六○五十六首） 一', '兵要望江南 占日第十一（京本列第六○五十六首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽位，爲主正爲君。","兆主國君家國事，通行循度總和平，昏蝕主憂驚。"]', '["太陽位，爲主正爲君。","兆主国君家国事，通行循度總和平，昏蝕主憂驚。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd313dc7-b2db-4bca-bced-bc1d596f8be1', '兵要望江南 占日第十一（京本列第六○五十六首） 二', '兵要望江南 占日第十一（京本列第六○五十六首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日旁氣，赤色若（京本作「似」）懸鐘。","所見之時（辛本、川本、京本作「遊所見邊」）須將死，不論春夏與秋冬，所舉總成空。"]', '["日旁氣，赤色若（京本作「似」）懸鐘。","所见之时（辛本、川本、京本作「游所见邊」）須將死，不論春夏與秋冬，所舉總成空。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e925b6-23f4-4525-ab01-a4cb723e765c', '兵要望江南 占日第十一（京本列第六○五十六首） 三', '兵要望江南 占日第十一（京本列第六○五十六首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日生暈，上下兩重交。","必有彼疆亡將過（京本作「軍亡將帥」），中謀獨霸不成韜，終是舉（京本作「起」）鎗刀。"]', '["日生暈，上下兩重交。","必有彼疆亡將過（京本作「軍亡將帥」），中謀独霸不成韜，終是舉（京本作「起」）鎗刀。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef04e329-3686-489c-95b2-79b515bff7ee', '兵要望江南 占日第十一（京本列第六○五十六首） 四', '兵要望江南 占日第十一（京本列第六○五十六首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日左（辛本、川本作「在」）右，白氣若虹交。","兆（京本作「即」）主血流成大戰，緣君失政作成妖，無法可禳消。"]', '["日左（辛本、川本作「在」）右，白氣若虹交。","兆（京本作「即」）主血流成大戰，緣君失政作成妖，無法可禳消。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27a1dee4-7d6f-42da-a706-c6d62eec4a34', '兵要望江南 占日第十一（京本列第六○五十六首） 五', '兵要望江南 占日第十一（京本列第六○五十六首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日光暈，暈珥有陰風。","左右並同爲吉兆，三般變動日時逢（京本作「同」），日月在羅籠。","（日邊耳，經曰：日有抱暈於野，皆有降軍降將至也。","）。"]', '["日光暈，暈珥有陰风。","左右並同爲吉兆，三般变动日时逢（京本作「同」），日月在羅籠。","（日邊耳，經曰：日有抱暈於野，皆有降軍降將至也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e49b0261-1a88-438a-9500-46f3eb713b39', '兵要望江南 占日第十一（京本列第六○五十六首） 六', '兵要望江南 占日第十一（京本列第六○五十六首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日光暈，有暈要須知。","闕處預先防（京本作「隄」）備吉，忽然不闕亦（京本作「不」）須疑，三日雨淋漓。"]', '["日光暈，有暈要須知。","闕处預先防（京本作「隄」）備吉，忽然不闕亦（京本作「不」）須疑，三日雨淋漓。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a50d96-2d1d-4c19-95c2-297c2b5fb52e', '兵要望江南 占日第十一（京本列第六○五十六首） 七', '兵要望江南 占日第十一（京本列第六○五十六首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日中暈，上蓋下爲陰（京本作「纓」）。","向暈即凶背暈吉，若無征戰有風聲，霞氣雨還成。"]', '["日中暈，上蓋下爲陰（京本作「纓」）。","向暈即凶背暈吉，若無征戰有风声，霞氣雨還成。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbdb1dce-f893-4b6e-814c-e96a719da426', '兵要望江南 占日第十一（京本列第六○五十六首） 八', '兵要望江南 占日第十一（京本列第六○五十六首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["暈不合，垂在兩邊生（京本作「旁」）。","城內有人謀不就，且饒緩慢看軍（京本作「牽」）情，一事也無成。"]', '["暈不合，垂在兩邊生（京本作「旁」）。","城內有人謀不就，且饒緩慢看軍（京本作「牽」）情，一事也無成。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc50941-5029-4af4-8f66-df307a1ea579', '兵要望江南 占日第十一（京本列第六○五十六首） 九', '兵要望江南 占日第十一（京本列第六○五十六首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["暈邊氣，入則外軍贏。","隨氣攻之應大勝，忽然內出外軍傾，勝負預先明（京本作「征」）。","。"]', '["暈邊氣，入則外軍贏。","隨氣攻之應大勝，忽然內出外軍傾，勝負預先明（京本作「征」）。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e0da6d-5134-4221-8727-364f1e269564', '兵要望江南 占日第十一（京本列第六○五十六首） 十', '兵要望江南 占日第十一（京本列第六○五十六首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["暈邊珥，一珥喜來生。","兩珥欲來相解意，又言敗（川本、辛本、京本作「拜」）將攝公卿，此術甚分明。"]', '["暈邊珥，一珥喜来生。","兩珥欲来相解意，又言敗（川本、辛本、京本作「拜」）將攝公卿，此術甚分明。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee110d1-6399-4862-8b1c-0e9c13069767', '兵要望江南 占日第十一（京本列第六○五十六首） 十一', '兵要望江南 占日第十一（京本列第六○五十六首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日月背，順吉背須凶。","若背東方西面勝，背西東面獲其功，南北並皆同。"]', '["日月背，順吉背須凶。","若背东方西面勝，背西东面獲其功，南北並皆同。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202a9fde-6ab5-4184-9975-91ecd7403c0a', '兵要望江南 占日第十一（京本列第六○五十六首） 十二', '兵要望江南 占日第十一（京本列第六○五十六首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占日月，主客要先知。","晝把（京本作「犯」）太陽將作主，夜憑星月驗安危，客認（京本作「與」）氣隨時。","（日月星爲主，雲霞氣爲客。","）。"]', '["占日月，主客要先知。","晝把（京本作「犯」）太陽將作主，夜憑星月驗安危，客認（京本作「與」）氣隨时。","（日月星爲主，云霞氣爲客。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e19d51-d770-4626-84e9-d319bc49debf', '兵要望江南 占日第十一（京本列第六○五十六首） 十三', '兵要望江南 占日第十一（京本列第六○五十六首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["相鬬（京本作「聞」）敵，兩日見分明。","必有拔營離寨去，正當日下（京本作「夜」）看拋城，大戰血交幷（京本作「兵」。","首本缺此首，茲據辛本、川本。","）。"]', '["相鬬（京本作「闻」）敵，兩日见分明。","必有拔營離寨去，正當日下（京本作「夜」）看拋城，大戰血交幷（京本作「兵」。","首本缺此首，茲據辛本、川本。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4809e6a8-80e8-45f1-9f0c-61c58a7268b2', '兵要望江南 占日第十一（京本列第六○五十六首） 十四', '兵要望江南 占日第十一（京本列第六○五十六首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["相鬭（京本作「聞」）敵，日鬬對城營（京本作「營城」）。","交戰血流看主客，必應主敗客軍贏，日度算還生。","（辛本、川本注：「算太陽分野。","」京本注：「精算太陽分野，在日度算還生第十三首。","」）。"]', '["相鬭（京本作「闻」）敵，日鬬对城營（京本作「營城」）。","交戰血流看主客，必應主敗客軍贏，日度算還生。","（辛本、川本注：「算太陽分野。","」京本注：「精算太陽分野，在日度算還生第十三首。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bfdbcea-6a2d-4f06-abee-25940d9b3124', '兵要望江南 占日第十一（京本列第六○五十六首） 十五', '兵要望江南 占日第十一（京本列第六○五十六首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日中暈，日被白虹穿。","天下大兵看即（京本作「帥」）起，又兼烈士報仇冤，奮怒氣沖天。","（荆軻入秦時有此兆。","）。"]', '["日中暈，日被白虹穿。","天下大兵看即（京本作「帥」）起，又兼烈士報仇冤，奮怒氣沖天。","（荆軻入秦时有此兆。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8708bb1-c17d-4d1e-b3e3-b0488918b609', '兵要望江南 占日第十一（京本列第六○五十六首） 十六', '兵要望江南 占日第十一（京本列第六○五十六首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，日偶蝕幷虧。","莫往前程尋大戰，天垂威（辛本、川本作「戒」）象遣（京本作「上天垂象欲」）人知，去則將難歸。"]', '["兵發日，日偶蝕幷虧。","莫往前程尋大戰，天垂威（辛本、川本作「戒」）象遣（京本作「上天垂象欲」）人知，去則將难归。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75df246a-b4f1-42da-ad33-5e3c03572143', '兵要望江南 占日第十一（京本列第六○五十六首） 十七', '兵要望江南 占日第十一（京本列第六○五十六首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["冠纓日（京本作「者」），日上即爲冠。","右（京本作「在」）下爲纓擎捧日，冠爲喜兆將須歡，纓則將心攢。"]', '["冠纓日（京本作「者」），日上即爲冠。","右（京本作「在」）下爲纓擎捧日，冠爲喜兆將須歡，纓則將心攢。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4822d29c-5ffd-4bd2-ba1f-a8493c054ed1', '兵要望江南 占日第十一（京本列第六○五十六首） 十八', '兵要望江南 占日第十一（京本列第六○五十六首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兩日鬬，少時（京本作「小將」）及明朝。","倘或必（辛本、川本、京本作「忽」）聞如此兆，外藩草莽競（京本作「盡」）興妖，進步即嚎啕（辛本、川本作「疾兵消」）。"]', '["兩日鬬，少时（京本作「小將」）及明朝。","倘或必（辛本、川本、京本作「忽」）闻如此兆，外藩草莽競（京本作「尽」）兴妖，進步即嚎啕（辛本、川本作「疾兵消」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a95824-3853-4fd2-849a-18fc89c45bba', '兵要望江南 占日第十一（京本列第六○五十六首） 十九', '兵要望江南 占日第十一（京本列第六○五十六首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日邊氣，如杵赤而明。","既顯不當軍將出，執迷堅往損其兵，一半不回程。"]', '["日邊氣，如杵赤而明。","既显不當軍將出，執迷堅往損其兵，一半不回程。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea676116-d757-4b4b-98c4-b3b075119cee', '兵要望江南 占日第十一（京本列第六○五十六首） 二十', '兵要望江南 占日第十一（京本列第六○五十六首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日旁暈，狀若死蛇圍。","其兆主（京本作「生」）災先舉（京本作「損」）將，師徒半出不能回，宜改（京本作「後」）擁師歸。","（此首首本缺，據辛本、川本。","）。"]', '["日旁暈，狀若死蛇圍。","其兆主（京本作「生」）災先舉（京本作「損」）將，師徒半出不能回，宜改（京本作「後」）擁師归。","（此首首本缺，據辛本、川本。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4edf1f57-5cd7-4e2c-abd5-9ae94f6dcc68', '兵要望江南 占日第十一（京本列第六○五十六首） 二十一', '兵要望江南 占日第十一（京本列第六○五十六首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日邊暈，抱日一邊生。","順抱敵人須可撃，還如逆抱戰無贏，隨衆（京本作「象」）舉其兵。"]', '["日邊暈，抱日一邊生。","順抱敵人須可撃，還如逆抱戰無贏，隨衆（京本作「象」）舉其兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('583aa2f6-9630-40d4-a998-662d3afff2c5', '兵要望江南 占日第十一（京本列第六○五十六首） 二十二', '兵要望江南 占日第十一（京本列第六○五十六首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日下氣，赤氣列三層。","天下流亡兵競起，黎民失業禍災生，鹿走霸圖爭。"]', '["日下氣，赤氣列三層。","天下流亡兵競起，黎民失業禍災生，鹿走霸圖爭。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723f0856-dced-484e-9de5-daf617b16762', '兵要望江南 占日第十一（京本列第六○五十六首） 二十三', '兵要望江南 占日第十一（京本列第六○五十六首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日四耳，多在四隅邊。","宮闕儲君生太子，歡欣期降定三年，人馬罷征權。"]', '["日四耳，多在四隅邊。","宮闕儲君生太子，歡欣期降定三年，人马罷征權。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12240cab-6120-4744-a958-7d6a19ae16cf', '兵要望江南 占日第十一（京本列第六○五十六首） 二十四', '兵要望江南 占日第十一（京本列第六○五十六首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日中氣，上下黑衝過。","長子建謀興大逆，速當根究莫蹉跎，遲便舉（京本作「起」）干戈。"]', '["日中氣，上下黑衝過。","长子建謀兴大逆，速當根究莫蹉跎，遲便舉（京本作「起」）干戈。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3e6636-9410-4d35-86d1-d7046bf56ff6', '兵要望江南 占日第十一（京本列第六○五十六首） 二十五', '兵要望江南 占日第十一（京本列第六○五十六首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兩陣近，青氣日邊生。","其狀分明如半月，順其形氣速前征，交戰必須贏。"]', '["兩陣近，青氣日邊生。","其狀分明如半月，順其形氣速前征，交戰必須贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1930509-cf2c-45c4-b08e-f9eed0ef3a78', '兵要望江南 占日第十一（京本列第六○五十六首） 二十六', '兵要望江南 占日第十一（京本列第六○五十六首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，八字氣分明。","下若鹿麞形勢走，將亡兵潰禍災生，固守保關營。"]', '["太陽畔，八字氣分明。","下若鹿麞形勢走，將亡兵潰禍災生，固守保关營。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df6760b8-1b99-4b13-bcea-92b184247bbf', '兵要望江南 占日第十一（京本列第六○五十六首） 二十七', '兵要望江南 占日第十一（京本列第六○五十六首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，雲氣傘張形。","又若飛烟星在（辛本、川本、京本作「影」）裏，火星傍出血成坑，堅守不宜行。"]', '["太陽畔，云氣傘張形。","又若飞烟星在（辛本、川本、京本作「影」）裏，火星傍出血成坑，堅守不宜行。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e868be57-d002-4c9e-9294-f24c999c69b5', '兵要望江南 占日第十一（京本列第六○五十六首） 二十八', '兵要望江南 占日第十一（京本列第六○五十六首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，突出泰山端。","紫氣盤旋供（辛本、川本作「俱」）不散，城中軍勝賊當殘，臨陣審詳看。"]', '["太陽畔，突出泰山端。","紫氣盤旋供（辛本、川本作「俱」）不散，城中軍勝賊當殘，臨陣審詳看。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47361c66-4816-4329-82b1-d88a2f2f8e54', '兵要望江南 占日第十一（京本列第六○五十六首） 二十九', '兵要望江南 占日第十一（京本列第六○五十六首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，氣蓋（京本作「貫」）日當中。","白色東西連卯酉，主憂社稷（京本作「宗社」）重災凶，改號任神龍。","（龍名曰喪門。","）。"]', '["太陽畔，氣蓋（京本作「貫」）日當中。","白色东西連卯酉，主憂社稷（京本作「宗社」）重災凶，改號任神龙。","（龙名曰喪门。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c05442b-e188-492a-a6f5-cf3ccedeb201', '兵要望江南 占日第十一（京本列第六○五十六首） 三十', '兵要望江南 占日第十一（京本列第六○五十六首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，九曜旋（辛本、川本、京本作「簇」）於邊。","似火如燈光爛爛（京本作「燁燁」），九州大亂水滔天（京本作「血流川」），王道苦（京本作「若」）憂煎。","（又主兵戈。","）。"]', '["太陽畔，九曜旋（辛本、川本、京本作「簇」）於邊。","似火如灯光爛爛（京本作「燁燁」），九州大亂水滔天（京本作「血流川」），王道苦（京本作「若」）憂煎。","（又主兵戈。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a163f2-4e96-4a11-981d-9e9a28fa95c1', '兵要望江南 占日第十一（京本列第六○五十六首） 三十一', '兵要望江南 占日第十一（京本列第六○五十六首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，牛鬬競爭時。","更有傍邊持戟立，戟人無首影依稀，宗廟必傾危。","（首本此首兩收，前二句一作「太陽鬬，競與日爭時」。","）。"]', '["太陽畔，牛鬬競爭时。","更有傍邊持戟立，戟人無首影依稀，宗廟必傾危。","（首本此首兩收，前二句一作「太陽鬬，競與日爭时」。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4b43f8-dbab-4ccf-a9e8-75ac39acdd15', '兵要望江南 占日第十一（京本列第六○五十六首） 三十二', '兵要望江南 占日第十一（京本列第六○五十六首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，如幕（京本作「蔓」）又如花。","相繼相連不間（京本作「黏不」）斷，嬪妃皇后亂其家，術士見生涯。"]', '["太陽畔，如幕（京本作「蔓」）又如花。","相繼相連不间（京本作「黏不」）斷，嬪妃皇后亂其家，術士见生涯。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c4529f-6061-4fe2-b35b-6a625f127680', '兵要望江南 占日第十一（京本列第六○五十六首） 三十三', '兵要望江南 占日第十一（京本列第六○五十六首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，氣如剪刀形。","更有散花桃杏（京本作「李」）雜，君王失政后妃稱（京本作「嗔」），鮮潔（京本作「解結」）愈爲精。"]', '["太陽畔，氣如剪刀形。","更有散花桃杏（京本作「李」）杂，君王失政后妃稱（京本作「嗔」），鲜潔（京本作「解結」）愈爲精。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc7e5a1-066e-4354-9b87-7a06aff50f2c', '兵要望江南 占日第十一（京本列第六○五十六首） 三十四', '兵要望江南 占日第十一（京本列第六○五十六首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，氣若璧形圓。","其影團圓（京本作「團」）如暈色，羣（京本作「郡」）邦臣下反（京本作「反主」）謀專，奪我境邊田。","（主小臣謀反分國。","京本注：「主小臣謀叛分國侵奪之事。","」）。"]', '["太陽畔，氣若璧形圓。","其影團圓（京本作「團」）如暈色，羣（京本作「郡」）邦臣下反（京本作「反主」）謀專，奪我境邊田。","（主小臣謀反分国。","京本注：「主小臣謀叛分国侵奪之事。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ea4b58-0946-4eca-89ee-e5e292f5d0c7', '兵要望江南 占日第十一（京本列第六○五十六首） 三十五', '兵要望江南 占日第十一（京本列第六○五十六首） 三十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，一樹蒂根成。","兩（京本作「雨」）氣橫生成長拽出，殺君自縊叛臣情，隨帝應其徴。"]', '["太陽畔，一樹蒂根成。","兩（京本作「雨」）氣橫生成长拽出，殺君自縊叛臣情，隨帝應其徴。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d750c4c2-dd91-49bc-9570-82803629edb3', '兵要望江南 占日第十一（京本列第六○五十六首） 三十六', '兵要望江南 占日第十一（京本列第六○五十六首） 三十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔（京本一作「時」），如鼠樹枝（京本一作「林」）間。","又似雞形雙（京本一作「頭」）翅舉（京本作「頤頸勢」），看（京本作「舉」）看洪水作爲（京本作「危」）難，移寨向（京本作「上」）高山。","（京本此首兩見。","）。"]', '["太陽畔（京本一作「时」），如鼠樹枝（京本一作「林」）间。","又似雞形雙（京本一作「头」）翅舉（京本作「頤頸勢」），看（京本作「舉」）看洪水作爲（京本作「危」）难，移寨向（京本作「上」）高山。","（京本此首兩见。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d2ccca-03a2-4011-a9b6-d61e8d23e7e4', '兵要望江南 占日第十一（京本列第六○五十六首） 三十七', '兵要望江南 占日第十一（京本列第六○五十六首） 三十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，帆幔氣堪疑。","又若破船來向（京本作「泊」）岸，仍居乾位帝京基（辛本、川本作「隳」、京本作「墮」），帆落勢傾時（京本作「危」）。"]', '["太陽畔，帆幔氣堪疑。","又若破船来向（京本作「泊」）岸，仍居乾位帝京基（辛本、川本作「隳」、京本作「墮」），帆落勢傾时（京本作「危」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f140dd-6b2b-4d57-9fbd-e0f637287091', '兵要望江南 占日第十一（京本列第六○五十六首） 三十八', '兵要望江南 占日第十一（京本列第六○五十六首） 三十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，五色氣鮮（京本作「祥」）明。","下有奔麞形象具，忠臣遭戮又妖興（京本作「兵」），不可不留情。"]', '["太陽畔，五色氣鲜（京本作「祥」）明。","下有奔麞形象具，忠臣遭戮又妖兴（京本作「兵」），不可不留情。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0327eee-0983-4409-8845-d4ef8cee9b39', '兵要望江南 占日第十一（京本列第六○五十六首） 三十九', '兵要望江南 占日第十一（京本列第六○五十六首） 三十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，十字在中張，大禍欲來先露兆，奸凶懷恨（京本作「詐」）作妖祥，齋醮早消禳。"]', '["太陽畔，十字在中張，大禍欲来先露兆，奸凶懷恨（京本作「詐」）作妖祥，斋醮早消禳。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 三十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6bb088a-64db-4c7f-97dd-043c337c5816', '兵要望江南 占日第十一（京本列第六○五十六首） 四十', '兵要望江南 占日第十一（京本列第六○五十六首） 四十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，氣色似人兵。","若在離邊移寨上，君王易代表臨坰，賢者得其情。"]', '["太陽畔，氣色似人兵。","若在離邊移寨上，君王易代表臨坰，賢者得其情。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b685c43-98d2-4a76-8182-83010f457eb0', '兵要望江南 占日第十一（京本列第六○五十六首） 四十一', '兵要望江南 占日第十一（京本列第六○五十六首） 四十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，兩手在其傍。","更有金星圓出現，后妃作孽亂生狂，乾地（京本作「帝」）應其殃。","（乾符六年二月十八日午時現。","京本「乾符」前有「唐禧宗」三字。","）。"]', '["太陽畔，兩手在其傍。","更有金星圓出現，后妃作孽亂生狂，乾地（京本作「帝」）應其殃。","（乾符六年二月十八日午时現。","京本「乾符」前有「唐禧宗」三字。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d05faab-c9ed-494d-858e-8fcccbc2e307', '兵要望江南 占日第十一（京本列第六○五十六首） 四十二', '兵要望江南 占日第十一（京本列第六○五十六首） 四十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，舉手若兩（京本作「首若雙」）分。","或作箒形居兩手，君王帝位欲分更，不散決然成。","（辛本、川本、京本注：「氣現久不散，其殃必應。","」）。"]', '["太陽畔，舉手若兩（京本作「首若雙」）分。","或作箒形居兩手，君王帝位欲分更，不散決然成。","（辛本、川本、京本注：「氣現久不散，其殃必應。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1516d1d-bec5-4b2c-816f-814cf1bb6678', '兵要望江南 占日第十一（京本列第六○五十六首） 四十三', '兵要望江南 占日第十一（京本列第六○五十六首） 四十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，青氣散如飛。","變作雁行分勢列，外邦小國賊臣欺，謀反禍相隨。"]', '["太陽畔，青氣散如飞。","变作雁行分勢列，外邦小国賊臣欺，謀反禍相隨。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86db0564-1cc1-4efb-b041-886c94c8c15d', '兵要望江南 占日第十一（京本列第六○五十六首） 四十四', '兵要望江南 占日第十一（京本列第六○五十六首） 四十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽畔，若對斗牛間。","更有一虹迎面見，三公流國戰無還，遷改莫辭難。","（京本注：「國主政權應自失。","」）。"]', '["太陽畔，若对斗牛间。","更有一虹迎面见，三公流国戰無還，遷改莫辞难。","（京本注：「国主政權應自失。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628fe1cb-2503-4038-b269-1a06e74de787', '兵要望江南 占日第十一（京本列第六○五十六首） 四十五', '兵要望江南 占日第十一（京本列第六○五十六首） 四十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日邊氣，皆應在蚩尤。","申酉且須看獬豸，喪門申未午時求，見處便堪愁（京本作「憂」）。","。"]', '["日邊氣，皆應在蚩尤。","申酉且須看獬豸，喪门申未午时求，见处便堪愁（京本作「憂」）。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04aa730-35af-4038-9621-8c86e8c37d14', '兵要望江南 占日第十一（京本列第六○五十六首） 四十六', '兵要望江南 占日第十一（京本列第六○五十六首） 四十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日之外，有耳兩邊生。","必有和通同好事（辛本、川本作「善」，京本作「同通好喜」），兩軍不戰結歡欣（京本作「情」），四海得安寧。"]', '["日之外，有耳兩邊生。","必有和通同好事（辛本、川本作「善」，京本作「同通好喜」），兩軍不戰結歡欣（京本作「情」），四海得安寧。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1925c70f-46ce-47fc-bbda-13ddd3f80625', '兵要望江南 占日第十一（京本列第六○五十六首） 四十七', '兵要望江南 占日第十一（京本列第六○五十六首） 四十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["青天象，日月氣來衝。","北面氣衝北面旺，南衝南旺任（川本、辛本、京本作「認」）西東，取此以爲宗（川本、辛本、京本作「蹤」）。"]', '["青天象，日月氣来衝。","北面氣衝北面旺，南衝南旺任（川本、辛本、京本作「認」）西东，取此以爲宗（川本、辛本、京本作「蹤」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849b07e0-2078-44c2-a188-d0cf375d6a4f', '兵要望江南 占日第十一（京本列第六○五十六首） 四十八', '兵要望江南 占日第十一（京本列第六○五十六首） 四十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日色異，黃赤病之源。","色若白時多死兆，更兼兵起禍凶年（京本作「連」），疾疫湊來纏。"]', '["日色異，黄赤病之源。","色若白时多死兆，更兼兵起禍凶年（京本作「連」），疾疫湊来纏。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edce20af-b8c7-4dad-990b-58e32f7bb113', '兵要望江南 占日第十一（京本列第六○五十六首） 四十九', '兵要望江南 占日第十一（京本列第六○五十六首） 四十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日五色，或有氣稜層（京本作「稜」）。","其分國王權政失，躭迷酒色損生靈，修德滅奢矜。"]', '["日五色，或有氣稜層（京本作「稜」）。","其分国王權政失，躭迷酒色損生靈，修德滅奢矜。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 四十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49329003-e0f3-450c-a871-da7114900836', '兵要望江南 占日第十一（京本列第六○五十六首） 五十', '兵要望江南 占日第十一（京本列第六○五十六首） 五十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日紫色，名曰疾萎蕤。","其分起兵多喪敗，且宜修德厭天機，勿起（京本作「忽即」）禍當時。"]', '["日紫色，名曰疾萎蕤。","其分起兵多喪敗，且宜修德厭天機，勿起（京本作「忽即」）禍當时。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27e3f59-a622-480d-9d89-8a4fc041852f', '兵要望江南 占日第十一（京本列第六○五十六首） 五十一', '兵要望江南 占日第十一（京本列第六○五十六首） 五十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日有耳，兩耳戰均平。","厚處必贏軍占取，一邊有耳一邊贏，無戰喜交兵。"]', '["日有耳，兩耳戰均平。","厚处必贏軍占取，一邊有耳一邊贏，無戰喜交兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c323cc15-90b8-4e00-bbd4-db87fe2faeff', '兵要望江南 占日第十一（京本列第六○五十六首） 五十二', '兵要望江南 占日第十一（京本列第六○五十六首） 五十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日色青，其分國堪傷。","或似火光兼火影，皆爲災亂殄忠良，防備賊臨疆。"]', '["日色青，其分国堪傷。","或似火光兼火影，皆爲災亂殄忠良，防備賊臨疆。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50592118-2c2f-4b1d-9ca5-c7c12643625e', '兵要望江南 占日第十一（京本列第六○五十六首） 五十三', '兵要望江南 占日第十一（京本列第六○五十六首） 五十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日生暈，須有暈形圓。","其形如暈圓其圓（辛本、川本作「圓圓背」），皆主邦臣（辛本、川本作「那邦臣子」）叛謀專，奪取境邊田。"]', '["日生暈，須有暈形圓。","其形如暈圓其圓（辛本、川本作「圓圓背」），皆主邦臣（辛本、川本作「那邦臣子」）叛謀專，奪取境邊田。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1890023-b479-44d0-af6f-9b64e9b2caf3', '兵要望江南 占日第十一（京本列第六○五十六首） 五十四', '兵要望江南 占日第十一（京本列第六○五十六首） 五十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日四耳，頂上即爲冠。","兩下爲纓須盡日，下爲履象不爲權，回報日須端。","（經曰：「日上爲冠，下爲履，兩下爲耳，長而爲纓，朝抱日吉。","」）。"]', '["日四耳，頂上即爲冠。","兩下爲纓須尽日，下爲履象不爲權，回報日須端。","（經曰：「日上爲冠，下爲履，兩下爲耳，长而爲纓，朝抱日吉。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac81882f-ff87-41b7-a50b-ffa6341bce97', '兵要望江南 占日第十一（京本列第六○五十六首） 五十五', '兵要望江南 占日第十一（京本列第六○五十六首） 五十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陽位，下復見形圓。","便若白來其色黑，王更國變別憂權，一日見憂煎。"]', '["太陽位，下复见形圓。","便若白来其色黑，王更国变別憂權，一日见憂煎。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7453c9-d52a-492c-a598-e5e1f023e418', '兵要望江南 占日第十一（京本列第六○五十六首） 五十六', '兵要望江南 占日第十一（京本列第六○五十六首） 五十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日出現，便若似（川本作「是」）臙脂。","蔭（辛本作「映」）地滿天血如染，此爲天（川本作「大」）殺苦軍權，七日雨平川。","（無雨主火災。","）。"]', '["日出現，便若似（川本作「是」）臙脂。","蔭（辛本作「映」）地满天血如染，此爲天（川本作「大」）殺苦軍權，七日雨平川。","（無雨主火災。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占日第十一（京本列第六○五十六首） 五十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1186db7-fc71-4745-9507-9f573a4b67c5', '兵要望江南 占月第十二（京本列第七○二十三首） 一', '兵要望江南 占月第十二（京本列第七○二十三首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陰位，爲后又爲臣。","凡有象形凶吉定，行兵主帥要知明，一一細分清（辛本、川本作「情」）。"]', '["太陰位，爲后又爲臣。","凡有象形凶吉定，行兵主帥要知明，一一細分清（辛本、川本作「情」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846f9d10-5e6e-4d85-b15e-ae4a907735a6', '兵要望江南 占月第十二（京本列第七○二十三首） 二', '兵要望江南 占月第十二（京本列第七○二十三首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占圓月，下小彼軍多。","若總（京本作「見」）大時占我衆（京本作「勝」），全（京本作「總」）無大小亦相和，青白定（京本作「早」）回戈。"]', '["占圓月，下小彼軍多。","若總（京本作「见」）大时占我衆（京本作「勝」），全（京本作「總」）無大小亦相和，青白定（京本作「早」）回戈。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b021a2-0896-45f1-842d-8b117d0d2c1f', '兵要望江南 占月第十二（京本列第七○二十三首） 三', '兵要望江南 占月第十二（京本列第七○二十三首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["出軍夜，看月好參詳。","有兔主人占大勝，兔無反（京本作「無兔還」）是客軍強，仔細審形相（京本作「須要細端詳」）。"]', '["出軍夜，看月好參詳。","有兔主人占大勝，兔無反（京本作「無兔還」）是客軍強，仔細審形相（京本作「須要細端詳」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f7f368-daa0-4eb6-8282-3305e9ea7c9a', '兵要望江南 占月第十二（京本列第七○二十三首） 四', '兵要望江南 占月第十二（京本列第七○二十三首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占夜月，五色氣相當。","此是（京本作「時」）交兵須謹（京本作「警」）慎，直須拚（京本作「挨」）得賞兒郎，慳吝必相傷。"]', '["占夜月，五色氣相當。","此是（京本作「时」）交兵須謹（京本作「警」）慎，直須拚（京本作「挨」）得賞兒郎，慳吝必相傷。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37a1b7d-9e5e-4f27-9572-da345834353b', '兵要望江南 占月第十二（京本列第七○二十三首） 五', '兵要望江南 占月第十二（京本列第七○二十三首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太陰內，有暈使人驚。","其象分明如刀字（京本作「刃」），奸臣謀反事將成，密究速加刑（京本作「庶無凶」）。"]', '["太陰內，有暈使人驚。","其象分明如刀字（京本作「刃」），奸臣謀反事將成，密究速加刑（京本作「庶無凶」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388c03a4-2f45-4d69-b4ca-c1de24284cf5', '兵要望江南 占月第十二（京本列第七○二十三首） 六', '兵要望江南 占月第十二（京本列第七○二十三首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["守彼壘，吾督將須攻。","月色無光灰（京本作「如」）粉樣，拔城不過一旬中，守將亦須凶。"]', '["守彼壘，吾督將須攻。","月色無光灰（京本作「如」）粉樣，拔城不過一旬中，守將亦須凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584228a5-3d00-4c91-90b5-9c04f8bb8261', '兵要望江南 占月第十二（京本列第七○二十三首） 七', '兵要望江南 占月第十二（京本列第七○二十三首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看夜月，五色氣相衝。","皆（京本作「此」）是將災宜（京本作「須」）謹慎，直須重賞宴軍中，堅執禍相逢。"]', '["看夜月，五色氣相衝。","皆（京本作「此」）是將災宜（京本作「須」）謹慎，直須重賞宴軍中，堅執禍相逢。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aabd0e1-e16e-4127-84f9-1fffa495c81a', '兵要望江南 占月第十二（京本列第七○二十三首） 八', '兵要望江南 占月第十二（京本列第七○二十三首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月生暈，厚薄四方停。","此是三軍均力象，一邊有抱一（辛本、川本、京本作「抱」）邊贏，順抱若神兵。"]', '["月生暈，厚薄四方停。","此是三軍均力象，一邊有抱一（辛本、川本、京本作「抱」）邊贏，順抱若神兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca7b956-233b-4895-bc87-7ff87b2b7f91', '兵要望江南 占月第十二（京本列第七○二十三首） 九', '兵要望江南 占月第十二（京本列第七○二十三首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月生暈，暈有珥兼生。","將有火（京本作「大」）災難閃避，三朝有雨得安寧，無雨禍還（京本作「須」）成。"]', '["月生暈，暈有珥兼生。","將有火（京本作「大」）災难閃避，三朝有雨得安寧，無雨禍還（京本作「須」）成。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace2987b-8f5c-4902-a3df-ec385456e1f5', '兵要望江南 占月第十二（京本列第七○二十三首） 十', '兵要望江南 占月第十二（京本列第七○二十三首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月生暈，暈內有流星。","當有貴人奔出走。","客星入側將當驚，國亦不安寧。"]', '["月生暈，暈內有流星。","當有貴人奔出走。","客星入側將當驚，国亦不安寧。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('242af7ff-2bb0-4c9c-92a5-f79e982d6c68', '兵要望江南 占月第十二（京本列第七○二十三首） 十一', '兵要望江南 占月第十二（京本列第七○二十三首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月如赭，莫戰最爲良。","若或不依（京本作「不依言」）須見敗，客軍得勝主軍傷，宜且守封疆。","（京本注：「先出客，後出主。","」）。"]', '["月如赭，莫戰最爲良。","若或不依（京本作「不依言」）須见敗，客軍得勝主軍傷，宜且守封疆。","（京本注：「先出客，後出主。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ee3d91-868c-4f44-bac1-1b61a111c3f6', '兵要望江南 占月第十二（京本列第七○二十三首） 十二', '兵要望江南 占月第十二（京本列第七○二十三首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["相鬬敵，月滿色無光。","客勝主衰（京本作「虧」）須謹慎，忽然交戰主難當，城內欲投降。"]', '["相鬬敵，月满色無光。","客勝主衰（京本作「虧」）須謹慎，忽然交戰主难當，城內欲投降。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961decb8-29a5-4a81-a595-e8956c4c0442', '兵要望江南 占月第十二（京本列第七○二十三首） 十三', '兵要望江南 占月第十二（京本列第七○二十三首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雙月現，現則有兵荒。","兩兩三三俱荒亂（辛本、川本、京本作「亂出」），當其現處有（辛本、川本、京本作「競」）猖狂，人馬兩（京本作「死及」）逃亡。"]', '["雙月現，現則有兵荒。","兩兩三三俱荒亂（辛本、川本、京本作「亂出」），當其現处有（辛本、川本、京本作「競」）猖狂，人马兩（京本作「死及」）逃亡。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a95070-b0b7-4a3b-8916-68d5f614e0ce', '兵要望江南 占月第十二（京本列第七○二十三首） 十四', '兵要望江南 占月第十二（京本列第七○二十三首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兩月鬬，侯景犯梁朝。","倘或遭逢如此兆，外藩（京本作「番」）雄略（京本作「客」）有謀韜，俱廢若（京本作「永」）冰消。"]', '["兩月鬬，侯景犯梁朝。","倘或遭逢如此兆，外藩（京本作「番」）雄略（京本作「客」）有謀韜，俱廢若（京本作「永」）冰消。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb1eeff-ce8e-493c-b6f9-7ea30aa51fb6', '兵要望江南 占月第十二（京本列第七○二十三首） 十五', '兵要望江南 占月第十二（京本列第七○二十三首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵在外，月色（辛本、川本作「蝕」、京本作「食」）八分強。","軍欲還鄉須（京本作「休」）罷戰，忽然蝕盡倒城亡，將死向郊（京本作「饑」）荒。"]', '["兵在外，月色（辛本、川本作「蝕」、京本作「食」）八分強。","軍欲還乡須（京本作「休」）罷戰，忽然蝕尽倒城亡，將死向郊（京本作「饑」）荒。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbec7dbf-53ec-41f3-8827-ef8fdde96739', '兵要望江南 占月第十二（京本列第七○二十三首） 十六', '兵要望江南 占月第十二（京本列第七○二十三首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太平夕（京本作「久」），月破作三分。","四海荒荒興逆叛，都緣人主寵奢昏（京本作「民」），草寇輒稱尊。"]', '["太平夕（京本作「久」），月破作三分。","四海荒荒兴逆叛，都緣人主寵奢昏（京本作「民」），草寇輒稱尊。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2bf5ad-a740-4dcc-8d18-06e6fb1e24cf', '兵要望江南 占月第十二（京本列第七○二十三首） 十七', '兵要望江南 占月第十二（京本列第七○二十三首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月黃色，分野現明光。","此是將軍遷（京本作「還」）職象，彼師我衆兩無傷。","各自守封疆。"]', '["月黄色，分野現明光。","此是將軍遷（京本作「還」）職象，彼師我衆兩無傷。","各自守封疆。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adecc713-ad00-4c20-bd4b-f9a0bf8d1557', '兵要望江南 占月第十二（京本列第七○二十三首） 十八', '兵要望江南 占月第十二（京本列第七○二十三首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月邊氣，其象若羣猪。","羽姓將軍兵大吉，宮商角徴不占拘（京本作「推」），把捉顧方隅。"]', '["月邊氣，其象若羣猪。","羽姓將軍兵大吉，宮商角徴不占拘（京本作「推」），把捉顧方隅。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a51eee9-858e-4e47-965a-6f1c52279208', '兵要望江南 占月第十二（京本列第七○二十三首） 十九', '兵要望江南 占月第十二（京本列第七○二十三首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["十五夜，月缺不團圓。","一面凸凹三兩處，近臣怪（辛本、川本作「懷」）怨（京本作「懷恨」）奪君權，急究反情原。"]', '["十五夜，月缺不團圓。","一面凸凹三兩处，近臣怪（辛本、川本作「懷」）怨（京本作「懷恨」）奪君權，急究反情原。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d194700-4a87-4344-8b4a-189745a2b844', '兵要望江南 占月第十二（京本列第七○二十三首） 二十', '兵要望江南 占月第十二（京本列第七○二十三首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金入月，星朗月無光。","星蝕太陰臣造逆，月明星暗將身（辛本、川本作「星」）亡。","星沒客軍傷。"]', '["金入月，星朗月無光。","星蝕太陰臣造逆，月明星暗將身（辛本、川本作「星」）亡。","星沒客軍傷。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e93d77-9b8e-42a8-941e-a842f2cfbe5e', '兵要望江南 占月第十二（京本列第七○二十三首） 二十一', '兵要望江南 占月第十二（京本列第七○二十三首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金與月，俱出在西方。","星北北方軍必勝，星南南面將身（辛本、川本作「星」）強，月白（辛本、川本作「向」）將兵亡。"]', '["金與月，俱出在西方。","星北北方軍必勝，星南南面將身（辛本、川本作「星」）強，月白（辛本、川本作「向」）將兵亡。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9b571a-8270-4a0c-9323-dc25311fb49a', '兵要望江南 占月第十二（京本列第七○二十三首） 二十二', '兵要望江南 占月第十二（京本列第七○二十三首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金月暈，星暗月昏昏。","客必敗亡須好認，木星三暈將（辛本、川本、京本作「宰」）臣奔。","天象顯然分。"]', '["金月暈，星暗月昏昏。","客必敗亡須好認，木星三暈將（辛本、川本、京本作「宰」）臣奔。","天象显然分。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19201806-2b56-4987-a781-4ab4c6e95950', '兵要望江南 占月第十二（京本列第七○二十三首） 二十三', '兵要望江南 占月第十二（京本列第七○二十三首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月有暈，白虹向中穿。","天下大兵看即起，更兼壯士執仇冤，大（辛本、川本作「日」）怒氣衝天。"]', '["月有暈，白虹向中穿。","天下大兵看即起，更兼壯士執仇冤，大（辛本、川本作「日」）怒氣衝天。"]', '诗', 'shi', '', NULL, '兵要望江南 占月第十二（京本列第七○二十三首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad0e9d4-85a8-4c63-8a7c-209131595324', '兵要望江南 占星第十三（京本列第五○四十三首） 一', '兵要望江南 占星第十三（京本列第五○四十三首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵要法（京本作「訣」），爲主認星辰。","伏逆遲留（京本作「留時」）須固守，更看金（京本作「堪全」）現便（京本作「使」）宜行，俱伏兩均平。"]', '["兵要法（京本作「訣」），爲主認星辰。","伏逆遲留（京本作「留时」）須固守，更看金（京本作「堪全」）現便（京本作「使」）宜行，俱伏兩均平。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5368333-faa7-4b19-bff4-0043d4e23dc0', '兵要望江南 占星第十三（京本列第五○四十三首） 二', '兵要望江南 占星第十三（京本列第五○四十三首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵要訣，爲主（京本作「客」）認金星。","若也伏藏休動作，逆行逆戰亦均平，順則最宜行。","（星退宜退，星進宜進。","）。"]', '["兵要訣，爲主（京本作「客」）認金星。","若也伏藏休动作，逆行逆戰亦均平，順則最宜行。","（星退宜退，星進宜進。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8131c769-af1f-4121-b4b9-5e46ff34f115', '兵要望江南 占星第十三（京本列第五○四十三首） 三', '兵要望江南 占星第十三（京本列第五○四十三首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金與火，統帥識星無。","須算（辛本、川本作「等」）行藏知決勝，何須堅執講星孤，諸事細參圖。"]', '["金與火，統帥識星無。","須算（辛本、川本作「等」）行藏知決勝，何須堅執講星孤，諸事細參圖。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('766a09c7-dfc9-471d-b0fe-c4ce36167fd2', '兵要望江南 占星第十三（京本列第五○四十三首） 四', '兵要望江南 占星第十三（京本列第五○四十三首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["土星合，相犯必爲災。","分野居（京本作「老」、辛本作「若」）當須有事，本藩太守禍之胎，修德免災（京本作「殃」）來。"]', '["土星合，相犯必爲災。","分野居（京本作「老」、辛本作「若」）當須有事，本藩太守禍之胎，修德免災（京本作「殃」）来。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b3eb19-344e-41bc-8e11-724f51929fc4', '兵要望江南 占星第十三（京本列第五○四十三首） 五', '兵要望江南 占星第十三（京本列第五○四十三首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["三星聚，晉宋爲居（辛本、川本作「兼」、京本作「衛兼」）唐。","此地將軍須就獄，總兵主帥作猖狂，斬首獻明（京本作「君」）王。"]', '["三星聚，晉宋爲居（辛本、川本作「兼」、京本作「衛兼」）唐。","此地將軍須就獄，總兵主帥作猖狂，斬首獻明（京本作「君」）王。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa166bba-5730-4cf7-b354-dfe796517607', '兵要望江南 占星第十三（京本列第五○四十三首） 六', '兵要望江南 占星第十三（京本列第五○四十三首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["四星聚，平地（辛本、川本、京本作「帝」）會張星。","王莽赤眉兵造起，後來光武掃餘（京本作「除」）兵，晉魏也曾更（京本作「經」）。"]', '["四星聚，平地（辛本、川本、京本作「帝」）會張星。","王莽赤眉兵造起，後来光武掃餘（京本作「除」）兵，晉魏也曾更（京本作「經」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bbf0198-8139-48a1-99e8-cafd6247acd2', '兵要望江南 占星第十三（京本列第五○四十三首） 七', '兵要望江南 占星第十三（京本列第五○四十三首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["五星聚，漢祖得其時。","秦滅漢兵東井會，君王起事合天機，星會尾如（京本作「聚尾和」）箕。"]', '["五星聚，漢祖得其时。","秦滅漢兵东井會，君王起事合天機，星會尾如（京本作「聚尾和」）箕。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b0b4d6-2b30-453b-b76d-66595a442741', '兵要望江南 占星第十三（京本列第五○四十三首） 八', '兵要望江南 占星第十三（京本列第五○四十三首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星落寨，爲將恐遭殃。","宜速移營方見吉，堅強舊所必凶傷，天降禍相（辛本、川本、京本作「難」）當。"]', '["星落寨，爲將恐遭殃。","宜速移營方见吉，堅強旧所必凶傷，天降禍相（辛本、川本、京本作「难」）當。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78c9475-f92a-47de-976d-c5c9fdbaa6cb', '兵要望江南 占星第十三（京本列第五○四十三首） 九', '兵要望江南 占星第十三（京本列第五○四十三首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星相打，攻守兩茫茫（京本作「忙忙」）。","遇戰血流交滿野（京本作「遇賊血流郊野滿」），攻城不下好隄防，宴犒賞兒郎。"]', '["星相打，攻守兩茫茫（京本作「忙忙」）。","遇戰血流交满野（京本作「遇賊血流郊野满」），攻城不下好隄防，宴犒賞兒郎。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924ed5da-8031-4633-b1ab-ffdc06dc37d0', '兵要望江南 占星第十三（京本列第五○四十三首） 十', '兵要望江南 占星第十三（京本列第五○四十三首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金星畔，邊有小星侵。","相去不過咫尺遠，客軍當敗將消沉，兵罷只如今。","（凡金星爲將星，專主兵權兆。","京本注：「金星專主兵權之事。","」）。"]', '["金星畔，邊有小星侵。","相去不過咫尺远，客軍當敗將消沉，兵罷只如今。","（凡金星爲將星，專主兵權兆。","京本注：「金星專主兵權之事。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c45c8c-73d3-43e7-ad70-f1df12b17617', '兵要望江南 占星第十三（京本列第五○四十三首） 十一', '兵要望江南 占星第十三（京本列第五○四十三首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金星（京本作「行」）疾，急戰定應（京本作「須」）贏。","行若緩時須固守，星高攻（京本作「遠」）戰有功名，低害（京本作「則」）莫深征。"]', '["金星（京本作「行」）疾，急戰定應（京本作「須」）贏。","行若緩时須固守，星高攻（京本作「远」）戰有功名，低害（京本作「則」）莫深征。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b78ca9e-ca3c-4036-bda3-0465f8528fd3', '兵要望江南 占星第十三（京本列第五○四十三首） 十二', '兵要望江南 占星第十三（京本列第五○四十三首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金芒角（京本作「金星落」），隨角出軍征。","若有焰光如掃箒，亦名天狗食妖兵，其下血成坑。","（如螻赴水，其下必敗。","）。"]', '["金芒角（京本作「金星落」），隨角出軍征。","若有焰光如掃箒，亦名天狗食妖兵，其下血成坑。","（如螻赴水，其下必敗。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce43a491-58cb-4dbc-8d1d-105665ef7df2', '兵要望江南 占星第十三（京本列第五○四十三首） 十三', '兵要望江南 占星第十三（京本列第五○四十三首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占星宿，伏現在西東。","星若近南南必勝，忽然近北北宜攻，專祖此爲宗（辛本、川本作「蹤」）。"]', '["占星宿，伏現在西东。","星若近南南必勝，忽然近北北宜攻，專祖此爲宗（辛本、川本作「蹤」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d561015-7f23-4259-a7e7-43e656dd5067', '兵要望江南 占星第十三（京本列第五○四十三首） 十四', '兵要望江南 占星第十三（京本列第五○四十三首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金星出，出在卯中央。","東面兵強莫（京本作「休」）與戰，西出西方不可當（京本作「出西面酉酉難當」），勿與動鋒鎗（辛本、川本作「鬬刀鎗」，京本作「勿與鬬鋒芒」）。"]', '["金星出，出在卯中央。","东面兵強莫（京本作「休」）與戰，西出西方不可當（京本作「出西面酉酉难當」），勿與动鋒鎗（辛本、川本作「鬬刀鎗」，京本作「勿與鬬鋒芒」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95111db8-d65f-459e-8bb8-01a03362fd92', '兵要望江南 占星第十三（京本列第五○四十三首） 十五', '兵要望江南 占星第十三（京本列第五○四十三首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金西伏，木（京本作「未」）出現東方。","軍在西南休進戰，二星同出現東方，西若戰須亡。","（或水或木星。","）。"]', '["金西伏，木（京本作「未」）出現东方。","軍在西南休進戰，二星同出現东方，西若戰須亡。","（或水或木星。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301655e4-e93c-44a4-b275-4db4abfdb02c', '兵要望江南 占星第十三（京本列第五○四十三首） 十六', '兵要望江南 占星第十三（京本列第五○四十三首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金東伏，木（京本作「未」）出現西方。","東北二方須敗走，忽然同出在西方（京本作「現在旁」），東面不能當。"]', '["金东伏，木（京本作「未」）出現西方。","东北二方須敗走，忽然同出在西方（京本作「現在旁」），东面不能當。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21b9d806-99f0-42b5-b0ff-bbe6fe124fa2', '兵要望江南 占星第十三（京本列第五○四十三首） 十七', '兵要望江南 占星第十三（京本列第五○四十三首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["同伏現，相去尺餘同。","交戰將兵須有應，水居月上戰應先（京本作「鬬」），月內必師還。","（水在月上也。","）。"]', '["同伏現，相去尺餘同。","交戰將兵須有應，水居月上戰應先（京本作「鬬」），月內必師還。","（水在月上也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d6d2c6-bb91-409f-a3f9-c5e840f2e6da', '兵要望江南 占星第十三（京本列第五○四十三首） 十八', '兵要望江南 占星第十三（京本列第五○四十三首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["欃星現，分野在（京本作「出」）何方。","若是正臨災在即，忽然頭尾也遭殃，仁德可脩禳。"]', '["欃星現，分野在（京本作「出」）何方。","若是正臨災在即，忽然头尾也遭殃，仁德可脩禳。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9259bcc5-03d9-42e5-b096-93af34071593', '兵要望江南 占星第十三（京本列第五○四十三首） 十九', '兵要望江南 占星第十三（京本列第五○四十三首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星一箇，無尾赤（京本作「亦」）兼青。","直下落來營寨上，急須遷去別爲營，此地定無成。"]', '["星一箇，無尾赤（京本作「亦」）兼青。","直下落来營寨上，急須遷去別爲營，此地定無成。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb02074-d9b8-47fa-ab24-50dfce2fb1d6', '兵要望江南 占星第十三（京本列第五○四十三首） 二十', '兵要望江南 占星第十三（京本列第五○四十三首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金晝現，名號是經天。","其分用兵兵必罷，未曾動處却兵連，人馬滿郊田。","（已動敗，未動易政。","）。"]', '["金晝現，名號是經天。","其分用兵兵必罷，未曾动处却兵連，人马满郊田。","（已动敗，未动易政。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('446a7137-32a0-4b65-8611-c3eb64cbf2cb', '兵要望江南 占星第十三（京本列第五○四十三首） 二十一', '兵要望江南 占星第十三（京本列第五○四十三首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星晝隕，聲震響如雷。","赤白或長三五丈，忽然更有小星陪，軍勢若寒灰。"]', '["星晝隕，声震响如雷。","赤白或长三五丈，忽然更有小星陪，軍勢若寒灰。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24fff1da-45d6-4878-a470-9578e7348c12', '兵要望江南 占星第十三（京本列第五○四十三首） 二十二', '兵要望江南 占星第十三（京本列第五○四十三首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星晝隕，其地定爲災（京本作「其下地殃危」）。","必有火焚軍寨柵，兼防將士涉沙泥（京本作「垝」），移寨（京本作「去」）莫徘徊。"]', '["星晝隕，其地定爲災（京本作「其下地殃危」）。","必有火焚軍寨柵，兼防將士涉沙泥（京本作「垝」），移寨（京本作「去」）莫徘徊。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc5bb28-e3fc-47ea-b91d-c2349afac1b8', '兵要望江南 占星第十三（京本列第五○四十三首） 二十三', '兵要望江南 占星第十三（京本列第五○四十三首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，斗大墜星來。","或是作聲長數丈，其間大戰將星移（京本作「身摧」），急去免災危。","（京本注：「孔明、祖逖，皆有此兆。","」）。"]', '["軍營內，斗大墜星来。","或是作声长數丈，其间大戰將星移（京本作「身摧」），急去免災危。","（京本注：「孔明、祖逖，皆有此兆。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5b17e84-ca45-4f2a-b9fa-13a6e8acb403', '兵要望江南 占星第十三（京本列第五○四十三首） 二十四', '兵要望江南 占星第十三（京本列第五○四十三首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，星隕落其間。","拽尾或長三五尺（辛本、川本、京本作「丈」），皆爲敗陣（辛本、川本、京本作「證」）莫（京本作「欲」）相殘，急去免災（京本作「凶」）奸。","（孔明、祖逖皆有此兆。","）。"]', '["軍營內，星隕落其间。","拽尾或长三五尺（辛本、川本、京本作「丈」），皆爲敗陣（辛本、川本、京本作「證」）莫（京本作「欲」）相殘，急去免災（京本作「凶」）奸。","（孔明、祖逖皆有此兆。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b8bc205-9493-4eeb-8416-3c43a522ffd3', '兵要望江南 占星第十三（京本列第五○四十三首） 二十五', '兵要望江南 占星第十三（京本列第五○四十三首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，星隕作驢鳴（京本作「形」）。","兆是（京本作「此兆」）敗軍幷殺將，便須移寨不須（京本作「當返不當」）停，天意甚分明。","。"]', '["軍營內，星隕作驢鳴（京本作「形」）。","兆是（京本作「此兆」）敗軍幷殺將，便須移寨不須（京本作「當返不當」）停，天意甚分明。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf7aacfc-b8a3-49fc-a6cb-3da520ab2569', '兵要望江南 占星第十三（京本列第五○四十三首） 二十六', '兵要望江南 占星第十三（京本列第五○四十三首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨內，星火殞其中。","芒角光明兼（京本作「並」）曳尾，急須移寨避災凶，不去禍重重。"]', '["營寨內，星火殞其中。","芒角光明兼（京本作「並」）曳尾，急須移寨避災凶，不去禍重重。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a50669f-557f-4d5a-aad3-08ef1302c5b9', '兵要望江南 占星第十三（京本列第五○四十三首） 二十七', '兵要望江南 占星第十三（京本列第五○四十三首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["出軍法，夜與日相殊。","彼上有光（京本作「星」）兼月朗，我軍上面暗稀疎，進戰決成輸。"]', '["出軍法，夜與日相殊。","彼上有光（京本作「星」）兼月朗，我軍上面暗稀疎，進戰決成輸。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e7dea6-acd1-412e-8b60-44195e05778c', '兵要望江南 占星第十三（京本列第五○四十三首） 二十八', '兵要望江南 占星第十三（京本列第五○四十三首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星晝隕，分作二三星。","此是兵戈將欲動，須防敵國別來侵（京本作「必來爭」），陰賊逆謀生。"]', '["星晝隕，分作二三星。","此是兵戈將欲动，須防敵国別来侵（京本作「必来爭」），陰賊逆謀生。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ce0c122-9618-430f-bdff-62bb68a25e4f', '兵要望江南 占星第十三（京本列第五○四十三首） 二十九', '兵要望江南 占星第十三（京本列第五○四十三首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["吾守壁，月內一星明。","必是外奸來入壘，期于半夜害吾城，搜（京本作「招」）捉審奸情。"]', '["吾守壁，月內一星明。","必是外奸来入壘，期于半夜害吾城，搜（京本作「招」）捉審奸情。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1d548c-774b-4dea-920d-690a3ad3c09d', '兵要望江南 占星第十三（京本列第五○四十三首） 三十', '兵要望江南 占星第十三（京本列第五○四十三首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["提大衆，欲打破城牆。","月左（京本作「上」）有星占上角，城中賢將有謀方，速退莫施張。"]', '["提大衆，欲打破城牆。","月左（京本作「上」）有星占上角，城中賢將有謀方，速退莫施張。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01a66910-926a-461e-9198-a925b02759fd', '兵要望江南 占星第十三（京本列第五○四十三首） 三十一', '兵要望江南 占星第十三（京本列第五○四十三首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["敵守壘，我力有餘攻。","月下有星相近駐，彼城奸欲亂吾中，門戶審其蹤。"]', '["敵守壘，我力有餘攻。","月下有星相近駐，彼城奸欲亂吾中，门戶審其蹤。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca0ae59-229e-4f69-bbbe-25776fb4bd95', '兵要望江南 占星第十三（京本列第五○四十三首） 三十二', '兵要望江南 占星第十三（京本列第五○四十三首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["圍彼久，月背一星隨。","壁（京本作「城」）內敵人謀走北，其城沉潰不須摧，捷報凱歌回。"]', '["圍彼久，月背一星隨。","壁（京本作「城」）內敵人謀走北，其城沉潰不須摧，捷報凱歌回。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8742ec95-0651-45dc-8f8c-bb0aa5ec421c', '兵要望江南 占星第十三（京本列第五○四十三首） 三十三', '兵要望江南 占星第十三（京本列第五○四十三首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["觀敵壘，月背有（辛本、川本、京本作「見」）三星。","狀若連珠敵便遁，不須攻打自安平，撫衆勿殘生。"]', '["观敵壘，月背有（辛本、川本、京本作「见」）三星。","狀若連珠敵便遁，不須攻打自安平，撫衆勿殘生。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b5146e-e8bf-4ae1-afe6-855543520bff', '兵要望江南 占星第十三（京本列第五○四十三首） 三十四', '兵要望江南 占星第十三（京本列第五○四十三首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍馬進，月畔見三星。","形似三星將月捧，攻城（京本作「圍」）不下戰無成，擇地設營停（京本作「再安營」。","候過旬日，別看氣候。","）。"]', '["軍马進，月畔见三星。","形似三星將月捧，攻城（京本作「圍」）不下戰無成，擇地設營停（京本作「再安營」。","候過旬日，別看氣候。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf50f0a-9757-48a7-8c73-1dd0af7690e0', '兵要望江南 占星第十三（京本列第五○四十三首） 三十五', '兵要望江南 占星第十三（京本列第五○四十三首） 三十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["攻彼（京本作「破」）壘，月下見（京本作「列」）三星。","城內詐降設（京本作「施」）巧計，急當準（京本作「整」）備出（京本作「突」）師征，莫信詐爲誠。"]', '["攻彼（京本作「破」）壘，月下见（京本作「列」）三星。","城內詐降設（京本作「施」）巧計，急當準（京本作「整」）備出（京本作「突」）師征，莫信詐爲誠。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54c2eca8-01ac-4b65-ae19-d1f796b800da', '兵要望江南 占星第十三（京本列第五○四十三首） 三十六', '兵要望江南 占星第十三（京本列第五○四十三首） 三十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["圍彼壘，月角露三星。","亦（京本作「形」）類三台侵抱月，其城難取枉亡（京本作「勞」）兵，別處設謀贏。"]', '["圍彼壘，月角露三星。","亦（京本作「形」）類三台侵抱月，其城难取枉亡（京本作「勞」）兵，別处設謀贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48c79c1-fb2b-48f7-b297-9bcfd649f9cb', '兵要望江南 占星第十三（京本列第五○四十三首） 三十七', '兵要望江南 占星第十三（京本列第五○四十三首） 三十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["彗星見，出在（京本作「自」）月旁邊。","必有弒君幷殺父，國中紛擾禍相連，更主易桑田。"]', '["彗星见，出在（京本作「自」）月旁邊。","必有弒君幷殺父，国中紛擾禍相連，更主易桑田。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcd5eec-344d-4f45-8d79-4dd402aee152', '兵要望江南 占星第十三（京本列第五○四十三首） 三十八', '兵要望江南 占星第十三（京本列第五○四十三首） 三十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金臨水（辛本、川本作「本」），三五寸金分。","少婦合憂生哭泣，又見鬬將見災凶，偏將喪郊中。"]', '["金臨水（辛本、川本作「本」），三五寸金分。","少婦合憂生哭泣，又见鬬將见災凶，偏將喪郊中。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01eedcf8-1414-494b-ac80-18a2630769df', '兵要望江南 占星第十三（京本列第五○四十三首） 三十九', '兵要望江南 占星第十三（京本列第五○四十三首） 三十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星墜地，鳴下似雷聲。","著把（辛本、川本作「地」）更（辛本、川本作「便」）如焚薪狀，此爲天狗食人民。","百日見災生。","。"]', '["星墜地，鳴下似雷声。","著把（辛本、川本作「地」）更（辛本、川本作「便」）如焚薪狀，此爲天狗食人民。","百日见災生。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 三十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d818b5b-535d-4de9-a08d-75c389513e88', '兵要望江南 占星第十三（京本列第五○四十三首） 四十', '兵要望江南 占星第十三（京本列第五○四十三首） 四十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["慧星現，但看出何方。","定主國君喪性命，不過百日見驚亡，減（辛本、川本作「咸」）滅在君王。"]', '["慧星現，但看出何方。","定主国君喪性命，不過百日见驚亡，減（辛本、川本作「咸」）滅在君王。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 四十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79894ba3-8429-45da-bb8a-002754e1d1e2', '兵要望江南 占星第十三（京本列第五○四十三首） 四十一', '兵要望江南 占星第十三（京本列第五○四十三首） 四十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太白犯，昴畢二星纏。","定主逆臣謀國主，馬奔人走喪中原，入昴赦人原。"]', '["太白犯，昴畢二星纏。","定主逆臣謀国主，马奔人走喪中原，入昴赦人原。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 四十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d19e3c7-88ae-4649-8a78-9abee1744dd4', '兵要望江南 占星第十三（京本列第五○四十三首） 四十二', '兵要望江南 占星第十三（京本列第五○四十三首） 四十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金與水，二曜若侵凌。","定主破軍幷殺將，水居（首本作「君」，茲從辛本、川本）金上客軍贏，在下主和平。"]', '["金與水，二曜若侵凌。","定主破軍幷殺將，水居（首本作「君」，茲從辛本、川本）金上客軍贏，在下主和平。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 四十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c8ab8c-2a0a-4a33-87cd-511d99afe525', '兵要望江南 占星第十三（京本列第五○四十三首） 四十三', '兵要望江南 占星第十三（京本列第五○四十三首） 四十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["慧星現，從斗向南行。","經過垣牆天市界，外邊兵寇界相臨，損將血成坑。"]', '["慧星現，從斗向南行。","經過垣牆天市界，外邊兵寇界相臨，損將血成坑。"]', '诗', 'shi', '', NULL, '兵要望江南 占星第十三（京本列第五○四十三首） 四十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01dc0496-5517-410e-a6dc-837f1d88b613', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 一', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡北斗，斗乃衆星魁。","天上衆星難相犯，若來相犯有災危，占候者須知。"]', '["凡北斗，斗乃衆星魁。","天上衆星难相犯，若来相犯有災危，占候者須知。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09993c7-f6c1-4040-a8d3-b2a53db60cc8', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 二', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["斗口內，慧現出光芒。","海內兵戈俱大起，江河流絕業成（京本作「田」）荒，民作甲兵糧。"]', '["斗口內，慧現出光芒。","海內兵戈俱大起，江河流絕業成（京本作「田」）荒，民作甲兵糧。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9618368-7ca4-4b4b-b75a-4a460be80315', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 三', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["北斗內，穿出慧星輝。","國內主君邊寨（京本作「塞」）將，陰謀惡黨起旌麾（京本作「強圍」），着意謹防危。"]', '["北斗內，穿出慧星輝。","国內主君邊寨（京本作「塞」）將，陰謀惡黨起旌麾（京本作「強圍」），着意謹防危。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c953bb0-d5e1-456e-a7e9-2acc1d31386f', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 四', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["北斗下，氣若破車輪。","白色漸生侵口內，饑荒不稔寇成羣，餘荒不堪論。"]', '["北斗下，氣若破车輪。","白色漸生侵口內，饑荒不稔寇成羣，餘荒不堪論。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9ae0e16-046d-4e1b-9dd7-a607f2c67627', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 五', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["黑色氣，守定斗口邊。","父子相吞天下歉，水渰城郭少乾田，災害四方傳。"]', '["黑色氣，守定斗口邊。","父子相吞天下歉，水渰城郭少乾田，災害四方傳。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b75ae7-643f-4fb4-88c2-7388c0ca0a66', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 六', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，第一是妖星。","却（京本作「都」）要分明軍（辛本、川本、京本作「君」）始吉，忽然不現衆星明。","主將落奸情。","（妖星乃貪狼星也。","）。"]', '["占北斗，第一是妖星。","却（京本作「都」）要分明軍（辛本、川本、京本作「君」）始吉，忽然不現衆星明。","主將落奸情。","（妖星乃貪狼星也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('773a4dd4-3f7b-404a-9eb1-f630bfb64cfb', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 七', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，夜夜白霞遮。","不過七旬兵大起，橫屍千里臥如麻，忌戰日西斜。","（斗爲主，霞爲客，有索戰，不可出。","京本「有索戰」作「酉未來索戰」。","）。"]', '["占北斗，夜夜白霞遮。","不過七旬兵大起，橫屍千里臥如麻，忌戰日西斜。","（斗爲主，霞爲客，有索戰，不可出。","京本「有索戰」作「酉未来索戰」。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60f2fefa-7da5-41bb-bfa5-c6a83be34849', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 八', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，黃（辛本、川本、京本作「紫」）氣在其中。","吉（京本作「喜」，辛本、川本作「有」）事欲來君且記，不過旬日（京本作「逾三月」）喜重重，萬姓賀堯風。","。"]', '["占北斗，黄（辛本、川本、京本作「紫」）氣在其中。","吉（京本作「喜」，辛本、川本作「有」）事欲来君且記，不過旬日（京本作「逾三月」）喜重重，万姓賀堯风。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551df69e-5ccc-49e1-a6c5-d3f6ec38eabc', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 九', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，赤氣在其中。","萬萬雄風（辛本作「師」、川本作「帥」、京本作「兵」）徒（京本作「多」）費力，攻城盡死不成功，枉把庫厫空。"]', '["占北斗，赤氣在其中。","万万雄风（辛本作「師」、川本作「帥」、京本作「兵」）徒（京本作「多」）費力，攻城尽死不成功，枉把庫厫空。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aebb5850-3059-4c0c-b6ee-4ec5cac234da', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，兼有小星多。","天下不安人失業，荒涼米貴遞相磨，處處動干戈。"]', '["占北斗，兼有小星多。","天下不安人失業，荒涼米貴遞相磨，处处动干戈。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f76249-4a29-4910-aadb-ced73e5325e7', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十一', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["青蒼氣，漸入斗心中。","定有賊來侵郡邑（京本作「縣」），不然裨將欲謀凶，大忌是三冬。"]', '["青蒼氣，漸入斗心中。","定有賊来侵郡邑（京本作「縣」），不然裨將欲謀凶，大忌是三冬。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628860de-e68a-4039-948a-13628c91966e', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十二', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，明閃電光輝。","定主好人初出世，輔賢明德助人君，此兆即非輕。"]', '["占北斗，明閃電光輝。","定主好人初出世，輔賢明德助人君，此兆即非轻。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4decaa-896a-4c48-a57d-467626c3c858', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十三', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，太白入其中。","定主將軍逢戰死，城營難守亂人民，大小在（辛本、川本作「走」）西東。","（太白入斗，將星入度也。","）。"]', '["占北斗，太白入其中。","定主將軍逢戰死，城營难守亂人民，大小在（辛本、川本作「走」）西东。","（太白入斗，將星入度也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489030e8-b02c-4e4a-9ba8-70acbb351f82', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十四', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["黑雲氣，夜散（辛本、川本作「蔽」）星斗中。","如此三朝當有雨，急須準備候天情（辛本作「晴」），此理甚分明。"]', '["黑云氣，夜散（辛本、川本作「蔽」）星斗中。","如此三朝當有雨，急須準備候天情（辛本作「晴」），此理甚分明。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa97cbf-41cf-478d-b45c-2b4d7a7484ee', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十五', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，忽直或伸之。","衝入斗中奸事有，犯其星位各占之，術士亦須知。"]', '["占北斗，忽直或伸之。","衝入斗中奸事有，犯其星位各占之，術士亦須知。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a61c80-f2c0-40fd-b12f-93abe865ed41', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十六', '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占北斗，通夜黑雲遮。","定主來朝須有雨，急披雨笠候天涯，應兆不能差。"]', '["占北斗，通夜黑云遮。","定主来朝須有雨，急披雨笠候天涯，應兆不能差。"]', '诗', 'shi', '', NULL, '兵要望江南 占北斗第十四（京本作「占斗第四」○十六首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40bfcc3c-a9f7-45f5-8764-2f043437d4db', '兵要望江南 占地第十五（二十一首） 一', '兵要望江南 占地第十五（二十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["地之道，與月一般稱。"]', '["地之道，與月一般稱。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('857859d8-cfcf-4de2-9415-6300cf56d7ef', '兵要望江南 占地第十五（二十一首） 二', '兵要望江南 占地第十五（二十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["統軍帥，下寨要安營。","先是須知吉凶地，莫令誤地損兵軍，此理要精明。"]', '["統軍帥，下寨要安營。","先是須知吉凶地，莫令誤地損兵軍，此理要精明。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc370a1-37ff-423c-acbe-0a97eca4f39f', '兵要望江南 占地第十五（二十一首） 三', '兵要望江南 占地第十五（二十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["地名好，川破不堪安。","大路叉中休下寨，伏屍古墓見多般，將帥要知言。","（主虛驚，賊來破寨。","）。"]', '["地名好，川破不堪安。","大路叉中休下寨，伏屍古墓见多般，將帥要知言。","（主虛驚，賊来破寨。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd36b920-e7d8-457d-bb74-34520233bb8a', '兵要望江南 占地第十五（二十一首） 四', '兵要望江南 占地第十五（二十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["山窄地，泣滴莫安營。","兩路中間休立寨，龍頭（辛本、川本作「勿投」）天竈怎持兵，仔細與軍（辛本、川本作「君」）尋。","（天竈者，大谷之口；龍頭者，大山之端。","）。"]', '["山窄地，泣滴莫安營。","兩路中间休立寨，龙头（辛本、川本作「勿投」）天竈怎持兵，仔細與軍（辛本、川本作「君」）尋。","（天竈者，大谷之口；龙头者，大山之端。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbcb5d12-86ce-4fed-9eeb-fd0844e6e840', '兵要望江南 占地第十五（二十一首） 五', '兵要望江南 占地第十五（二十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["戰場地，古廟與靈壇（首本作「臺」，茲從辛本、川本）。","攻破城營移（辛本、川本作「遺」）故地，盡言凶敗與傷殘，細說與軍（辛本、川本作「兵」）官。"]', '["戰場地，古廟與靈壇（首本作「台」，茲從辛本、川本）。","攻破城營移（辛本、川本作「遺」）故地，尽言凶敗與傷殘，細说與軍（辛本、川本作「兵」）官。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a37aaea-0361-497a-904e-e45719f78d5b', '兵要望江南 占地第十五（二十一首） 六', '兵要望江南 占地第十五（二十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["山谷中，下寨忌逢之。","前高後下居之險，地無草木主憂疑，明將總須知。"]', '["山谷中，下寨忌逢之。","前高後下居之險，地無草木主憂疑，明將總須知。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e51e18-c371-4c71-a62a-102c4978c636', '兵要望江南 占地第十五（二十一首） 七', '兵要望江南 占地第十五（二十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["大驛路，前後總須疑。","或在高崗或在（辛本、川本作「近」）水，長深溪澗最無疑，下寨得便宜。"]', '["大驛路，前後總須疑。","或在高崗或在（辛本、川本作「近」）水，长深溪澗最無疑，下寨得便宜。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f6cd31-0ddd-4dac-a19d-f1d144077975', '兵要望江南 占地第十五（二十一首） 八', '兵要望江南 占地第十五（二十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營已下，須識有災非。","地上忽生諸怪類，往來天象看來情，主將要知因。"]', '["營已下，須識有災非。","地上忽生諸怪類，往来天象看来情，主將要知因。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff63b59e-3cde-4803-b95c-00ceca1cefd1', '兵要望江南 占地第十五（二十一首） 九', '兵要望江南 占地第十五（二十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占其地，毛羽忽然生。","必主人君遭厄難，大兵侵國亂朝廷，百事應憂驚。"]', '["占其地，毛羽忽然生。","必主人君遭厄难，大兵侵国亂朝廷，百事應憂驚。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ec4b1e-8b80-4ce4-a85e-72c76cba249f', '兵要望江南 占地第十五（二十一首） 十', '兵要望江南 占地第十五（二十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["田地上，忽然便生毛。","處處盡生人總見，此爲謀逆血流郊，百日主凶妖。"]', '["田地上，忽然便生毛。","处处尽生人總见，此爲謀逆血流郊，百日主凶妖。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59d14654-4f79-4dff-af88-63d9c86db36c', '兵要望江南 占地第十五（二十一首） 十一', '兵要望江南 占地第十五（二十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，火焰忽然（京本作「生」）光。","將士敗亡看在速，急須移寨（京本作「轉」）免災殃，不去禍難當。"]', '["城營內，火焰忽然（京本作「生」）光。","將士敗亡看在速，急須移寨（京本作「轉」）免災殃，不去禍难當。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec0e0f9-0582-4910-8ea9-d0228e7f0844', '兵要望江南 占地第十五（二十一首） 十二', '兵要望江南 占地第十五（二十一首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城忽裂，必主起干戈。","山中地或如雷吼，敵軍來時看（辛本、川本作「速探」）如何，急避莫蹉跎。"]', '["城忽裂，必主起干戈。","山中地或如雷吼，敵軍来时看（辛本、川本作「速探」）如何，急避莫蹉跎。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ccc7fb-0fac-430f-bd9a-6548eed34454', '兵要望江南 占地第十五（二十一首） 十三', '兵要望江南 占地第十五（二十一首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨（京本作「砦」）地，泉水及生塵。","有戰不離於月內，早排兵甲敵邊隣，移寨避災迍。","（先移後戰。","）。"]', '["營寨（京本作「砦」）地，泉水及生塵。","有戰不離於月內，早排兵甲敵邊隣，移寨避災迍。","（先移後戰。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8dd994-b1cc-4b0f-8101-48c524b47cb5', '兵要望江南 占地第十五（二十一首） 十四', '兵要望江南 占地第十五（二十一首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營（京本作「營內」）地，無故動還搖。","大戰必應於歲月（京本作「內」，幷注：「城年營月也。","」）直須移（京本作「離」）寨禍應消，不去（京本作「出」）將身招。"]', '["城營（京本作「營內」）地，無故动還搖。","大戰必應於歲月（京本作「內」，幷注：「城年營月也。","」）直須移（京本作「離」）寨禍應消，不去（京本作「出」）將身招。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('747573f6-e086-4ff3-b041-35faf184705b', '兵要望江南 占地第十五（二十一首） 十五', '兵要望江南 占地第十五（二十一首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，地動起兵戈。","且早移營於吉地（辛本、川本作「福上」），不然刑禍將身多，陣敗（辛本、川本、京本作「破」）自消磨。"]', '["城營內，地动起兵戈。","且早移營於吉地（辛本、川本作「福上」），不然刑禍將身多，陣敗（辛本、川本、京本作「破」）自消磨。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1891bae-7d1b-4ff2-ac8d-33fd83b0dc0f', '兵要望江南 占地第十五（二十一首） 十六', '兵要望江南 占地第十五（二十一首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營内，忽見地生毛。","所統精兵當便起，須臾不去禍應遭，禳醮保功勞。"]', '["城營内，忽见地生毛。","所統精兵當便起，須臾不去禍應遭，禳醮保功勞。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('415c08f3-b064-427c-9b9e-0669e2c5f375', '兵要望江南 占地第十五（二十一首） 十七', '兵要望江南 占地第十五（二十一首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，地上起錢（京本作「殘」）花。","有似馬蹄同此兆，移營擁（京本作「各營勇」）士定歸家，應驗決無差。","。"]', '["城營內，地上起錢（京本作「殘」）花。","有似马蹄同此兆，移營擁（京本作「各營勇」）士定归家，應驗決無差。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6de04cb-4355-4e42-ac17-0306c9025571', '兵要望江南 占地第十五（二十一首） 十八', '兵要望江南 占地第十五（二十一首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，地忽現（辛本、川本、京本作「陷」）崩摧。","禍結兵連緣此兆，移營脩義滅（京本作「速修仁義免」）凶災，不信將身推（京本作「危」）。"]', '["城營內，地忽現（辛本、川本、京本作「陷」）崩摧。","禍結兵連緣此兆，移營脩義滅（京本作「速修仁義免」）凶災，不信將身推（京本作「危」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ca6632-d537-425a-a6ad-02457f5d336c', '兵要望江南 占地第十五（二十一首） 十九', '兵要望江南 占地第十五（二十一首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，忽見地生丹（京本作「忽有土崩塌」）。","敵騎欲來衝突我，差人截路莫輕閑（京本作「待莫輕看」），移寨庶幾安（辛本、川本作「倚亭關」）。"]', '["城營內，忽见地生丹（京本作「忽有土崩塌」）。","敵騎欲来衝突我，差人截路莫轻闲（京本作「待莫轻看」），移寨庶幾安（辛本、川本作「倚亭关」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55656ad5-bb83-41f7-a741-d101bf9c3193', '兵要望江南 占地第十五（二十一首） 二十', '兵要望江南 占地第十五（二十一首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，花草忽然生。","急出莫令軍疾病，經旬不動將身傾，智士（京本作「勇」）切須明。"]', '["城營內，花草忽然生。","急出莫令軍疾病，經旬不动將身傾，智士（京本作「勇」）切須明。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36909703-c4eb-4cc3-ac8e-7d9a7757ffaf', '兵要望江南 占地第十五（二十一首） 二十一', '兵要望江南 占地第十五（二十一首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，地上忽然（京本作「生」）黃。","五穀或生幷地長（京本作「忽然生遍地」），將軍祿位福無疆，士馬樂（京本作「亦」）安康。","。"]', '["城營內，地上忽然（京本作「生」）黄。","五穀或生幷地长（京本作「忽然生遍地」），將軍祿位福無疆，士马乐（京本作「亦」）安康。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占地第十五（二十一首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68d0251-0e4c-447d-982f-9a437442e906', '兵要望江南 占樹第十六（五首） 一', '兵要望江南 占樹第十六（五首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城（京本作「營」）中樹，忽然總萎黃。","威氣（京本作「風」）助吾軍必勝，陰神祐我必成強，主將喜非常。"]', '["城（京本作「營」）中樹，忽然總萎黄。","威氣（京本作「风」）助吾軍必勝，陰神祐我必成強，主將喜非常。"]', '诗', 'shi', '', NULL, '兵要望江南 占樹第十六（五首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0a7a7b-c5c4-4669-a934-6c2c511fe120', '兵要望江南 占樹第十六（五首） 二', '兵要望江南 占樹第十六（五首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營側畔，樹木自崩摧。","若近軍前師敗辱，不然近彼賊（京本作「彼戰必」）衝來，移去免凶災。"]', '["營側畔，樹木自崩摧。","若近軍前師敗辱，不然近彼賊（京本作「彼戰必」）衝来，移去免凶災。"]', '诗', 'shi', '', NULL, '兵要望江南 占樹第十六（五首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac41051-7178-4662-96cb-b9ad203b3715', '兵要望江南 占樹第十六（五首） 三', '兵要望江南 占樹第十六（五首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["諸樹木，花發不當時。","營內見之須速備（京本作「避」），定知賊衆欲來圍，移寨免災危。"]', '["諸樹木，花發不當时。","營內见之須速備（京本作「避」），定知賊衆欲来圍，移寨免災危。"]', '诗', 'shi', '', NULL, '兵要望江南 占樹第十六（五首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3062bc2e-0c7d-47d5-8c33-00286c43a77c', '兵要望江南 占樹第十六（五首） 四', '兵要望江南 占樹第十六（五首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨內，樹本被雷驚。","或是震傷人與物，此爲傷敗被天嗔，移寨免憂心。"]', '["營寨內，樹本被雷驚。","或是震傷人與物，此爲傷敗被天嗔，移寨免憂心。"]', '诗', 'shi', '', NULL, '兵要望江南 占樹第十六（五首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4afdefe3-9f04-4e3e-8192-81635fe89f80', '兵要望江南 占樹第十六（五首） 五', '兵要望江南 占樹第十六（五首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["諸樹木，忽地出奇枝。","異花奇葉人罕見，必生異事報軍（辛本、川本作「君」）知，將帥看修爲。"]', '["諸樹木，忽地出奇枝。","異花奇葉人罕见，必生異事報軍（辛本、川本作「君」）知，將帥看修爲。"]', '诗', 'shi', '', NULL, '兵要望江南 占樹第十六（五首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b759ed9-d97b-4f00-a568-40ee96449f6f', '兵要望江南 占蜂第十七（京本列第十一○五首） 一', '兵要望江南 占蜂第十七（京本列第十一○五首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，蜂衆泊於營。","兵（京本作「軍」）欲動移應不久，修磨器甲莫教停，總令便須行。"]', '["軍營內，蜂衆泊於營。","兵（京本作「軍」）欲动移應不久，修磨器甲莫教停，總令便須行。"]', '诗', 'shi', '', NULL, '兵要望江南 占蜂第十七（京本列第十一○五首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950d9e31-fc57-4a92-849a-dc0e7e443d1a', '兵要望江南 占蜂第十七（京本列第十一○五首） 二', '兵要望江南 占蜂第十七（京本列第十一○五首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍行次，蜂蝶接連來。","定有伏兵居草莽（辛本、川本、京本作「澤」），好防林木與山崖，先探保無災。"]', '["軍行次，蜂蝶接連来。","定有伏兵居草莽（辛本、川本、京本作「澤」），好防林木與山崖，先探保無災。"]', '诗', 'shi', '', NULL, '兵要望江南 占蜂第十七（京本列第十一○五首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f657b3ec-8f2d-4c34-a331-0406de5a7e26', '兵要望江南 占蜂第十七（京本列第十一○五首） 三', '兵要望江南 占蜂第十七（京本列第十一○五首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍下寨，蜂蝶遍天飛，防有賊來攻我寨，急（首本作「忽」，茲從辛本、川本）須固守莫遲回，主將要先知。"]', '["軍下寨，蜂蝶遍天飞，防有賊来攻我寨，急（首本作「忽」，茲從辛本、川本）須固守莫遲回，主將要先知。"]', '诗', 'shi', '', NULL, '兵要望江南 占蜂第十七（京本列第十一○五首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7440d815-4ee9-45ad-aa1e-d9b7dc779fa6', '兵要望江南 占蜂第十七（京本列第十一○五首） 四', '兵要望江南 占蜂第十七（京本列第十一○五首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，蜂惡亂叮（辛本、川本作「呵」）人。","或是反軍與謀將，必然軍將有灾危，謹守賊欺追（辛本、川本作「追欺」）。","。"]', '["軍營內，蜂惡亂叮（辛本、川本作「呵」）人。","或是反軍與謀將，必然軍將有灾危，謹守賊欺追（辛本、川本作「追欺」）。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占蜂第十七（京本列第十一○五首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce04659-2487-469c-b895-ac1af84fa2bc', '兵要望江南 占蜂第十七（京本列第十一○五首） 五', '兵要望江南 占蜂第十七（京本列第十一○五首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，蜂子遍飛遊。","必主將軍多口舌，若還移寨沒災危，記此在心機。"]', '["軍營內，蜂子遍飞游。","必主將軍多口舌，若還移寨沒災危，記此在心機。"]', '诗', 'shi', '', NULL, '兵要望江南 占蜂第十七（京本列第十一○五首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c4b600-1d9e-4dcd-a7b3-d24d6388554d', '兵要望江南 占鼠第十八（京本列第十○十首） 一', '兵要望江南 占鼠第十八（京本列第十○十首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占見鼠，其物夙名虛。","主盜主奸皆主賊，若來爲怪將兵虞，不信禍難除。"]', '["占见鼠，其物夙名虛。","主盜主奸皆主賊，若来爲怪將兵虞，不信禍难除。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78725b2c-b0f0-453a-9f4f-1448b378a6c1', '兵要望江南 占鼠第十八（京本列第十○十首） 二', '兵要望江南 占鼠第十八（京本列第十○十首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["逢見鼠，白色是金精。","若順軍行軍大勝，逆軍來者禍相（京本作「灾」）生，凶吉甚分明。"]', '["逢见鼠，白色是金精。","若順軍行軍大勝，逆軍来者禍相（京本作「灾」）生，凶吉甚分明。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8ff0b5-14d4-4aee-80b8-201b76acb892', '兵要望江南 占鼠第十八（京本列第十○十首） 三', '兵要望江南 占鼠第十八（京本列第十○十首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["逢赤鼠，來往在軍前。","此是伏軍（京本作「兵」）藏詭計，搜尋斜谷道旁邊，急備莫遲延。"]', '["逢赤鼠，来往在軍前。","此是伏軍（京本作「兵」）藏詭計，搜尋斜谷道旁邊，急備莫遲延。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd1238c-00a5-4cd6-909b-f96a426d90bd', '兵要望江南 占鼠第十八（京本列第十○十首） 四', '兵要望江南 占鼠第十八（京本列第十○十首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，鼠咬屋椽楹。","或見（辛本、京本作「向」）壁間搬出土，移營在近改遷寧，排備向前程。"]', '["軍營內，鼠咬屋椽楹。","或见（辛本、京本作「向」）壁间搬出土，移營在近改遷寧，排備向前程。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9c37ac-cb22-42df-af35-e72457a6e3a9', '兵要望江南 占鼠第十八（京本列第十○十首） 五', '兵要望江南 占鼠第十八（京本列第十○十首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，行鼠尾舒前。","將（京本作「軍」）主有災須醮謝，夜深谷口（京本作「各各」、辛本、川本作「谷谷」）罷戈（京本作「兵」）鋋，太白（京本作「天似」）報人言。"]', '["軍營內，行鼠尾舒前。","將（京本作「軍」）主有災須醮謝，夜深谷口（京本作「各各」、辛本、川本作「谷谷」）罷戈（京本作「兵」）鋋，太白（京本作「天似」）報人言。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d780d16-afc4-46a3-a211-89df38fbc0f4', '兵要望江南 占鼠第十八（京本列第十○十首） 六', '兵要望江南 占鼠第十八（京本列第十○十首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨（京本作「軍營」）內，驀地鼠成行。","欲似弔人聲不罷（京本作「出」），此須爲禍將身當，禳謝得平（京本作「保安」）康。"]', '["營寨（京本作「軍營」）內，驀地鼠成行。","欲似弔人声不罷（京本作「出」），此須爲禍將身當，禳謝得平（京本作「保安」）康。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea887fa4-5573-4d5c-b82d-2460da77345f', '兵要望江南 占鼠第十八（京本列第十○十首） 七', '兵要望江南 占鼠第十八（京本列第十○十首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨內，白日鼠搬兒。","不是火災應大水，三日（辛本、川本、京本作「朝」）五（京本作「兩」）日速遷移，不出禍相隨。"]', '["營寨內，白日鼠搬兒。","不是火災應大水，三日（辛本、川本、京本作「朝」）五（京本作「兩」）日速遷移，不出禍相隨。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b386465-f116-4e16-bd3a-24f021fd306e', '兵要望江南 占鼠第十八（京本列第十○十首） 八', '兵要望江南 占鼠第十八（京本列第十○十首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["寨中鼠，能舞向人前。","必有內奸通外敵，且須搜捉莫遷延，速備實爲先。"]', '["寨中鼠，能舞向人前。","必有內奸通外敵，且須搜捉莫遷延，速備實爲先。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e012d923-0187-4038-be47-3e4dcf3fe7ea', '兵要望江南 占鼠第十八（京本列第十○十首） 九', '兵要望江南 占鼠第十八（京本列第十○十首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營鼠，血染將衣冠。","或咬鼓旗皆不利，信須修謝拜星官，移寨且求安。"]', '["軍營鼠，血染將衣冠。","或咬鼓旗皆不利，信須修謝拜星官，移寨且求安。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de2196e-6098-42a9-8138-a642bf33254c', '兵要望江南 占鼠第十八（京本列第十○十首） 十', '兵要望江南 占鼠第十八（京本列第十○十首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍臥，眼上被鼠傷（京本作「將軍服，上祍鼠來傷」）。","必有奸賊（京本作「喜神」）來（辛本、川本、京本作「看」）在即，或傷腰下不相當，財散（京本作「破」）客軍強。","（經曰：「鼠者，賊也。","如有變易，必主奸寇入也。","」）。"]', '["將軍臥，眼上被鼠傷（京本作「將軍服，上祍鼠来傷」）。","必有奸賊（京本作「喜神」）来（辛本、川本、京本作「看」）在即，或傷腰下不相當，財散（京本作「破」）客軍強。","（經曰：「鼠者，賊也。","如有变易，必主奸寇入也。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鼠第十八（京本列第十○十首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6cc9a8f-5078-4ea6-b008-c91ed7bdcefc', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 一', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，路上遇橫蛇。","或入水中應大勝，蛇還赤地（京本作「色」）戰無涯，勝負較些些（辛本、川本作「勝地住些些」。","泊住過一日，外動則吉。","）。"]', '["兵發日，路上遇橫蛇。","或入水中應大勝，蛇還赤地（京本作「色」）戰無涯，勝負較些些（辛本、川本作「勝地住些些」。","泊住過一日，外动則吉。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4621c164-30b1-4a6c-8ad8-7b3f4b5d62e7', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 二', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵（京本作「軍」）行次，蛇赤忌逢之。","慎備（京本作「陣當」）前程來勒（京本作「應勤」）戰，訓兵激賞布恩威，厚薄勿偏虧。"]', '["兵（京本作「軍」）行次，蛇赤忌逢之。","慎備（京本作「陣當」）前程来勒（京本作「應勤」）戰，訓兵激賞布恩威，厚薄勿偏虧。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90fb1220-4358-417d-a851-1375b316905a', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 三', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍發次，驀地見交蛇（京本作「蛟交」）。","講武揚兵須宴犒，不然上將中風邪，身喪掩黃沙。"]', '["軍發次，驀地见交蛇（京本作「蛟交」）。","講武揚兵須宴犒，不然上將中风邪，身喪掩黄沙。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18bd2f16-d011-47e4-a2a3-293b1ca74dbf', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 四', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["蛇赤（辛本、川本、京本作「諸」）色，大小外邊來。","來入我軍兵欲敵（京本作「散」），更防引得外奸乖，德向（京本作「得上」）好通開（首本作「關」，茲從辛本、川本、京本）。"]', '["蛇赤（辛本、川本、京本作「諸」）色，大小外邊来。","来入我軍兵欲敵（京本作「散」），更防引得外奸乖，德向（京本作「得上」）好通开（首本作「关」，茲從辛本、川本、京本）。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c465aad0-9547-4877-9bd3-db6d910755d7', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 五', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["長蛇見，飲水近營（京本作「軍」）傍。","抽退還鄉方始吉，不然移寨九天方，禳厭免災殃（辛本、川本末八字作「向高強，營壘布旌幢」。","京本注：「太歲九天上同。","」）。"]', '["长蛇见，饮水近營（京本作「軍」）傍。","抽退還乡方始吉，不然移寨九天方，禳厭免災殃（辛本、川本末八字作「向高強，營壘布旌幢」。","京本注：「太歲九天上同。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff907cd-d766-4fdd-b66c-912e14c03b2c', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 六', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵（京本作「軍」）行次，蛇貫路邊傍。","備禦伏（京本作「賊」）兵前道阻，且須仔細更思量，終不使開（京本作「利封」）疆。"]', '["兵（京本作「軍」）行次，蛇貫路邊傍。","備禦伏（京本作「賊」）兵前道阻，且須仔細更思量，終不使开（京本作「利封」）疆。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb486724-d2e9-461b-91b1-e084777042ca', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 七', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["蛇入井，俱是敗軍形。","或似杄形營內現，若還交戰血成坑，堅守我軍營。"]', '["蛇入井，俱是敗軍形。","或似杄形營內現，若還交戰血成坑，堅守我軍營。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397c2a69-29dc-4537-b3d7-dcd166f8dfca', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 八', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["蛇貫道，白赤動（京本作「助」）軍情。","必有賊兵攔道路（京本作「捫路道」），只宜盤泊賞軍兵，不久却回程。","（但有異色之蛇攔路，回師罷戰，大吉。","）。"]', '["蛇貫道，白赤动（京本作「助」）軍情。","必有賊兵攔道路（京本作「捫路道」），只宜盤泊賞軍兵，不久却回程。","（但有異色之蛇攔路，回師罷戰，大吉。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c69f18-8588-412c-886b-866bf494f544', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 九', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["蛇如鳥，更有似弓（辛本、川本作「車」）形。","或是白蛇形（辛本、川本作「行」、京本作「形如」）斷續，兼之五六見城營，泣淚血交幷。"]', '["蛇如鸟，更有似弓（辛本、川本作「车」）形。","或是白蛇形（辛本、川本作「行」、京本作「形如」）斷續，兼之五六见城營，泣泪血交幷。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9348bcd6-b64a-4c80-9b34-727e35852b5e', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["蛟蛇見，營寨必（京本作「不」）宜攻。","更有青蛇人病疾，黃蛇疫瘴總成凶，移寨（京本作「徙」）免灾凶（京本作「逢」）。"]', '["蛟蛇见，營寨必（京本作「不」）宜攻。","更有青蛇人病疾，黄蛇疫瘴總成凶，移寨（京本作「徙」）免灾凶（京本作「逢」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e9b40e-dace-48b5-9d5a-2424bb352d4c', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十一', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，水裏怕逢蛇。","更有魚龍蜃類見，悉皆進退事無涯（京本作「捱」），速退莫咨嗟。","（如見龍蛇蜃，幷同。","）。"]', '["兵行次，水裏怕逢蛇。","更有鱼龙蜃類见，悉皆進退事無涯（京本作「捱」），速退莫咨嗟。","（如见龙蛇蜃，幷同。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6960e7-d6f3-40fe-8bb9-b04e1da10c59', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十二', '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["下營畢（京本作「軍」），遶寨（京本作「蛇遶」）大蛇棲。","必有賊（京本作「戰」）兵來打寨，高強營壘矗（京本作「布」）旌旗，謹慎欲（京本作「好」）防之。"]', '["下營畢（京本作「軍」），遶寨（京本作「蛇遶」）大蛇棲。","必有賊（京本作「戰」）兵来打寨，高強營壘矗（京本作「布」）旌旗，謹慎欲（京本作「好」）防之。"]', '诗', 'shi', '', NULL, '兵要望江南 占蛇第十九（京本列第二十一○十二首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49568868-4aa2-4f53-b2cf-58fa2146ceb5', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 一', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，馬夜轉槽鳴。","軍欲離營將大戰，早排驍勇各嚴（辛本、川本作「令行」）明，（京本作「各令齊」），法令（辛本、川本作「號」）整齊行（京本作「號令辨高低」）。"]', '["城營內，马夜轉槽鳴。","軍欲離營將大戰，早排驍勇各嚴（辛本、川本作「令行」）明，（京本作「各令齊」），法令（辛本、川本作「號」）整齊行（京本作「號令辨高低」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4fc4e8f-27b9-448c-9632-5a1c632fdef3', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，馬咬石兼沙。","必有賊兵吾（京本作「君」）大獲，將軍克勝遠方誇，大小總榮華。"]', '["軍營內，马咬石兼沙。","必有賊兵吾（京本作「君」）大獲，將軍克勝远方誇，大小總榮华。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b8a7d9-f58b-4e13-aa24-b55517cd0fcf', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，牛舞向人前。","欲罷戰爭休士卒，干戈不舉却回旋，各（辛本、川本、京本作「齊」）賀太平年。"]', '["軍營內，牛舞向人前。","欲罷戰爭休士卒，干戈不舉却回旋，各（辛本、川本、京本作「齊」）賀太平年。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e52107-79e7-4bdc-a3c0-0bb97f646213', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 四', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["馬廐內，天火忽然燒。","看即大兵將欲起，直須修德（辛本、川本作「福」）禍方消，勿使自身招。"]', '["马廐內，天火忽然燒。","看即大兵將欲起，直須修德（辛本、川本作「福」）禍方消，勿使自身招。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9423768-8233-431a-a2ee-a74b0fced7ee', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 五', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，驢馬作人言。","聽取語言爲定（京本作「作」）准，更看馬後（辛本、川本作「駿」）殺軍年，方始報仇冤。"]', '["城營內，驢马作人言。","听取語言爲定（京本作「作」）准，更看马後（辛本、川本作「駿」）殺軍年，方始報仇冤。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d5613c-7fcc-43c2-a74f-d4b364f77e0e', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 六', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍（川本作「城」）營內，牛馬夜間鳴。","必有暴兵來覓鬬，直須防備夜偷營，速暗布精兵。"]', '["軍（川本作「城」）營內，牛马夜间鳴。","必有暴兵来覓鬬，直須防備夜偷營，速暗布精兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('009f62cf-56f7-46f8-80d3-0d91102ddea6', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 七', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，生產兩頭奇。","或有足多生八隻，四足兩頭禍不移，裂土應逾期。"]', '["城營內，生產兩头奇。","或有足多生八隻，四足兩头禍不移，裂土應逾期。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b1ff82b-e6a0-4a0c-b22f-bc1f3b7d8e5a', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 八', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占走獸，獸字體相將。","或（辛本、川本作「凡」）有怪形須要當，由分凶吉與君張，要辨（辛本、川本作「獸」）虎豺狼。"]', '["占走獸，獸字體相將。","或（辛本、川本作「凡」）有怪形須要當，由分凶吉與君張，要辨（辛本、川本作「獸」）虎豺狼。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('056df25f-d9a0-42d4-8791-1287fb770892', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 九', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日（京本作「發兵次」），野獸截軍（京本作「兵」）行。","直向隊中衝透過，必然（京本作「分」）隊伍兩縱橫，良將要（京本作「亦」）須明。"]', '["兵發日（京本作「發兵次」），野獸截軍（京本作「兵」）行。","直向隊中衝透過，必然（京本作「分」）隊伍兩縱橫，良將要（京本作「亦」）須明。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4b7af3-6da3-4215-b840-3896d7e207ed', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，狼虎及熊羆。","若在軍前狂亂（京本作「浪」）走，此行旬日戰無移（京本作「旬戰定無宜」），先舉得（京本作「合」）天機。"]', '["兵行次，狼虎及熊羆。","若在軍前狂亂（京本作「浪」）走，此行旬日戰無移（京本作「旬戰定無宜」），先舉得（京本作「合」）天機。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8a51876-f68e-4731-b48d-39086dccc1a8', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十一', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["諸禽獸，異色及無名。","有爪有牙（京本作「齒」）爲我怕，無牙無爪亦應輕，此兆甚分明。","。"]', '["諸禽獸，異色及無名。","有爪有牙（京本作「齒」）爲我怕，無牙無爪亦應轻，此兆甚分明。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a351e243-7706-4dbd-a86f-0535d1a45e04', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十二', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營前後，野獸亂縱橫。","殺取太牢天地祭，三（京本作「六」）軍方得保安寧，有戰必須（京本作「然」）贏。"]', '["營前後，野獸亂縱橫。","殺取太牢天地祭，三（京本作「六」）軍方得保安寧，有戰必須（京本作「然」）贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b8f198c-4bbc-4b04-b1dc-cd7b0d9c9bf2', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十三', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，白鹿入營來。","將士病災方欲起，若還無角（京本作「病」）主兵回，移寨免災危。"]', '["城營內，白鹿入營来。","將士病災方欲起，若還無角（京本作「病」）主兵回，移寨免災危。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2dda3e0-9036-4d58-995e-e29fa4891806', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十四', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵屯次，鹿走入軍營。","必有降人來見我，期於三日事分明，或（京本作「咸」）喜長威名。","（辛本、川本注：有戰作，主大勝。","）。"]', '["兵屯次，鹿走入軍營。","必有降人来见我，期於三日事分明，或（京本作「咸」）喜长威名。","（辛本、川本注：有戰作，主大勝。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f344e0d5-a9c0-4c7e-85f0-db28a56d3898', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十五', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["狼與虎，切忌入軍（京本作「營」）中。","隊伍突衝幷截路，不過數日有危凶，警備勿交攻。"]', '["狼與虎，切忌入軍（京本作「營」）中。","隊伍突衝幷截路，不過數日有危凶，警備勿交攻。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff54753-e6f6-4ccf-b543-11f84f250a91', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十六', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["虎相食，兆不出三年。","必有大兵當至此，來其分野禍相煎，其兆理關天。"]', '["虎相食，兆不出三年。","必有大兵當至此，来其分野禍相煎，其兆理关天。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('802235c8-357e-4816-9709-3c221592856e', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十七', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵屯次，野象（京本作「豕」）入于營。","急急殺來將祭獻（京本作「鼓」），三軍從此得安寧，齋沐要嚴精。"]', '["兵屯次，野象（京本作「豕」）入于營。","急急殺来將祭獻（京本作「鼓」），三軍從此得安寧，斋沐要嚴精。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1cc32c-d855-4f75-b322-f166384c528b', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十八', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鹿（京本作「麂」）子入其中。","殺取三牲將祭獻（辛本、川本、京本作「禱」），急當移寨免災凶，否則禍重重。"]', '["城營內，鹿（京本作「麂」）子入其中。","殺取三牲將祭獻（辛本、川本、京本作「禱」），急當移寨免災凶，否則禍重重。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607c47df-9f78-4aae-89bc-c745f6bfdb47', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十九', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營側，驀地有豪猪。","須備伏兵來犯（京本作「賊兵來劫」）我，便宜先舉莫躊躇，移寨始無虞。"]', '["軍營側，驀地有豪猪。","須備伏兵来犯（京本作「賊兵来劫」）我，便宜先舉莫躊躇，移寨始無虞。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3221003d-1d3c-4d99-b88b-9f37ffa1110b', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，或（京本作「忽」）有野猪來。","若戰先贏多後敗，速當移寨避其災，修謝莫遲回。"]', '["軍營內，或（京本作「忽」）有野猪来。","若戰先贏多後敗，速當移寨避其災，修謝莫遲回。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d73cf5-b1af-4985-b8d5-a79cf6f82821', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十一', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，兔走在（京本作「入」）其中。","雖有雄兵終不戰，都緣彼敵欲和同，不在苦（京本作「若」）邀功。"]', '["軍營內，兔走在（京本作「入」）其中。","雖有雄兵終不戰，都緣彼敵欲和同，不在苦（京本作「若」）邀功。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c9759e-5a3e-4d57-adbc-306b5ad9b754', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十二', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，狸獸（京本作「走」）夜頻鳴。","恰似豺狼同此兆，必知將士欲離營，不久禍災生。"]', '["軍營內，狸獸（京本作「走」）夜頻鳴。","恰似豺狼同此兆，必知將士欲離營，不久禍災生。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48ae1f2a-09ad-43d9-8380-f164bf083a2d', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十三', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵屯（京本作「行」）次，豺狗入於營。","內有奸人（京本作「兵」）相結外，急須搜捉察原情，莫遣叛縱橫（京本作「蹤興」）。"]', '["兵屯（京本作「行」）次，豺狗入於營。","內有奸人（京本作「兵」）相結外，急須搜捉察原情，莫遣叛縱橫（京本作「蹤兴」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c155b47a-ac06-4592-bb84-c95259852aba', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十四', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，狗怪遣人猜（京本作「灾」）。","急殺血流于戍（京本作「成」）地，埋深三尺以禳災，敵將必擒來。"]', '["軍營內，狗怪遣人猜（京本作「灾」）。","急殺血流于戍（京本作「成」）地，埋深三尺以禳災，敵將必擒来。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6956e41d-1e23-4ff2-9e02-656859a1d54d', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十五', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，獐入及登城。","若遇此妖多是火，不然孝服與兵爭，祈謝保（京本作「得」）安寧。"]', '["軍營內，獐入及登城。","若遇此妖多是火，不然孝服與兵爭，祈謝保（京本作「得」）安寧。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a2feeb-f5b4-4d2d-b622-23d4b7287094', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十六', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，路上遇猿猴。","嚴令小心防恐怖，理當排槊（京本作「齪」）整戈矛，預計盡良籌。","。"]', '["兵行次，路上遇猿猴。","嚴令小心防恐怖，理當排槊（京本作「齪」）整戈矛，預計尽良籌。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83cf4e1-12df-4f88-bab5-9adf94a1c86a', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十七', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["狼與虎，遶寨作悲鳴（京本作「聲」）。","似哭似號（京本作「嘷」）軍大敗，將軍兵敗（京本作「潰」）事多驚（京本作「更」），屍壘澗溝平。"]', '["狼與虎，遶寨作悲鳴（京本作「声」）。","似哭似號（京本作「嘷」）軍大敗，將軍兵敗（京本作「潰」）事多驚（京本作「更」），屍壘澗溝平。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852eb726-8ee0-49b6-810d-0627e10b6cb6', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十八', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["狼奔走，直撞入吾軍。","不出三日（京本作「去三朝」）幷五日，敵來降我引朝君，彼我受皇恩。"]', '["狼奔走，直撞入吾軍。","不出三日（京本作「去三朝」）幷五日，敵来降我引朝君，彼我受皇恩。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92236bbb-653e-44cf-981c-8f7667a446e6', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十九', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["野猪鹿，從外入中營。","定有降人來投（京本作「伏」）我，只於三日見分明，引使（京本作「伴」）履王庭。"]', '["野猪鹿，從外入中營。","定有降人来投（京本作「伏」）我，只於三日见分明，引使（京本作「伴」）履王庭。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a98895-88e0-4ea9-8dfa-21c63753de1e', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["狼與虎，卒見使人驚。","我在徒師前去後（京本作「在我帥營前後走」），須防大戰血成坑，不遇聖賢明。"]', '["狼與虎，卒见使人驚。","我在徒師前去後（京本作「在我帥營前後走」），須防大戰血成坑，不遇聖賢明。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed6bc04-99fc-43cf-a817-4a6679ecd9f8', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十一', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行（辛本、川本、京本作「屯」）次，狸走入其中。","不住夜鳴圍繞寨，先因風火事（京本作「憂風火夜」）重重，埋伏且藏兵（京本作「蹤」、辛本、川本作「擬藏中」）。"]', '["兵行（辛本、川本、京本作「屯」）次，狸走入其中。","不住夜鳴圍繞寨，先因风火事（京本作「憂风火夜」）重重，埋伏且藏兵（京本作「蹤」、辛本、川本作「擬藏中」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc0bb51d-4780-450c-b262-3b7d8eb49feb', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十二', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，驀地有來獐。","三朝七日須大戰，不然講武較旗鎗。","速斬免災殃。"]', '["軍營內，驀地有来獐。","三朝七日須大戰，不然講武較旗鎗。","速斬免災殃。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7709d923-bff5-45de-bf32-6d20d40810f2', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十三', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["牛與馬，產出是人形。","定主胡人侵大國，不分南北亂人民，且候聖明生。"]', '["牛與马，產出是人形。","定主胡人侵大国，不分南北亂人民，且候聖明生。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0867a374-3563-42a9-a659-2ba38b993fec', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十四', '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛马第十八」○三十四首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["狼與虎，號泣（辛本、川本作「號叫」、京本作「嘯叫」）又傷人。","五日七朝兵起至，臨時勝負預鋪陳，方許（辛本、川本作「治」、京本作「恥」）敗來軍。"]', '["狼與虎，號泣（辛本、川本作「號叫」、京本作「嘯叫」）又傷人。","五日七朝兵起至，臨时勝負預鋪陳，方許（辛本、川本作「治」、京本作「恥」）敗来軍。"]', '诗', 'shi', '', NULL, '兵要望江南 占獸第二十（京本列第二十二，前六首另作「占牛馬第十八」○三十四首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76101ae4-47fa-4b58-a067-38185fa24ed9', '兵要望江南 占水族第二十一（京本列第十二○七首） 一', '兵要望江南 占水族第二十一（京本列第十二○七首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，水族忌逢（京本作「行」）之。","但是魚龍蛟蜃類，悉皆不吉兆災危，抽退却相宜。"]', '["兵行次，水族忌逢（京本作「行」）之。","但是鱼龙蛟蜃類，悉皆不吉兆災危，抽退却相宜。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95203a55-2b63-427c-8ffb-b2255fe43e35', '兵要望江南 占水族第二十一（京本列第十二○七首） 二', '兵要望江南 占水族第二十一（京本列第十二○七首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["龍現壘，室宅及池（京本作「其」）中。","必有大臣謀叛逆，且須作急探奸凶，莫待有奔衝。","（王莽、朱溫時，龍現池沼。","）。"]', '["龙現壘，室宅及池（京本作「其」）中。","必有大臣謀叛逆，且須作急探奸凶，莫待有奔衝。","（王莽、朱溫时，龙現池沼。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc219c92-4e96-4927-9107-ef6c99dba9c3', '兵要望江南 占水族第二十一（京本列第十二○七首） 三', '兵要望江南 占水族第二十一（京本列第十二○七首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍（京本作「兵」）行次，龍鬬在軍前。","必是（京本作「有」）交鋒亡命戰，黃龍得勝黑龍偏，平地血成川。"]', '["軍（京本作「兵」）行次，龙鬬在軍前。","必是（京本作「有」）交鋒亡命戰，黄龙得勝黑龙偏，平地血成川。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c70251e-0b3b-4076-93ba-b36820f8dcc1', '兵要望江南 占水族第二十一（京本列第十二○七首） 四', '兵要望江南 占水族第二十一（京本列第十二○七首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，魚鼈現（辛本、川本、京本作「鼈忽露」）其形。","防有內奸謀叛逆，不然水漲浸軍兵，速去得安寧。","。"]', '["城營內，鱼鼈現（辛本、川本、京本作「鼈忽露」）其形。","防有內奸謀叛逆，不然水漲浸軍兵，速去得安寧。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b19cd304-7403-4aad-8b86-e54db50ca207', '兵要望江南 占水族第二十一（京本列第十二○七首） 五', '兵要望江南 占水族第二十一（京本列第十二○七首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，龜蟹入其（京本作「營」）中。","更有聚蠅億萬數，軍兵潰散（京本作「敗」）敗不從容，看即棄（辛本、川本作「旋」）營空。"]', '["城營內，龟蟹入其（京本作「營」）中。","更有聚蠅億万數，軍兵潰散（京本作「敗」）敗不從容，看即棄（辛本、川本作「旋」）營空。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a6d31f-3383-4887-866e-08aa0d491959', '兵要望江南 占水族第二十一（京本列第十二○七首） 六', '兵要望江南 占水族第二十一（京本列第十二○七首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍（京本作「兵」）行次，路上見黿鼉。","或有戰爭營寨（京本作「在戰營征砦」）內，不宜前進有（京本作「損」）兵戈，細審莫奔波。"]', '["軍（京本作「兵」）行次，路上见黿鼉。","或有戰爭營寨（京本作「在戰營征砦」）內，不宜前進有（京本作「損」）兵戈，細審莫奔波。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe0eb3d-8ddb-4230-a6b7-369925180e3e', '兵要望江南 占水族第二十一（京本列第十二○七首） 七', '兵要望江南 占水族第二十一（京本列第十二○七首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，龜鼈入其營。","盡是頓遲亡（首本作「忘」，此從辛本、川本）敗象，速當移寨免灾凶，不去禍灾（辛本、川本作「將」）生。"]', '["城營內，龟鼈入其營。","尽是頓遲亡（首本作「忘」，此從辛本、川本）敗象，速當移寨免灾凶，不去禍灾（辛本、川本作「將」）生。"]', '诗', 'shi', '', NULL, '兵要望江南 占水族第二十一（京本列第十二○七首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd93af76-40f1-4a64-9ee0-830373dc4601', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占飛鳥，軍旅要知因。","或是縱橫或逐我，或來逆我或成羣，仔細說來情。"]', '["占飞鸟，軍旅要知因。","或是縱橫或逐我，或来逆我或成羣，仔細说来情。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f70d83a-4a12-4815-b6ce-370a465a4610', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鷹搦鷂，勢速入軍營。","必是義兄圖義弟，不然義弟欲謀兄，奸禍兩般情。"]', '["鷹搦鷂，勢速入軍營。","必是義兄圖義弟，不然義弟欲謀兄，奸禍兩般情。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297fd717-d7d2-40e2-b9f5-fa536fdb62a9', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，鷹鶚面（京本作「鷂向」）前飛。","所向進兵應（京本作「須」）大勝，必能捉彼將兵（辛本、川本作「師」、京本作「帥」）歸，天意助神威。"]', '["兵行次，鷹鶚面（京本作「鷂向」）前飞。","所向進兵應（京本作「須」）大勝，必能捉彼將兵（辛本、川本作「師」、京本作「帥」）归，天意助神威。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d19f3c-ee0d-4ee4-8618-1eb2d6a41413', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鷂子搦蒼鷹。","定有奸謀陰禍起，早須排備莫惶驚，有戰損精兵。"]', '["城營內，鷂子搦蒼鷹。","定有奸謀陰禍起，早須排備莫惶驚，有戰損精兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d50f0cea-f599-47ee-8272-3989d19b15f5', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，鷂鶚（京本作「鷹鷂」）捉飛禽。","此去前程須有戰，得其首領盡生擒，主（京本作「上」）將稱其心。"]', '["兵行次，鷂鶚（京本作「鷹鷂」）捉飞禽。","此去前程須有戰，得其首領尽生擒，主（京本作「上」）將稱其心。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf225cf9-c237-42c3-9fdf-19710e027cbe', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，鷹鶻（辛本、川本、京本作「鶻雁」）盡同占。","鷹（辛本、川本、京本作「雁」）不避鶻鶻不搦，兩軍通好守盟言，各擁士回還。"]', '["兵行次，鷹鶻（辛本、川本、京本作「鶻雁」）尽同占。","鷹（辛本、川本、京本作「雁」）不避鶻鶻不搦，兩軍通好守盟言，各擁士回還。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71efab20-23cf-4690-be7b-c991a6800c32', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，忽（京本作「或」）見杜鵑來。","應有負冤人未雪，佞臣謀間損賢才，天遣叫聲哀。","。"]', '["城營內，忽（京本作「或」）见杜鵑来。","應有負冤人未雪，佞臣謀间損賢才，天遣叫声哀。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4d6770b-edb9-4e59-913f-eaa066d87119', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["羣烏（京本作「雀」）噪，隊隊逐（辛本、川本、京本作「遶」）營飛。","防有賊（京本作「外」）兵來劫寨，早須整（京本作「准」）備設關機，遲（京本作「稽」）慢致灾危。"]', '["羣烏（京本作「雀」）噪，隊隊逐（辛本、川本、京本作「遶」）營飞。","防有賊（京本作「外」）兵来劫寨，早須整（京本作「准」）備設关機，遲（京本作「稽」）慢致灾危。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0246629d-cce1-46ba-baf5-9fdcbc109396', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，衆鳥噪聲鳴。","必有暴兵來劫寨，不然有戰損於（辛本、川本作「千」、京本作「戈」）兵，移轉最爲精。"]', '["城營內，衆鸟噪声鳴。","必有暴兵来劫寨，不然有戰損於（辛本、川本作「千」、京本作「戈」）兵，移轉最爲精。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed3217a3-8ba0-43d0-90c6-362227b5b845', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["羣鳥隊，飛去又飛來。","不問（辛本、川本作「以」）下（京本作「在」）營幷在路，此行千里足（京本作「十里走」）難回，仔細察天灾（京本作「威」）。"]', '["羣鸟隊，飞去又飞来。","不问（辛本、川本作「以」）下（京本作「在」）營幷在路，此行千里足（京本作「十里走」）难回，仔細察天灾（京本作「威」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357865db-5d53-4ef2-88ee-ab3b277d6071', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["羣鳥聚（京本作「隊」），飛起忽然驚。","盡向滿天鳴噪鬧，不過三日火燒營，或有劫寨（辛本、川本、京本作「殘」）兵。","（移營吉。","）。"]', '["羣鸟聚（京本作「隊」），飞起忽然驚。","尽向满天鳴噪鬧，不過三日火燒營，或有劫寨（辛本、川本、京本作「殘」）兵。","（移營吉。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf56b5b-d0c3-444d-8899-18cccabdd5bb', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，四面鳥聲鳴（京本作「有鳥聲」）。","千萬結成鳴噪去，急須固守本城營，堅執戰傷兵。"]', '["城營內，四面鸟声鳴（京本作「有鸟声」）。","千万結成鳴噪去，急須固守本城營，堅執戰傷兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af66f823-0faa-4926-86a0-b1535e8080a9', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鳥夜結羣鳴。","必有暴兵來覓戰，不然城寨有虛驚，探後（京本作「候」）用心聽。"]', '["城營內，鸟夜結羣鳴。","必有暴兵来覓戰，不然城寨有虛驚，探後（京本作「候」）用心听。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5996bd22-e34b-4d99-b808-2230d122c223', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鳥衆泊（京本作「拍」）營墻（京本作「壇」）。","頭向此營皆盡叫，人驚不起是天殃，不免（京本作「去」）見傷亡。"]', '["鸟衆泊（京本作「拍」）營墻（京本作「壇」）。","头向此營皆尽叫，人驚不起是天殃，不免（京本作「去」）见傷亡。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545a8c31-2803-4308-920a-4a90660eb28f', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鳥鵲（辛本、川本、京本作「烏鳥」）驀然驚。","內有奸臣連外賊，隄防大（京本、辛本、川本作「苦」）戰血成坑，謀反（京本作「叛」）害英明（川本作「其身」）。"]', '["城營內，鸟鵲（辛本、川本、京本作「烏鸟」）驀然驚。","內有奸臣連外賊，隄防大（京本、辛本、川本作「苦」）戰血成坑，謀反（京本作「叛」）害英明（川本作「其身」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a864ad60-c48a-43e8-8026-a1c3e93b1cb9', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，烏鵲忽圍牆。","當有敵（京本作「外」）兵來打寨，不然疾病大（辛本、川本、京本作「火」）灾殃，營內欲來（京本作「他」）降。"]', '["城營內，烏鵲忽圍牆。","當有敵（京本作「外」）兵来打寨，不然疾病大（辛本、川本、京本作「火」）灾殃，營內欲来（京本作「他」）降。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfd0001-50de-4ba0-bbf6-5432d56a5c1b', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鳥鵲（辛本、川本作「噪」）兩（京本作「叫二」）三聲。","必有命（京本作「使」）來應在即，早須奉候出門迎，此意（京本作「語」）且須聽。","。"]', '["城營內，鸟鵲（辛本、川本作「噪」）兩（京本作「叫二」）三声。","必有命（京本作「使」）来應在即，早須奉候出门迎，此意（京本作「語」）且須听。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc04902-785e-44e2-94f1-06d44eca2c72', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鳥相打（京本作「相打拍」），防撃有奸爭。","斬斷罪愆懲戒衆，若無敵（辛本、川本作「停」）戰禍應生，固守始爲精。"]', '["鸟相打（京本作「相打拍」），防撃有奸爭。","斬斷罪愆懲戒衆，若無敵（辛本、川本作「停」）戰禍應生，固守始爲精。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a45fc1-306a-4910-9411-4a497aebafde', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鳥集奪巢飛。","必有鬬爭相競事，不然下吏欲爲非，防慎見（辛本、川本作「間」）分（京本作「有間相」）離。"]', '["城營內，鸟集奪巢飞。","必有鬬爭相競事，不然下吏欲爲非，防慎见（辛本、川本作「间」）分（京本作「有间相」）離。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1383f34-e08a-4cca-b78d-01af48ede2ed', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，鳥向四方鳴。","選取鳥聲鳴叫（京本作「向」）處，但從（京本作「存」）此地出軍征，百戰百回贏。"]', '["臨陣次，鸟向四方鳴。","選取鸟声鳴叫（京本作「向」）处，但從（京本作「存」）此地出軍征，百戰百回贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1dbe323-183c-4d05-ac66-2908e7c607a7', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，前面有羣烏（首本作「聲鳴」，茲從辛本、川本、京本）。","亂叫亂（辛本、川本、京本作「衆」）鳴防伏截，或（京本作「忽」）然有戰莫先圖，詳緩保（京本作「却」）無虞。"]', '["兵發日，前面有羣烏（首本作「声鳴」，茲從辛本、川本、京本）。","亂叫亂（辛本、川本、京本作「衆」）鳴防伏截，或（京本作「忽」）然有戰莫先圖，詳緩保（京本作「却」）無虞。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd153ea-2324-41d1-8726-17dcfeeddb95', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，鳥衆集旌旗。","若見中軍加喜氣，將軍增爵位遷移，在即不爲遲（京本作「在疾莫遲爲」）。"]', '["兵行次，鸟衆集旌旗。","若见中軍加喜氣，將軍增爵位遷移，在即不爲遲（京本作「在疾莫遲爲」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0761f95a-dab2-4959-b317-6c1445e27a9b', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，鳥衆逐軍行。","未見彼軍防隱伏，若逢敵戰（京本作「陣」）利先征，攻戰必先贏。"]', '["兵發日，鸟衆逐軍行。","未见彼軍防隐伏，若逢敵戰（京本作「陣」）利先征，攻戰必先贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86139e78-a8bf-4314-8ae4-1a15c4b4c925', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵（京本作「軍」）行次，橫陣列鳥來。","防有伏兵衝隊伍（京本作「陣位」），搜羅前後用心猜，不信必爲災。"]', '["兵（京本作「軍」）行次，橫陣列鸟来。","防有伏兵衝隊伍（京本作「陣位」），搜羅前後用心猜，不信必爲災。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670c14c2-2ee1-484c-b4da-5e941b9b9dd7', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，鳥衆後頭來。","若遇前隨應大勝，逆來衝我且宜回，退却免凶灾（辛本、川本、京本作「灾危」）。"]', '["兵行次，鸟衆後头来。","若遇前隨應大勝，逆来衝我且宜回，退却免凶灾（辛本、川本、京本作「灾危」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a92b4853-331a-4dbd-925f-1276709d7fcf', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，鳥立在軍旗。","必有奸人言賊勢，今旬來月好防之，偷（京本作「發」）號運謀機。"]', '["兵行次，鸟立在軍旗。","必有奸人言賊勢，今旬来月好防之，偷（京本作「發」）號運謀機。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b14051-7005-4ed4-b5fd-0e0df250077a', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，軍上鳥鳴飛。","不論下營將布陣，若同此瑞合天機，必勝莫遲疑。"]', '["兵行次，軍上鸟鳴飞。","不論下營將布陣，若同此瑞合天機，必勝莫遲疑。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a3f6376-717f-4733-8fbb-03356f87ef79', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["下營次，鳥衆集牙旗。","急宰三牲將祭禱，不然軍（京本作「兵」）敗主分離，靈物報人知。"]', '["下營次，鸟衆集牙旗。","急宰三牲將祭禱，不然軍（京本作「兵」）敗主分離，靈物報人知。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54791372-42a0-4e32-bd6a-89948fd9089a', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，白鵲（京本作「雀」）入軍營（辛本、川本、京本作「營中」）。","若作巢窩兵大起，急須移寨免災凶，否則禍重重。"]', '["城營內，白鵲（京本作「雀」）入軍營（辛本、川本、京本作「營中」）。","若作巢窩兵大起，急須移寨免災凶，否則禍重重。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd7549e-3f14-4cf5-8f01-df7d586952a1', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，靈鵲（京本作「雀」）件巢窩。","不去營空兼火起，速當移寨禍消磨，久住殺傷多。"]', '["城營內，靈鵲（京本作「雀」）件巢窩。","不去營空兼火起，速當移寨禍消磨，久住殺傷多。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b0ba4f5-5cc1-40cc-af1b-4e292e4c5cc6', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["寨始定，白鵲入營來。","此是金星呈怪象，有人相害處謀乖，移寨免其災。"]', '["寨始定，白鵲入營来。","此是金星呈怪象，有人相害处謀乖，移寨免其災。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c5ba0f5-467f-430a-8af1-046a2f682368', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["羣鵲（京本作「雀」）噪，頭向敵軍營。","隨鵲戰之軍必勝，一般羣鵲（京本作「雀」）事無成，在外也須驚。","（頭指敵噪我軍勝，不指敵噪鬧則虛驚。","）。"]', '["羣鵲（京本作「雀」）噪，头向敵軍營。","隨鵲戰之軍必勝，一般羣鵲（京本作「雀」）事無成，在外也須驚。","（头指敵噪我軍勝，不指敵噪鬧則虛驚。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d812059-64ce-47dc-970b-28eb31703903', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，野雉入軍中。","若在德鄉來即吉，或臨刑殺候爲（京本作「刑或殺帥侯」）凶，仔細審西東。"]', '["城營內，野雉入軍中。","若在德乡来即吉，或臨刑殺候爲（京本作「刑或殺帥侯」）凶，仔細審西东。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57011e37-451d-4787-8bed-dc0b41b2a7ee', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，驀地降鴛鴦。","必有奸人生戶內，不然朋友害忠良，自衛己身強。"]', '["城營內，驀地降鴛鴦。","必有奸人生戶內，不然朋友害忠良，自衛己身強。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959128e7-d948-42e4-9fea-4616df43f476', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，燕鴿忽離城。","定有火災兼禍起，軍中行尅事叮嚀，禳厭始安平。"]', '["城營內，燕鴿忽離城。","定有火災兼禍起，軍中行尅事叮嚀，禳厭始安平。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78dc38de-2027-4be8-a1a3-f1b71be8cc6d', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，水鳥忽啣魚。","將至門橋幷臺屋（京本作「樓臺屋上」），必應大水漫街衢，預辦早防虞（京本作「危」）。"]', '["城營內，水鸟忽啣鱼。","將至门橋幷台屋（京本作「楼台屋上」），必應大水漫街衢，預辦早防虞（京本作「危」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21c6b30c-115e-4703-a12f-431e9d264041', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鴨聲異，一樣似鵝聲（京本作「鳴」）。","鵿有官災幷口舌，速須齋醮慎交爭，方使免灾（京本作「遭」）刑。"]', '["鴨声異，一樣似鵝声（京本作「鳴」）。","鵿有官災幷口舌，速須斋醮慎交爭，方使免灾（京本作「遭」）刑。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28a1e7cb-5db7-440c-b1c9-1628255053ac', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鵝與鴨，或解（京本作「忽辨」）作人聲。","家內必登三品祿（京本作「位」），一門子（辛本、川本作「兒」）姪盡（京本作「更」）享（辛本、川本、京本作「亨」）榮，吉兆自天生。"]', '["鵝與鴨，或解（京本作「忽辨」）作人声。","家內必登三品祿（京本作「位」），一门子（辛本、川本作「兒」）姪尽（京本作「更」）享（辛本、川本、京本作「亨」）榮，吉兆自天生。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de6a584-5355-4a3c-a310-947c0a4ed2c4', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 三十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，雞母作雄聲。","或在夜鳴家（京本作「皆」）有禍，若門（京本作「聞」）陰暗（京本作「口」）不惺惺，禳（京本作「醮」）謝始安寧。"]', '["城營內，雞母作雄声。","或在夜鳴家（京本作「皆」）有禍，若门（京本作「闻」）陰暗（京本作「口」）不惺惺，禳（京本作「醮」）謝始安寧。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 三十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09b8a5c9-b794-40eb-bbd5-32ec5c92b3b5', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵（京本作「軍」）行次，軍上伯勞鳴（京本作「鶯」）。","兆是軍分爲（京本作「鳴兆是軍分」），兩路兼防禍起察奸情，主將要須（京本作「詳」）明。"]', '["兵（京本作「軍」）行次，軍上伯勞鳴（京本作「鶯」）。","兆是軍分爲（京本作「鳴兆是軍分」），兩路兼防禍起察奸情，主將要須（京本作「詳」）明。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d672d346-0c0b-4e81-a330-44eada9fabb0', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["伯勞鳥，鬧噪在軍前。","大禍預（辛本、川本作「須」）知（京本作「將臨」）須早覺，不逾兩月（京本作「日」）事應然，此象理關天。"]', '["伯勞鸟，鬧噪在軍前。","大禍預（辛本、川本作「須」）知（京本作「將臨」）須早覺，不逾兩月（京本作「日」）事應然，此象理关天。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('881968c0-6809-4989-aa27-fb2d1809c230', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["伯勞鳥，啼叫在軍營。","南北敵人困我將，東西只是有虛聲，此象甚分明。"]', '["伯勞鸟，啼叫在軍營。","南北敵人困我將，东西只是有虛声，此象甚分明。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0dca5b-e9df-4b6c-ba2f-339210fe53ba', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，梟鳥噪聲鳴。","若（京本作「如」）在德鄉分隊伍，如居刑殺有奔驚，預叫使人聽。","。"]', '["城營內，梟鸟噪声鳴。","若（京本作「如」）在德乡分隊伍，如居刑殺有奔驚，預叫使人听。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae94a565-7f18-49cd-817c-604e66ba5c56', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["下營次，衆鳥集羣鳴。","如在德鄉猶自可，若臨刑上血成坑，此兆細（京本作「仔細要」）詳聽。"]', '["下營次，衆鸟集羣鳴。","如在德乡猶自可，若臨刑上血成坑，此兆細（京本作「仔細要」）詳听。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d7620b-43a3-47d6-9742-b86d80c9eb74', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，百（京本作「白」）鳥忽迎軍。","此是天威來助順，賊人歸向息邊塵，端的立功勳。"]', '["兵發日，百（京本作「白」）鸟忽迎軍。","此是天威来助順，賊人归向息邊塵，端的立功勳。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b3cd3b-1470-49b1-9a2e-033090c12803', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，衆鳥覆（京本作「巨鳥伏」）於營。","必有大軍來撃我，皂旗黃杆引師行，禳厭必（辛本作「畢」）登程（京本作「早堪程」）。"]', '["兵行次，衆鸟覆（京本作「巨鸟伏」）於營。","必有大軍来撃我，皂旗黄杆引師行，禳厭必（辛本作「畢」）登程（京本作「早堪程」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b958c1-b9c9-47c7-ab0c-cc076c16329d', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行日（京本作「已」），禽乃或（京本作「巨鳥或」）期軍。","將有福神天祐助，必然旬日立功勳，官爵顯超羣。"]', '["兵行日（京本作「已」），禽乃或（京本作「巨鸟或」）期軍。","將有福神天祐助，必然旬日立功勳，官爵显超羣。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b391f195-12c8-43b9-83b3-f5ba585e35f8', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["雞聲鬧（京本作「鬬」），半夜及黃昏。","半夜精兵行在速，黃昏啼後有回軍，太白報人聞。","（衆雞主國事，一雞主家咎。","）。"]', '["雞声鬧（京本作「鬬」），半夜及黄昏。","半夜精兵行在速，黄昏啼後有回軍，太白報人闻。","（衆雞主国事，一雞主家咎。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18dc0e0d-e9a1-4de2-9f36-0722dfbfb75a', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 四十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["燕雀鬧，隣境動（京本作「有」）兵爭。","更有黑頭黃鳥至，腹黃身黑不知名，彼已出精兵。"]', '["燕雀鬧，隣境动（京本作「有」）兵爭。","更有黑头黄鸟至，腹黄身黑不知名，彼已出精兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 四十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdbe791d-6d7e-45e1-8068-05ba619f455a', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，雞鳥共喧爭。","鳥若贏時軍外（京本作「客軍」）勝，雞贏主勝甚分明，偷寨兩般情。"]', '["城營內，雞鸟共喧爭。","鸟若贏时軍外（京本作「客軍」）勝，雞贏主勝甚分明，偷寨兩般情。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ab71fb-7020-4b3c-9da8-6fa86641f924', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鴉鳴（京本作「鳥」）噪，無故噪城營。","此是用兵災欲起（京本作「預兆」），人家被噪有凶情，禍發不安寧。"]', '["鴉鳴（京本作「鸟」）噪，無故噪城營。","此是用兵災欲起（京本作「預兆」），人家被噪有凶情，禍發不安寧。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c0f9d0-6829-4d5d-9586-2ef915a24d68', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鶩（京本作「鶖」）鳥入其城。","定有兵災幷瘴疫，人民饑餓失（京本作「不」）耕耘，修德免災成。"]', '["城營內，鶩（京本作「鶖」）鸟入其城。","定有兵災幷瘴疫，人民饑餓失（京本作「不」）耕耘，修德免災成。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea7ecfe-2a7e-4621-8fad-99f8fde0cb77', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，黃鳥（京本作「牛」）赤其頭。","必有官災三日內，兼防奸叛有因由，熒惑禍堪憂。","（熒惑禍者，火災也。","）。"]', '["城營內，黄鸟（京本作「牛」）赤其头。","必有官災三日內，兼防奸叛有因由，熒惑禍堪憂。","（熒惑禍者，火災也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc96e7eb-90e3-494d-99ec-909e162c2944', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，赤鳥入於（京本作「其」）營。","更有野鷄併野雉，須防風火與虛驚，皂幟厭爲精。","（水剋火，故用皂旗。","如見赤色鳥入軍營，覆將帳幕以皂旗白竿，立帳前三日，厭吉。","）。"]', '["城營內，赤鸟入於（京本作「其」）營。","更有野鷄併野雉，須防风火與虛驚，皂幟厭爲精。","（水剋火，故用皂旗。","如见赤色鸟入軍營，覆將帳幕以皂旗白竿，立帳前三日，厭吉。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06fc237-8032-44b8-b443-23eb86c1a04b', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，大（京本作「各」）鳥遶其中。","不是將軍亡瘴疫，及防外寇損身躬，先兆（京本作「逃」）已呈凶。"]', '["城營內，大（京本作「各」）鸟遶其中。","不是將軍亡瘴疫，及防外寇損身躬，先兆（京本作「逃」）已呈凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40fd8d0e-7010-4541-b1d1-cb32841a2139', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，異鳥或（京本作「忽」）然來。","好慎外歸（京本作「切忌外方」）刑禍事，不然軍（京本作「君」）將主（辛本、川本、京本作「主將」）身灾，齋醮保無（京本作「年」）乖。","。"]', '["城營內，異鸟或（京本作「忽」）然来。","好慎外归（京本作「切忌外方」）刑禍事，不然軍（京本作「君」）將主（辛本、川本、京本作「主將」）身灾，斋醮保無（京本作「年」）乖。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63315ea-0805-4853-b541-184a8a6ecbd0', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，夜靜有鳩鳴。","此是暴兵來逼我，便（京本作「更」）須防備速移營，即得事安寧。"]', '["城營內，夜静有鳩鳴。","此是暴兵来逼我，便（京本作「更」）須防備速移營，即得事安寧。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8c3b5b-e85d-435d-bcf7-fe955559015a', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，衆鳥驀翱翔。","障日翳天成陣起，必知內外將猖狂，仔細可（京本作「好」）消詳。"]', '["城營內，衆鸟驀翱翔。","障日翳天成陣起，必知內外將猖狂，仔細可（京本作「好」）消詳。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b335f22-def0-4d34-b90e-a3f7c1a5aba5', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 五十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["彼軍上，衆鳥泊其中。","定見（京本作「主」）拋營軍敗走，不然潛伏刷營空，仔細審其蹤。"]', '["彼軍上，衆鸟泊其中。","定见（京本作「主」）拋營軍敗走，不然潛伏刷營空，仔細審其蹤。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 五十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('077e8330-1d43-458c-acb5-e985f7c003c0', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["彼軍上，衆鳥鬧紛紛。","聚散只看三五日，不然潛伏擬謀人，防禦始參真。"]', '["彼軍上，衆鸟鬧紛紛。","聚散只看三五日，不然潛伏擬謀人，防禦始參真。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8feac1f5-c02d-4568-babf-26d45eb7cb69', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["諸鳴鳥，不利叫三聲。","一語（辛本、川本、京本作「與」）五聲將快和（京本作「利」），若逢（京本作「過」）此數不堪聽，一任徹更（辛本、川本、京本作「天」）鳴。","（《易》云：「三多凶。","」故不利。","）。"]', '["諸鳴鸟，不利叫三声。","一語（辛本、川本、京本作「與」）五声將快和（京本作「利」），若逢（京本作「過」）此數不堪听，一任徹更（辛本、川本、京本作「天」）鳴。","（《易》云：「三多凶。","」故不利。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b9f7fd4-fcce-4f05-a833-8a155042274d', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占飛鳥，何事（辛本、川本作「處」）入軍營。","若在德鄉加喜氣，只從刑地（京本作「上」）是凶聲，百鳥一般聽。"]', '["占飞鸟，何事（辛本、川本作「处」）入軍營。","若在德乡加喜氣，只從刑地（京本作「上」）是凶声，百鸟一般听。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5441d3bf-072c-451b-b99f-db490ed51a96', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鳥散作巢窩。","其地欲荒堪（京本作「看」）在即，速須移寨莫蹉跎，不去禍來磨（京本作「多」）。"]', '["城營內，鸟散作巢窩。","其地欲荒堪（京本作「看」）在即，速須移寨莫蹉跎，不去禍来磨（京本作「多」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50543c95-12de-4583-ac9c-b03782f99534', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["攻城次，羣鳥出牆頭。","內有敵圍（京本作「人」）軍欲出，外兵急備整戈矛（首本作「干戈」，此從辛本、川本、京本），用意設良籌。"]', '["攻城次，羣鸟出牆头。","內有敵圍（京本作「人」）軍欲出，外兵急備整戈矛（首本作「干戈」，此從辛本、川本、京本），用意設良籌。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aaedda3-c95b-464b-a56f-ff3530ab6264', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，白鳥立旗頭。","相聚數枚人總見，將軍遷位作公侯，吉慶喜天休。"]', '["軍營內，白鸟立旗头。","相聚數枚人總见，將軍遷位作公侯，吉慶喜天休。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bfa10f-510b-452c-8fba-608ac696f538', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鷹與鷂，逐鳥奔吾軍。","前有暴客（辛本、川本、京本作「兵」）來勢猛，速當准備莫因循，常（京本作「當」）守險關津。"]', '["鷹與鷂，逐鸟奔吾軍。","前有暴客（辛本、川本、京本作「兵」）来勢猛，速當准備莫因循，常（京本作「當」）守險关津。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19369756-f95b-4417-9328-c1740532436e', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["下營次，鳥立樹枝間。","或在牙旗毛羽掩（京本作「際」），須防敵騎欲相殘，三日內生奸。"]', '["下營次，鸟立樹枝间。","或在牙旗毛羽掩（京本作「際」），須防敵騎欲相殘，三日內生奸。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c2418d-ed3a-4a00-95e5-223e6d6f0925', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，異鳥入其中。","宿處不知人不識，終（京本作「中」）須血染草頭紅，防備有奸（京本作「妨」）通。"]', '["城營內，異鸟入其中。","宿处不知人不識，終（京本作「中」）須血染草头紅，防備有奸（京本作「妨」）通。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8606553-5d41-4dea-800b-1b7e4d1cfe9f', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 六十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占烏鳥，結伴後（京本作「盡」）隨軍。","路後（川本、京本作「寇」）敵（京本作「賊」）人應過去，我軍不久却回程，相賀喜安平（京本作「寧」）。","。"]', '["占烏鸟，結伴後（京本作「尽」）隨軍。","路後（川本、京本作「寇」）敵（京本作「賊」）人應過去，我軍不久却回程，相賀喜安平（京本作「寧」）。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 六十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11e0152-4ae5-47c3-8d85-cbfde346f1a4', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，巨鳥忽留停。","防備賊人來索（京本作「兵來搦」）戰，兆當催衆早收（京本作「擁士倒抽」）兵，不去禍還成。","（京本注：「三日從始吉。","」）。"]', '["城營內，巨鸟忽留停。","防備賊人来索（京本作「兵来搦」）戰，兆當催衆早收（京本作「擁士倒抽」）兵，不去禍還成。","（京本注：「三日從始吉。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b89a1d4-6ecd-478b-9405-9ee224845a81', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，巨鳥至紛紛。","地（辛本、川本作「他」）分欲荒應在即，早須排備莫留停，號令速驅兵。"]', '["城營內，巨鸟至紛紛。","地（辛本、川本作「他」）分欲荒應在即，早須排備莫留停，號令速驱兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa330d1e-cd91-4c2a-9e69-a80ae879dc33', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，聆（京本作「聽」）取鳥聲鳴。","若在我軍頭上叫，切忌（川本作「須」）備敵莫（京本「須忌取敵」）交兵，在彼我軍贏。"]', '["臨陣次，聆（京本作「听」）取鸟声鳴。","若在我軍头上叫，切忌（川本作「須」）備敵莫（京本「須忌取敵」）交兵，在彼我軍贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d597381-73f7-4ffb-ad4b-c3c6a357a771', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十三', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，鳥向（京本作「鬬」）彼軍飛。","便整旗鎗（京本作「旛」）征敵吉，統兵大帥不須疑，天助得其時。"]', '["臨陣次，鸟向（京本作「鬬」）彼軍飞。","便整旗鎗（京本作「旛」）征敵吉，統兵大帥不須疑，天助得其时。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e859d3b9-4546-4a23-b233-0e90f64b6d19', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十四', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，鳥向敵軍來。","一隻一隻（辛本、川本作「雙」）猶可撃（京本作「自可」），或（京本作「忽」）然成陣叫聲哀，勿戰速當迴。"]', '["臨陣次，鸟向敵軍来。","一隻一隻（辛本、川本作「雙」）猶可撃（京本作「自可」），或（京本作「忽」）然成陣叫声哀，勿戰速當迴。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1624cd3-15b9-4c1e-8a8e-62a5697b7c02', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十五', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["彼軍壘，羣鳥出高飛。","內有雄兵來突我（京本作「將突出」），其城須（辛本、川本、京本作「難」）下速當回，不悟將身危。"]', '["彼軍壘，羣鸟出高飞。","內有雄兵来突我（京本作「將突出」），其城須（辛本、川本、京本作「难」）下速當回，不悟將身危。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712e7411-b104-49de-922f-37b6a1d65435', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十六', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鷄雁（京本作「鷹鷂」）入其中。","必（京本作「的」）有外（京本作「內」）奸通敵事（京本作「外敵」），忽然搦鳥更爲（京本作「尤」）凶，遇戰豈成（京本作「我無」）功。"]', '["城營內，鷄雁（京本作「鷹鷂」）入其中。","必（京本作「的」）有外（京本作「內」）奸通敵事（京本作「外敵」），忽然搦鸟更爲（京本作「尤」）凶，遇戰豈成（京本作「我無」）功。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa771c12-607c-4402-aaef-c33d5ee10516', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十七', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，烏鳥後隨聲。","此是順天天助我，靈禽預報戰須贏，將士有歡情。"]', '["兵發日，烏鸟後隨声。","此是順天天助我，靈禽預報戰須贏，將士有歡情。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4437c697-d3b7-4ad3-8199-9a838acf7ac5', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十八', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，敵上鳥來衝。","進戰必當傷將士，如從我後却宜攻，賊敗定生擒。"]', '["臨陣次，敵上鸟来衝。","進戰必當傷將士，如從我後却宜攻，賊敗定生擒。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab009fb-4aa1-453b-9866-135f24afce73', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十九', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 七十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，夜靜有鳩鳴。","軍欲還鄉宜准備，此爲天意事叮嚀，爲將莫憂驚。"]', '["城營內，夜静有鳩鳴。","軍欲還乡宜准備，此爲天意事叮嚀，爲將莫憂驚。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 七十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('605eb193-00b6-4a27-ba68-afb071d33568', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八十', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 八十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["下營次，鳥衆聚營中。","防有外兵來撃我，亦虞諸將起奸凶，急去莫從容。"]', '["下營次，鸟衆聚營中。","防有外兵来撃我，亦虞諸將起奸凶，急去莫從容。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b60958-bc1d-492a-8514-c0edaccbcbd7', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八十一', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 八十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["他陣上，四面有鳥來。","進戰必因傷將士，若從我陣往前摧，生捉將休猜。"]', '["他陣上，四面有鸟来。","進戰必因傷將士，若從我陣往前摧，生捉將休猜。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eea0c25-bf7e-48ee-8a37-2dea65c04fa3', '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八十二', '兵要望江南 占鸟第二十二（京本作「占飞禽第二十」○八十三首） 八十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵發日，旗後有烏鳴。","此是天教吾得勝，令禽先報我公卿，將士盡歡欣。","（以上三首據京本補。","）。"]', '["兵發日，旗後有烏鳴。","此是天教吾得勝，令禽先報我公卿，將士尽歡欣。","（以上三首據京本補。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占鳥第二十二（京本作「占飛禽第二十」○八十三首） 八十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6898ccd2-08e8-4879-9a6a-337b20b32f49', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 一', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["戈矛上，忽有火光明。","兆主三軍輕命戰，管須（京本作「取」）交戰我軍贏，青焰不宜兵。","（火青焰小如鬼火者主兵憂。","）。"]', '["戈矛上，忽有火光明。","兆主三軍轻命戰，管須（京本作「取」）交戰我軍贏，青焰不宜兵。","（火青焰小如鬼火者主兵憂。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964e7a3b-df35-42ab-9e0b-fe8667a3df18', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["帥衣服，無故血痕班。","防有奸人（京本作「備奸謀」）來害己，急須焚毀禍回還，不爾將（京本作「帥」）遭殃。"]', '["帥衣服，無故血痕班。","防有奸人（京本作「備奸謀」）来害己，急須焚毀禍回還，不爾將（京本作「帥」）遭殃。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9491ef76-8bd3-468d-ab21-cbd79856989f', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["抽刀劍，血點自然生。","戰有大功須在近，又兼鈴鐸不搖（京本作「撝」）鳴，遇戰（京本作「賊」）必須贏。"]', '["抽刀劍，血点自然生。","戰有大功須在近，又兼鈴鐸不搖（京本作「撝」）鳴，遇戰（京本作「賊」）必須贏。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae0c2f7-2ac6-4f2d-a68d-4eeea14f3780', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["出軍日，龍現衆人驚。","急令（京本作「命」）師（京本作「帥」）回休強去（辛本、川本、京本作「進」），若還堅執往前行（京本作「向前營」），枉損馬和兵。"]', '["出軍日，龙現衆人驚。","急令（京本作「命」）師（京本作「帥」）回休強去（辛本、川本、京本作「進」），若還堅執往前行（京本作「向前營」），枉損马和兵。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0714a01f-d57f-4fe8-9add-37f630da056e', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 五', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍帳，無故似人搖。","兆主敵人兵潰散，稍驅兵馬向前交，瓦解與冰消。"]', '["將軍帳，無故似人搖。","兆主敵人兵潰散，稍驱兵马向前交，瓦解與冰消。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b07a5d-7cdf-42ef-ba15-fb127d3b6357', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 六', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍帳，床動衆人驚。","及有血生俱作怪（京本作「怪訝」），若還臨陣禍無輕，身喪掩黃（辛本、川本、京本作「泉」）坰。"]', '["將軍帳，床动衆人驚。","及有血生俱作怪（京本作「怪訝」），若還臨陣禍無轻，身喪掩黄（辛本、川本、京本作「泉」）坰。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('075eda84-14eb-41b6-bcfb-54943e2028ff', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 七', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍袂，驀地起飛騰。","上備將軍傾折象（京本作「逝相」），難禳兵衆敵相凌（京本作「急須禳厭敵相臨」），火急整回程。"]', '["將軍袂，驀地起飞腾。","上備將軍傾折象（京本作「逝相」），难禳兵衆敵相凌（京本作「急須禳厭敵相臨」），火急整回程。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ac35d7-c021-44a5-9402-1cce73fbf68b', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 八', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍纔統（京本作「上」、辛本、川本作「正」），陂澤與郊（京本作「菱」）田。","或有石盤從地湧，此爲吉兆可攻前，君聖（京本作「任」）宰臣賢。"]', '["軍纔統（京本作「上」、辛本、川本作「正」），陂澤與郊（京本作「菱」）田。","或有石盤從地湧，此爲吉兆可攻前，君聖（京本作「任」）宰臣賢。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee75e56-cd16-4d12-bfed-963f7ea44d6f', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 九', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["安營訖，分布已周圍（京本作「依圓」）。","碎石或生無數目，將軍不久罷兵權，天地（京本作「兆」）應昭然。"]', '["安營訖，分布已周圍（京本作「依圓」）。","碎石或生無數目，將軍不久罷兵權，天地（京本作「兆」）應昭然。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0eeba4a-61a7-443f-8cf7-b0f6cc3056d9', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，田地陡然高。","必得敵人來土貢（京本作「城土地」），開旗贏彼不疲勞，休士少（川本作「止」、京本作「要止」）鎗刀。"]', '["軍營內，田地陡然高。","必得敵人来土貢（京本作「城土地」），开旗贏彼不疲勞，休士少（川本作「止」、京本作「要止」）鎗刀。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bceb3a-aa16-4a21-ad2f-7f6b0212e059', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十一', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，元處是平田。","地比始臨微似長，將軍官職必陞遷，祿位享遐年。"]', '["軍營內，元处是平田。","地比始臨微似长，將軍官職必陞遷，祿位享遐年。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da0ecfef-d89b-4523-9d97-d05259bdf564', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十二', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，地上或（京本作「忽」）生黃。","兆（首本作「照」，此從京本）得敵人兵與將，凱旋歸國長威光，天下舉宮商。"]', '["軍營內，地上或（京本作「忽」）生黄。","兆（首本作「照」，此從京本）得敵人兵與將，凱旋归国长威光，天下舉宮商。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e20ef2c8-f12e-4803-a376-92d60c3647c4', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十三', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，氣出地（京本作「應」）中央。","滿寨便教（京本作「交」）人勿訝，敵人怯戰愈乖張，獲將得封疆。"]', '["軍營內，氣出地（京本作「應」）中央。","满寨便教（京本作「交」）人勿訝，敵人怯戰愈乖張，獲將得封疆。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1898d852-51db-4b55-9499-cb4207dea4e2', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十四', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，地上水泉生。","此是潤軍天助順，須當先敵（京本作「預」）將和兵，捷報入朝京。"]', '["軍營內，地上水泉生。","此是潤軍天助順，須當先敵（京本作「預」）將和兵，捷報入朝京。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5659f87d-b6ce-494e-bd00-9d29c3f66f20', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十五', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍止歇（京本作「憇」），地上忽生塵。","若有震聲人總怪，三朝（首本作「日」，此從辛本、川本、京本）五日定還軍（京本作「勒還兵」），大戰苦勞心（辛本作「辛」）。"]', '["軍止歇（京本作「憇」），地上忽生塵。","若有震声人總怪，三朝（首本作「日」，此從辛本、川本、京本）五日定還軍（京本作「勒還兵」），大戰苦勞心（辛本作「辛」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afde480-6b23-4e8c-b0dd-ecb885bf8905', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十六', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍寨內，地上血紛紛。","此象大凶人速避，麻衣布（京本作「履」）帽送將（京本作「三」）軍，休望有功勳。"]', '["軍寨內，地上血紛紛。","此象大凶人速避，麻衣布（京本作「履」）帽送將（京本作「三」）軍，休望有功勳。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af506e05-e773-44ab-a2bf-26e472c80f02', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十七', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，地上艾方（京本作「蒿」）生。","青嫩葉苗人盡識，師徒將捷（京本作「疾」）事非輕，惡疾使人驚。","（七年之病，求三年之艾，故爲病兆。","）。"]', '["軍營內，地上艾方（京本作「蒿」）生。","青嫩葉苗人尽識，師徒將捷（京本作「疾」）事非轻，惡疾使人驚。","（七年之病，求三年之艾，故爲病兆。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4233f96-29af-4cde-a35d-306789bbbfeb', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十八', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["安營內（京本作「畢」），街（京本作「階」）經（京本作「陘」）已編成。","地上忽然土裂坼（辛本、川本、京本作「生拆裂」），不如准備速移營，不信大亡傾。"]', '["安營內（京本作「畢」），街（京本作「階」）經（京本作「陘」）已編成。","地上忽然土裂坼（辛本、川本、京本作「生拆裂」），不如准備速移營，不信大亡傾。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a401a1e7-c21a-49a9-a434-25e6a14127dd', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十九', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營寨內，地陷或（京本作「忽」）成坑。","大陷大虧微小負，俱爲戰敗喪軍情，火速去移營。","。"]', '["營寨內，地陷或（京本作「忽」）成坑。","大陷大虧微小負，俱爲戰敗喪軍情，火速去移營。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e421cf-f683-4b88-9e7b-34e05769cb52', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，地陷幾（京本作「使」）人驚。","若更似催征（京本作「作聲如」）戰鼓，此般凶象速移營，少（辛本、川本、京本作「稍」）緩禍災成。"]', '["軍營內，地陷幾（京本作「使」）人驚。","若更似催征（京本作「作声如」）戰鼓，此般凶象速移營，少（辛本、川本、京本作「稍」）緩禍災成。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d416b55-542b-450f-98b7-e3cdae46c19e', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十一', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城（京本作「軍」）營內，半夜忽鍋鳴。","定有暴兵來劫寨，幷（京本作「兼」）防謀反（京本作「叛」）及奸生，列陣後（京本作「遠」）相迎。"]', '["城（京本作「軍」）營內，半夜忽鍋鳴。","定有暴兵来劫寨，幷（京本作「兼」）防謀反（京本作「叛」）及奸生，列陣後（京本作「远」）相迎。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c180ee89-8b2d-4670-a1a7-e7baf7ffd636', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十二', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，螻蟻滿營生。","好備奸謀陰（京本作「陰奸謀」）禍起，兼虞地道入奸（京本作「城」）兵，早備得平平。"]', '["軍營內，螻蟻满營生。","好備奸謀陰（京本作「陰奸謀」）禍起，兼虞地道入奸（京本作「城」）兵，早備得平平。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ebe32c-c7e4-4220-8ff7-b74685d213c3', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十三', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍邑（京本作「營口」）內，天上忽聞聲。","恰是（京本作「似」）雷聲還不是（京本作「似」），多應（京本作「因」）土地見英（京本作「現陰」）靈，不久（京本作「是」）戰兵行（京本作「興」）。"]', '["軍邑（京本作「營口」）內，天上忽闻声。","恰是（京本作「似」）雷声還不是（京本作「似」），多應（京本作「因」）土地见英（京本作「現陰」）靈，不久（京本作「是」）戰兵行（京本作「兴」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4cbb24-0058-49e4-aa59-1b3c30f57774', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十四', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["諸怪現，不可廣傳聞（京本、辛本、川本作「聲」）。","防有奸人知仔細，亦防（京本作「虞」、川本作「如」）彼內有賢英，知我兆原（京本作「元」）情。"]', '["諸怪現，不可廣傳闻（京本、辛本、川本作「声」）。","防有奸人知仔細，亦防（京本作「虞」、川本作「如」）彼內有賢英，知我兆原（京本作「元」）情。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5088dc28-90b7-42b7-a176-6d2b6c2b1a15', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十五', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城（京本作「軍」）營內，晝夜起虛驚。","營所田（辛本、川本、京本作「舊」）爲神廟地，速移營寨莫居停（京本作「速將移徙莫教停」），不去賊偷營。"]', '["城（京本作「軍」）營內，晝夜起虛驚。","營所田（辛本、川本、京本作「旧」）爲神廟地，速移營寨莫居停（京本作「速將移徙莫教停」），不去賊偷營。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70bebde3-1151-47fd-82cc-69f1ec3c7716', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十六', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，旗鼓自搖鳴。","此是天威來助我，十番出戰九須贏，上將稱其情。"]', '["城營內，旗鼓自搖鳴。","此是天威来助我，十番出戰九須贏，上將稱其情。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a2cb3d-891a-45e1-8fb5-536571489b19', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十七', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鼓角急聲雄。","此是乾坤興廢事，戈矛（京本作「鋋」）大舉禍重重，萬姓失耕農。"]', '["城營內，鼓角急声雄。","此是乾坤兴廢事，戈矛（京本作「鋋」）大舉禍重重，万姓失耕農。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ec6cbb-99d1-4661-a40b-644174158131', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十八', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鼓角自然鳴。","必有敵（京本作「外」）軍來撃我，急須整備待來兵，着意與交征。"]', '["城營內，鼓角自然鳴。","必有敵（京本作「外」）軍来撃我，急須整備待来兵，着意與交征。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十八 易靜 shi');
